export type View = 'tasks' | 'customers' | 'customerDetail';

import { useState, useEffect } from 'react';

export function useLocalStorage<T,>(key: string, initialValue: T): [T, React.Dispatch<React.SetStateAction<T>>] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(error);
      return initialValue;
    }
  });

  useEffect(() => {
    try {
      const valueToStore =
        typeof storedValue === 'function'
          ? storedValue(storedValue)
          : storedValue;
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
    } catch (error) {
      console.error(error);
    }
  }, [key, storedValue]);

  return [storedValue, setStoredValue];
}

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY environment variable not set. Gemini API will not function.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

export const parseTasksFromText = async (text: string): Promise<string[]> => {
    if (!API_KEY) {
        // Fallback for when API key is not available
        return text.split('\n').map(line => line.trim()).filter(line => line.length > 0);
    }

    try {
        const prompt = `Kullanıcının aşağıdaki metnini analiz et ve yapılacak işleri maddeler halinde bir JSON dizisi olarak çıkar. Sadece ve sadece JSON dizisini döndür, başka hiçbir açıklama, metin veya markdown formatı ekleme. Girdi boşsa veya anlamsızsa boş bir dizi döndür.

Örnek Girdi: "yarın sabah depoyu temizle sonra da ahmet'in kumaşlarını bas ve öğleden sonra faturaları düzenle"
Örnek Çıktı: ["Depoyu temizle", "Ahmet'in kumaşlarını bas", "Öğleden sonra faturaları düzenle"]

Kullanıcı Girdisi:
---
${text}
---
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: prompt,
        });

        const jsonString = response.text.trim().replace(/^```json\n?/, '').replace(/```$/, '');

        const tasks = JSON.parse(jsonString);
        if (Array.isArray(tasks) && tasks.every(t => typeof t === 'string')) {
            return tasks;
        }
        throw new Error("Invalid format from API");
    } catch (error) {
        console.error("Error parsing tasks with Gemini:", error);
        // Fallback to simple line-by-line parsing on error
        return text.split('\n').filter(line => line.trim() !== '');
    }
};

