import React, { useState, useRef, useEffect } from 'react';
import type { Task } from '../types';
import { parseTasksFromText } from '../services/geminiService';
import { PlusIcon, MicrophoneIcon, StopIcon, TrashIcon } from './Icons';

interface AddTaskProps {
  onAddTask: (tasks: string[]) => void;
}

const AddTask: React.FC<AddTaskProps> = ({ onAddTask }) => {
  const [text, setText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  useEffect(() => {
    if ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window) {
      const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = true;
      recognitionRef.current.lang = 'tr-TR';
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (event) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          transcript += event.results[i][0].transcript + ' ';
        }
        setText(prev => prev + transcript);
      };

      recognitionRef.current.onerror = (event) => {
        console.error('Speech recognition error', event.error);
        setIsListening(false);
      };

      recognitionRef.current.onend = () => {
        if(isListening) {
           recognitionRef.current?.start();
        }
      }

    } else {
      console.warn('Speech Recognition not supported in this browser.');
    }
  }, [isListening]);

  const handleMicClick = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      if(recognitionRef.current) {
        recognitionRef.current.start();
        setIsListening(true);
      } else {
        alert("Mikrofon desteği bulunamadı.");
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() === '') return;

    setIsLoading(true);
    const newTasks = await parseTasksFromText(text);
    if (newTasks.length > 0) {
      onAddTask(newTasks);
      setText('');
    }
    setIsLoading(false);
  };

  return (
    <form onSubmit={handleSubmit} className="mt-4 p-4 bg-gray-800 rounded-lg shadow-lg">
      <textarea
        className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Görevlerinizi yazın veya mikrofonla söyleyin..."
        disabled={isLoading}
      />
      <div className="flex items-center justify-between mt-3">
        <button
          type="button"
          onClick={handleMicClick}
          className={`p-2 rounded-full transition-colors duration-200 ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
          disabled={isLoading}
        >
          {isListening ? <StopIcon /> : <MicrophoneIcon />}
        </button>
        <button
          type="submit"
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-teal-500 transition-colors disabled:opacity-50"
          disabled={isLoading || text.trim() === ''}
        >
          {isLoading ? 'Ekleniyor...' : <> <PlusIcon /> Görev Ekle </>}
        </button>
      </div>
    </form>
  );
};


interface TaskListScreenProps {
  tasks: Task[];
  setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
}

const TaskListScreen: React.FC<TaskListScreenProps> = ({ tasks, setTasks }) => {
  const handleAddTask = (taskTexts: string[]) => {
    const newTasks: Task[] = taskTexts.map(text => ({
      id: Date.now().toString() + text.slice(0, 5),
      text,
      completed: false,
      createdAt: new Date().toISOString(),
    }));
    setTasks(prevTasks => [...newTasks, ...prevTasks]);
  };

  const toggleTask = (id: string) => {
    setTasks(tasks.map(task => task.id === id ? { ...task, completed: !task.completed } : task));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  return (
    <div>
      <AddTask onAddTask={handleAddTask} />
      <div className="mt-6">
        <h2 className="text-xl font-semibold text-gray-300 mb-3">Yapılacaklar Listesi</h2>
        {tasks.length === 0 ? (
          <p className="text-gray-500 text-center py-4">Henüz görev eklenmemiş.</p>
        ) : (
          <ul className="space-y-3">
            {tasks.map(task => (
              <li key={task.id} className="flex items-center justify-between bg-gray-800 p-4 rounded-lg shadow-md transition-all hover:bg-gray-700">
                <div className="flex items-center flex-1 min-w-0">
                  <input
                    type="checkbox"
                    checked={task.completed}
                    onChange={() => toggleTask(task.id)}
                    className="h-5 w-5 rounded-full bg-gray-700 border-gray-600 text-teal-500 focus:ring-teal-600 cursor-pointer"
                  />
                  <span className={`ml-4 text-gray-300 truncate ${task.completed ? 'line-through text-gray-500' : ''}`}>
                    {task.text}
                  </span>
                </div>
                <button onClick={() => deleteTask(task.id)} className="ml-4 text-gray-500 hover:text-red-500 transition-colors">
                  <TrashIcon />
                </button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default TaskListScreen;

import React, { useState } from 'react';
import type { Customer } from '../types';
import { PlusIcon } from './Icons';

interface CustomerListScreenProps {
  customers: Customer[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onSelectCustomer: (customerId: string) => void;
}

const CustomerListScreen: React.FC<CustomerListScreenProps> = ({ customers, setCustomers, onSelectCustomer }) => {
  const [newCustomerName, setNewCustomerName] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const handleAddCustomer = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCustomerName.trim() === '') return;

    const newCustomer: Customer = {
      id: Date.now().toString(),
      name: newCustomerName.trim(),
      jobs: [],
      paidAmount: 0,
    };
    setCustomers(prev => [newCustomer, ...prev]);
    setNewCustomerName('');
    setIsAdding(false);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  }

  const calculateBalance = (customer: Customer) => {
    const total = customer.jobs.reduce((sum, job) => sum + job.price, 0);
    return total - customer.paidAmount;
  }

  return (
    <div>
      {isAdding ? (
        <form onSubmit={handleAddCustomer} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6">
          <input
            type="text"
            value={newCustomerName}
            onChange={(e) => setNewCustomerName(e.target.value)}
            placeholder="Yeni Müşteri Adı"
            className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
            autoFocus
          />
          <div className="flex justify-end gap-3 mt-3">
             <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-500 transition-colors">
              İptal
            </button>
            <button type="submit" className="px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">
              Ekle
            </button>
          </div>
        </form>
      ) : (
        <div className="text-right mb-4">
          <button onClick={() => setIsAdding(true)} className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900 focus:ring-blue-500 transition-colors">
            <PlusIcon /> Yeni Müşteri
          </button>
        </div>
      )}

      <h2 className="text-xl font-semibold text-gray-300 mb-3">Müşteri Listesi</h2>
      {customers.length === 0 ? (
          <p className="text-gray-500 text-center py-4">Henüz müşteri eklenmemiş.</p>
      ) : (
        <ul className="space-y-3">
          {customers.map(customer => {
            const balance = calculateBalance(customer);
            return (
              <li key={customer.id} onClick={() => onSelectCustomer(customer.id)} className="bg-gray-800 p-4 rounded-lg shadow-md transition-all hover:bg-gray-700 cursor-pointer">
                <div className="flex justify-between items-center">
                  <span className="font-bold text-lg text-gray-200">{customer.name}</span>
                  <span className={`font-semibold px-3 py-1 rounded-full text-sm ${balance > 0 ? 'bg-red-900 text-red-300' : 'bg-green-900 text-green-300'}`}>
                    {formatCurrency(balance)}
                  </span>
                </div>
              </li>
            )
          })}
        </ul>
      )}
    </div>
  );
};

export default CustomerListScreen;

import React, { useState, useMemo } from 'react';
import type { Customer, Job } from '../types';
import { BackIcon, PlusIcon, TrashIcon } from './Icons';

interface CustomerDetailScreenProps {
  customer: Customer;
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onBack: () => void;
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
};

const CustomerDetailScreen: React.FC<CustomerDetailScreenProps> = ({ customer, setCustomers, onBack }) => {
  const [isAddingJob, setIsAddingJob] = useState(false);
  const [newJobName, setNewJobName] = useState('');
  const [newJobPrice, setNewJobPrice] = useState('');
  const [paymentAmount, setPaymentAmount] = useState('');

  const { totalCost, balance } = useMemo(() => {
    const total = customer.jobs.reduce((sum, job) => sum + job.price, 0);
    return {
      totalCost: total,
      balance: total - customer.paidAmount,
    };
  }, [customer]);

  const handleAddJob = (e: React.FormEvent) => {
    e.preventDefault();
    if (newJobName.trim() === '' || !newJobPrice) return;

    const newJob: Job = {
      id: Date.now().toString(),
      name: newJobName.trim(),
      price: parseFloat(newJobPrice),
      createdAt: new Date().toISOString(),
    };

    setCustomers(prev => prev.map(c => 
        c.id === customer.id ? { ...c, jobs: [newJob, ...c.jobs] } : c
    ));
    setNewJobName('');
    setNewJobPrice('');
    setIsAddingJob(false);
  };

  const handleUpdatePayment = (e: React.FormEvent) => {
    e.preventDefault();
    const amount = parseFloat(paymentAmount);
    if (isNaN(amount) || amount <= 0) return;

    setCustomers(prev => prev.map(c => 
        c.id === customer.id ? { ...c, paidAmount: c.paidAmount + amount } : c
    ));
    setPaymentAmount('');
  };

  const deleteJob = (jobId: string) => {
    setCustomers(prev => prev.map(c =>
      c.id === customer.id
        ? { ...c, jobs: c.jobs.filter(job => job.id !== jobId) }
        : c
    ));
  };


  return (
    <div>
      <button onClick={onBack} className="flex items-center gap-2 mb-4 text-teal-400 hover:text-teal-300">
        <BackIcon /> Geri
      </button>

      <div className="bg-gray-800 p-4 rounded-lg shadow-lg mb-6">
        <h2 className="text-2xl font-bold text-center text-teal-400 mb-4">{customer.name}</h2>
        <div className="grid grid-cols-3 gap-4 text-center">
          <div>
            <p className="text-sm text-gray-400">Toplam Tutar</p>
            <p className="text-lg font-semibold text-gray-100">{formatCurrency(totalCost)}</p>
          </div>
          <div>
            <p className="text-sm text-gray-400">Ödenen</p>
            <p className="text-lg font-semibold text-green-400">{formatCurrency(customer.paidAmount)}</p>
          </div>
          <div>
            <p className="text-sm text-gray-400">Kalan Bakiye</p>
            <p className="text-lg font-semibold text-red-400">{formatCurrency(balance)}</p>
          </div>
        </div>

        <form onSubmit={handleUpdatePayment} className="mt-6 flex gap-2">
          <input
            type="number"
            value={paymentAmount}
            onChange={(e) => setPaymentAmount(e.target.value)}
            placeholder="Ödeme Tutarı Ekle"
            className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
          />
          <button type="submit" className="px-4 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 transition-colors">
            Ekle
          </button>
        </form>
      </div>

      <div className="flex justify-between items-center mb-4">
        <h3 className="text-xl font-semibold">İşler</h3>
        <button onClick={() => setIsAddingJob(!isAddingJob)} className="inline-flex items-center gap-2 px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors">
          <PlusIcon /> Yeni İş
        </button>
      </div>

      {isAddingJob && (
        <form onSubmit={handleAddJob} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-3">
          <input
            type="text"
            value={newJobName}
            onChange={(e) => setNewJobName(e.target.value)}
            placeholder="İş Adı"
            className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
            autoFocus
          />
