import { useState, useEffect, Dispatch, SetStateAction } from 'react';

// FIX: Changed return type to use imported Dispatch and SetStateAction to resolve "Cannot find namespace 'React'" error.
export function useLocalStorage<T,>(key: string, initialValue: T): [T, Dispatch<SetStateAction<T>>] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.error(error);
      return initialValue;
    }
  });

  useEffect(() => {
    try {
      const valueToStore =
        typeof storedValue === 'function'
          ? storedValue(storedValue)
          : storedValue;
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
    } catch (error) {
      console.error(error);
    }
  }, [key, storedValue]);

  return [storedValue, setStoredValue];
}

import React, { useState, useRef, useEffect } from 'react';
import type { Task } from '../types';
import { parseTasksFromText } from '../services/geminiService';
import { PlusIcon, MicrophoneIcon, StopIcon, TrashIcon } from './Icons';

interface AddTaskProps {
  onAddTask: (tasks: string[]) => void;
}

const AddTask: React.FC<AddTaskProps> = ({ onAddTask }) => {
  const [text, setText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  // FIX: Changed the type of recognitionRef to `any` to fix "Cannot find name 'SpeechRecognition'" error.
  const recognitionRef = useRef<any | null>(null);

  useEffect(() => {
    if ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window) {
      // FIX: Cast window to `any` to access non-standard SpeechRecognition properties.
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = true;
      recognitionRef.current.lang = 'tr-TR';
      recognitionRef.current.interimResults = false;

      recognitionRef.current.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          transcript += event.results[i][0].transcript + ' ';
        }
        setText(prev => prev + transcript);
      };

      recognitionRef.current.onerror = (event: any) => {
        console.error('Speech recognition error', event.error);
        setIsListening(false);
      };

      recognitionRef.current.onend = () => {
        if(isListening) {
           recognitionRef.current?.start();
        }
      }

    } else {
      console.warn('Speech Recognition not supported in this browser.');
    }
  }, [isListening]);

  const handleMicClick = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      if(recognitionRef.current) {
        recognitionRef.current.start();
        setIsListening(true);
      } else {
        alert("Mikrofon desteği bulunamadı.");
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() === '') return;

    setIsLoading(true);
    const newTasks = await parseTasksFromText(text);
    if (newTasks.length > 0) {
      onAddTask(newTasks);
      setText('');
    }
    setIsLoading(false);
  };

  return (
    <form onSubmit={handleSubmit} className="mt-4 p-4 bg-gray-800 rounded-lg shadow-lg">
      <textarea
        className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Görevlerinizi yazın veya mikrofonla söyleyin..."
        disabled={isLoading}
      />
      <div className="flex items-center justify-between mt-3">
        <button
          type="button"
          onClick={handleMicClick}
          className={`p-2 rounded-full transition-colors duration-200 ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
          disabled={isLoading}
        >
          {isListening ? <StopIcon /> : <MicrophoneIcon />}
        </button>
        <button
          type="submit"
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-teal-500 transition-colors disabled:opacity-50"
          disabled={isLoading || text.trim() === ''}
        >
          {isLoading ? 'Ekleniyor...' : <> <PlusIcon /> Görev Ekle </>}
        </button>
      </div>
    </form>
  );
};


