      patternName: newJobPatternName !== patterns[0].name ? newJobPatternName : undefined,
      photos: [],
      estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
    };

    setCustomers(prev => prev.map(c => 
        c.id === customer.id ? { ...c, jobs: [newJob, ...c.jobs] } : c
    ));
    resetForm();
    setShowToast(true);
  };

  const handleDeleteRequest = (jobId: string) => setJobToDelete(jobId);

  const handleConfirmDelete = () => {
    if (!jobToDelete) return;
    setCustomers(prev => prev.map(c =>
      c.id === customer.id ? { ...c, jobs: c.jobs.filter(job => job.id !== jobToDelete) } : c
    ));
    setJobToDelete(null);
  };

