import React, { useState, useEffect } from 'react';
import type { Customer, Task, View, Pattern } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
import CustomerListScreen from './components/CustomerListScreen';
import CustomerDetailScreen from './components/CustomerDetailScreen';
import TaskListScreen from './components/TaskListScreen';
import PatternManagementScreen from './components/PatternManagementScreen';
import { CustomersIcon, TasksIcon, PatternIcon } from './components/Icons';

const defaultPatterns: Pattern[] = [
    { id: '1', name: 'Düz Baskı', pricePerMeter: 15, image: 'https://via.placeholder.com/150/10B981/FFFFFF?text=Düz' },
    { id: '2', name: 'Desenli A', pricePerMeter: 25, image: 'https://via.placeholder.com/150/3B82F6/FFFFFF?text=Desenli+A' },
    { id: '3', name: 'Desenli B (Simli)', pricePerMeter: 35, image: 'https://via.placeholder.com/150/F59E0B/FFFFFF?text=Simli' },
    { id: '4', name: 'Özel Tasarım', pricePerMeter: 50, image: 'https://via.placeholder.com/150/8B5CF6/FFFFFF?text=Özel' },
];

const App: React.FC = () => {
  const [customers, setCustomers] = useLocalStorage<Customer[]>('customers', []);
  const [tasks, setTasks] = useLocalStorage<Task[]>('tasks', []);
  const [patterns, setPatterns] = useLocalStorage<Pattern[]>('patterns', defaultPatterns);
  const [currentView, setCurrentView] = useState<View>('tasks');
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);

  useEffect(() => {
    const interval = setInterval(() => {
      const incompleteTasks = tasks.filter(t => !t.completed);
      if (incompleteTasks.length > 0) {
        // In a real app, this would use the Notification API.
        // For this environment, alert is a simple alternative.
        console.log(`Hatırlatma: ${incompleteTasks.length} adet tamamlanmamış göreviniz var.`);
      }
    }, 30 * 60 * 1000); // Remind every 30 minutes

    return () => clearInterval(interval);
  }, [tasks]);

  const handleSelectCustomer = (customerId: string) => {
    setSelectedCustomerId(customerId);
    setCurrentView('customerDetail');
  };

  const handleBackToList = () => {
    setSelectedCustomerId(null);
    setCurrentView('customers');
  };

  const renderContent = () => {
    switch (currentView) {
      case 'tasks':
        return <TaskListScreen tasks={tasks} setTasks={setTasks} />;
      case 'customers':
        return (
          <CustomerListScreen
            customers={customers}
            setCustomers={setCustomers}
            onSelectCustomer={handleSelectCustomer}
          />
        );
      case 'customerDetail':
        const selectedCustomer = customers.find(c => c.id === selectedCustomerId);
        if (selectedCustomer) {
          return (
            <CustomerDetailScreen
              customer={selectedCustomer}
              setCustomers={setCustomers}
              onBack={handleBackToList}
              patterns={patterns}
            />
          );
        }
        // Fallback if customer not found
        handleBackToList();
        return null;
      case 'patterns':
        return <PatternManagementScreen patterns={patterns} setPatterns={setPatterns} />;
      default:
        return <TaskListScreen tasks={tasks} setTasks={setTasks} />;
    }
  };

  // FIX: Changed icon type from JSX.Element to React.ReactElement to resolve "Cannot find namespace 'JSX'" error.
  const NavButton = ({ view, label, icon }: { view: View, label: string, icon: React.ReactElement }) => (
    <button
      onClick={() => setCurrentView(view)}
      className={`flex flex-col items-center justify-center w-full pt-2 pb-1 transition-colors duration-200 ${currentView === view || (view === 'customers' && currentView === 'customerDetail') ? 'text-teal-400' : 'text-gray-400 hover:text-teal-300'}`}
    >
      {icon}
      <span className="text-xs mt-1">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col h-screen font-sans">
      <header className="bg-gray-800 shadow-md p-4 text-center">
        <h1 className="text-2xl font-bold text-teal-400">İş Takip Asistanı</h1>
      </header>
      <main className="flex-grow overflow-y-auto p-4 pb-20 bg-gray-900">
        {renderContent()}
      </main>
      <nav className="fixed bottom-0 left-0 right-0 bg-gray-800 border-t border-gray-700 shadow-lg flex justify-around">
        <NavButton view="tasks" label="Görevler" icon={<TasksIcon />} />
        <NavButton view="customers" label="Müşteriler" icon={<CustomersIcon />} />
        <NavButton view="patterns" label="Kalıplar" icon={<PatternIcon />} />
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import type { Customer, Job, Pattern } from '../types';
import { BackIcon, PlusIcon, TrashIcon, CameraIcon, EditIcon } from './Icons';
import ConfirmationModal from './ConfirmationModal';
import Toast from './Toast';

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
};

const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
    });
};


interface JobItemProps {
    job: Job;
    customerId: string;
    setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
    onDeleteRequest: (jobId: string) => void;
}

const JobItem: React.FC<JobItemProps> = ({ job, customerId, setCustomers, onDeleteRequest }) => {
    const [paymentAmount, setPaymentAmount] = useState('');
    const balance = job.price - job.paidAmount;

    const handleAddPayment = (e: React.FormEvent) => {
        e.preventDefault();
        const amount = parseFloat(paymentAmount);
        if(isNaN(amount) || amount <= 0) return;

        setCustomers(prevCustomers => prevCustomers.map(c => {
            if (c.id === customerId) {
                return {
                    ...c,
                    jobs: c.jobs.map(j => 
                        j.id === job.id ? { ...j, paidAmount: Math.min(j.price, j.paidAmount + amount) } : j
                    )
                };
            }
            return c;
        }));
        setPaymentAmount('');
    };

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            const files = Array.from(e.target.files);
            const base64Photos = await Promise.all(files.map(fileToBase64));

            setCustomers(prev => prev.map(c => {
                if (c.id === customerId) {
                    return {
                        ...c,
                        jobs: c.jobs.map(j => 
                            j.id === job.id ? { ...j, photos: [...(j.photos || []), ...base64Photos] } : j
                        )
                    };
                }
                return c;
            }));
        }
    };

    const formatTime = (minutes?: number) => {
        if (minutes === undefined) return 'N/A';
        const hours = Math.floor(minutes / 60);
        const mins = minutes % 60;
        return `${hours > 0 ? `${hours} sa ` : ''}${mins} dk`;
    };

    return (
        <li className="bg-gray-800 p-4 rounded-lg shadow-md space-y-4">
            <div className="flex justify-between items-start">
                <div>
                     <p className="font-semibold text-lg text-gray-200 flex items-center gap-2">
                        {job.name}
                        {job.discountAmount && job.discountAmount > 0 && (
                            <span className="text-xs bg-teal-600 text-teal-100 font-bold px-2 py-0.5 rounded-full">
                                {formatCurrency(job.discountAmount)} İndirim
                            </span>
                        )}
                    </p>
                    <p className="text-sm text-gray-400">{job.patternName || 'Desen Belirtilmemiş'} - {job.fabricLength || '0'}m</p>
                    <p className="text-xs text-gray-500">Tahmini Süre: {formatTime(job.estimatedTimeMinutes)}</p>
                </div>
                <button onClick={() => onDeleteRequest(job.id)} className="text-gray-500 hover:text-red-500 transition-colors" aria-label="İşi Sil">
                    <TrashIcon />
                </button>
            </div>

            {job.photos && job.photos.length > 0 && (
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                    {job.photos.map((photo, index) => (
                        <a key={index} href={photo} target="_blank" rel="noopener noreferrer">
                            <img src={photo} alt={`Job photo ${index + 1}`} className="rounded-md object-cover aspect-square" />
                        </a>
                    ))}
                </div>
            )}

            <div className="grid grid-cols-3 gap-2 text-center border-t border-b border-gray-700 py-3">
                <div><p className="text-xs text-gray-400">Fiyat</p><p className="font-semibold text-gray-100">{formatCurrency(job.price)}</p></div>
                <div><p className="text-xs text-gray-400">Ödenen</p><p className="font-semibold text-green-400">{formatCurrency(job.paidAmount)}</p></div>
                <div><p className="text-xs text-gray-400">Kalan</p><p className={`font-semibold ${balance > 0 ? 'text-red-400' : 'text-green-400'}`}>{formatCurrency(balance)}</p></div>
            </div>

            <div className="flex gap-2 items-center">
                <form onSubmit={handleAddPayment} className="flex-grow flex gap-2">
                    <input type="number" step="0.01" value={paymentAmount} onChange={(e) => setPaymentAmount(e.target.value)} placeholder="Ödeme Tutarı" className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none w-full min-w-0" />
                    <button type="submit" className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 transition-colors disabled:opacity-50" disabled={!paymentAmount}>Ekle</button>
                </form>
                <label className="cursor-pointer p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500 transition-colors"><CameraIcon /><input type="file" multiple accept="image/*" className="hidden" onChange={handlePhotoUpload} /></label>
            </div>
        </li>
    );
};


interface CustomerDetailScreenProps {
  customer: Customer;
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onBack: () => void;
  patterns: Pattern[];
}

const CustomerDetailScreen: React.FC<CustomerDetailScreenProps> = ({ customer, setCustomers, onBack, patterns }) => {
  const [isAddingJob, setIsAddingJob] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [showToast, setShowToast] = useState(false);
  const [isEditingName, setIsEditingName] = useState(false);
  const [editedName, setEditedName] = useState(customer.name);


  // New Job Form State
  const [newJobName, setNewJobName] = useState('');
  const [newJobFabricLength, setNewJobFabricLength] = useState('');
  const [newJobPatternName, setNewJobPatternName] = useState(patterns.length > 0 ? patterns[0].name : '');
  const [newJobDiscountAmount, setNewJobDiscountAmount] = useState('');
  const [newJobPrice, setNewJobPrice] = useState('');

  const { priceCalculation, timeCalculation } = useMemo(() => {
    const length = parseFloat(newJobFabricLength);
    const pattern = patterns.find(p => p.name === newJobPatternName);
    const discount = parseFloat(newJobDiscountAmount) || 0;

    if (isNaN(length) || !pattern || length <= 0) {
        return { priceCalculation: 0, timeCalculation: 0 };
    }
    const basePrice = length * pattern.pricePerMeter;
    const finalPrice = basePrice - discount;

    return {
        priceCalculation: Math.max(0, finalPrice),
        timeCalculation: Math.round((length / 100) * 20)
    };
  }, [newJobFabricLength, newJobPatternName, newJobDiscountAmount, patterns]);

  useEffect(() => {
      setNewJobPrice(priceCalculation.toFixed(2).toString());
  }, [priceCalculation]);

  useEffect(() => {
    setEditedName(customer.name);
  }, [customer.name]);

  const resetForm = () => {
    setNewJobName('');
    setNewJobFabricLength('');
    setNewJobPatternName(patterns.length > 0 ? patterns[0].name : '');
    setNewJobDiscountAmount('');
    setNewJobPrice('');
    setIsAddingJob(false);
  };

  const handleAddJob = (e: React.FormEvent) => {
    e.preventDefault();
    const price = parseFloat(newJobPrice);
    if (newJobName.trim() === '' || isNaN(price) || price < 0) return;

    const newJob: Job = {
      id: Date.now().toString(),
      name: newJobName.trim(),
      price: price,
      paidAmount: 0,
      createdAt: new Date().toISOString(),
      fabricLength: parseFloat(newJobFabricLength) || undefined,
      patternName: newJobPatternName,
      photos: [],
      estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
      discountAmount: parseFloat(newJobDiscountAmount) > 0 ? parseFloat(newJobDiscountAmount) : undefined,
    };

    setCustomers(prev => prev.map(c => 
        c.id === customer.id ? { ...c, jobs: [newJob, ...c.jobs] } : c
    ));
    resetForm();
    setShowToast(true);
  };

  const handleDeleteRequest = (jobId: string) => setJobToDelete(jobId);

  const handleConfirmDelete = () => {
    if (!jobToDelete) return;
    setCustomers(prev => prev.map(c =>
      c.id === customer.id ? { ...c, jobs: c.jobs.filter(job => job.id !== jobToDelete) } : c
    ));
    setJobToDelete(null);
  };

  const handleSaveName = () => {
    if (editedName.trim() === '') return;
    setCustomers(prev => prev.map(c => 
      c.id === customer.id ? { ...c, name: editedName.trim() } : c
    ));
    setIsEditingName(false);
  };

  return (
    <div>
      <Toast message="Lütfen taşların yeterli olduğunu kontrol edin." show={showToast} onClose={() => setShowToast(false)} />
      <div className="flex justify-between items-center mb-4">
        <button onClick={onBack} className="flex items-center gap-2 text-teal-400 hover:text-teal-300"><BackIcon /> Geri</button>
        {isEditingName ? (
            <div className="flex-grow flex items-center gap-2 mx-2">
                <input type="text" value={editedName} onChange={(e) => setEditedName(e.target.value)} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 text-2xl font-bold focus:ring-2 focus:ring-teal-500 focus:outline-none" autoFocus />
                <button onClick={handleSaveName} className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500">Kaydet</button>
                <button onClick={() => setIsEditingName(false)} className="px-3 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-500">İptal</button>
            </div>
        ) : (
             <div className="flex items-center gap-3">
                <h2 className="text-2xl font-bold text-teal-400 text-center truncate">{customer.name}</h2>
                <button onClick={() => setIsEditingName(true)} className="text-gray-400 hover:text-white"><EditIcon /></button>
            </div>
        )}
        <div className="w-16"></div>
      </div>

      <div className="flex justify-between items-center my-6">
        <h3 className="text-xl font-semibold">İşler</h3>
        <button onClick={() => setIsAddingJob(!isAddingJob)} className="inline-flex items-center gap-2 px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors"><PlusIcon /> {isAddingJob ? 'Kapat' : 'Yeni İş'}</button>
      </div>

      {isAddingJob && (
        <form onSubmit={handleAddJob} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-3">
          <input type="text" value={newJobName} onChange={(e) => setNewJobName(e.target.value)} placeholder="İş Adı (Örn: Siyah Penye)" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" autoFocus required />
          <div className="flex gap-2">
            <input type="number" value={newJobFabricLength} onChange={(e) => setNewJobFabricLength(e.target.value)} placeholder="Metraj (m)" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
            <select value={newJobPatternName} onChange={(e) => setNewJobPatternName(e.target.value)} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" disabled={patterns.length === 0}>
                {patterns.length === 0 ? <option>Lütfen Kalıp Ekleyin</option> : patterns.map(p => <option key={p.id} value={p.name}>{p.name} ({formatCurrency(p.pricePerMeter)}/m)</option>)}
            </select>
          </div>
           <div className="flex gap-2">
            <input type="number" step="0.01" value={newJobDiscountAmount} onChange={(e) => setNewJobDiscountAmount(e.target.value)} placeholder="İskonto Tutarı (TRY)" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
            <input type="number" value={newJobPrice} onChange={(e) => setNewJobPrice(e.target.value)} placeholder="Nihai Fiyat (TRY)" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
          </div>
          {timeCalculation > 0 && <p className="text-xs text-center text-gray-400">Tahmini Süre: {Math.floor(timeCalculation / 60)} sa {timeCalculation % 60} dk</p>}
          <div className="flex justify-end"><button type="submit" className="px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">İş Ekle</button></div>
        </form>
      )}

      <ul className="space-y-4">
        {customer.jobs.length > 0 ? customer.jobs.map(job => (<JobItem key={job.id} job={job} customerId={customer.id} setCustomers={setCustomers} onDeleteRequest={handleDeleteRequest}/>)) : <p className="text-gray-500 text-center py-4">Bu müşteri için henüz iş eklenmemiş.</p>}
      </ul>

      <ConfirmationModal isOpen={!!jobToDelete} onClose={() => setJobToDelete(null)} onConfirm={handleConfirmDelete} title="İşi Silmeyi Onayla"><p>Bu işi kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p></ConfirmationModal>
    </div>
  );
};

