    const [patternName, setPatternName] = useState(job.patternName || (patterns.length > 0 ? patterns[0].name : ''));
    const [discountAmount, setDiscountAmount] = useState(job.discountAmount?.toString() || '');
    const [price, setPrice] = useState(job.price.toString());

