import React, { useState } from 'react';
import type { Customer } from '../types';
import { PlusIcon } from './Icons';

interface CustomerListScreenProps {
  customers: Customer[];
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onSelectCustomer: (customerId: string) => void;
}

const CustomerListScreen: React.FC<CustomerListScreenProps> = ({ customers, setCustomers, onSelectCustomer }) => {
  const [newCustomerName, setNewCustomerName] = useState('');
  const [isAdding, setIsAdding] = useState(false);

  const handleAddCustomer = (e: React.FormEvent) => {
    e.preventDefault();
    if (newCustomerName.trim() === '') return;

    const newCustomer: Customer = {
      id: Date.now().toString(),
      name: newCustomerName.trim(),
      jobs: [],
    };
    setCustomers(prev => [newCustomer, ...prev]);
    setNewCustomerName('');
    setIsAdding(false);
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  }

  const calculateBalance = (customer: Customer) => {
    return customer.jobs.reduce((totalBalance, job) => {
      return totalBalance + (job.price - job.paidAmount);
    }, 0);
  }

  const renderBalance = (balance: number) => {
    if (balance > 0) {
      return (
        <div className="text-center">
            <p className="text-sm text-gray-400">Bakiye</p>
            <p className="font-semibold text-xl text-red-400">{formatCurrency(balance)}</p>
        </div>
      );
    }
    if (balance < 0) {
      return (
        <div className="text-center">
             <p className="text-sm text-blue-300">Alacaklı</p>
            <p className="font-semibold text-xl text-blue-400">{formatCurrency(Math.abs(balance))}</p>
        </div>
      );
    }
    return (
        <div className="text-center">
            <p className="text-sm text-gray-400">Bakiye</p>
            <p className="font-semibold text-xl text-green-400">{formatCurrency(0)}</p>
        </div>
    );
  };

  return (
    <div>
      {isAdding ? (
        <form onSubmit={handleAddCustomer} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6">
          <input
            type="text"
            value={newCustomerName}
            onChange={(e) => setNewCustomerName(e.target.value)}
            placeholder="Yeni Müşteri Adı"
            className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
            autoFocus
          />
          <div className="flex justify-end gap-3 mt-3">
             <button type="button" onClick={() => setIsAdding(false)} className="px-4 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-500 transition-colors">
              İptal
            </button>
            <button type="submit" className="px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">
              Ekle
            </button>
          </div>
        </form>
      ) : (
        <div className="text-right mb-4">
          <button onClick={() => setIsAdding(true)} className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900 focus:ring-blue-500 transition-colors">
            <PlusIcon /> Yeni Müşteri
          </button>
        </div>
      )}

      <h2 className="text-xl font-semibold text-gray-300 mb-3">Müşteri Listesi</h2>
      {customers.length === 0 ? (
          <p className="text-gray-500 text-center py-4">Henüz müşteri eklenmemiş.</p>
      ) : (
        <div className="grid grid-cols-2 gap-4">
          {customers.map(customer => {
            const balance = calculateBalance(customer);
            return (
              <div key={customer.id} onClick={() => onSelectCustomer(customer.id)} className="bg-gray-800 p-4 rounded-lg shadow-md transition-all hover:bg-gray-700 hover:shadow-teal-500/20 cursor-pointer flex flex-col justify-between aspect-square">
                <h3 className="font-bold text-lg text-center text-gray-200 truncate">{customer.name}</h3>
                {renderBalance(balance)}
              </div>
            )
          })}
        </div>
      )}
    </div>
  );
};

export default CustomerListScreen;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import type { Customer, Job, Pattern } from '../types';
import { BackIcon, PlusIcon, TrashIcon, CameraIcon, EditIcon, SaveIcon } from './Icons';
import ConfirmationModal from './ConfirmationModal';
import Toast from './Toast';
import PatternSelectorModal from './PatternSelectorModal';

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
};

const compressAndEncodeImage = (file: File, maxDimension: number = 800, quality: number = 0.7): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            if (!event.target?.result) {
                return reject(new Error("FileReader failed to read file."));
            }
            const img = new Image();
            img.src = event.target.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let { width, height } = img;

                if (width > height) {
                    if (width > maxDimension) {
                        height = Math.round((height * maxDimension) / width);
                        width = maxDimension;
                    }
                } else {
                    if (height > maxDimension) {
                        width = Math.round((width * maxDimension) / height);
                        height = maxDimension;
                    }
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    return reject(new Error('Could not get 2D context from canvas.'));
                }
                ctx.drawImage(img, 0, 0, width, height);

                // For photos, JPEG provides better compression than PNG.
                const dataUrl = canvas.toDataURL('image/jpeg', quality);
                resolve(dataUrl);
            };
            img.onerror = (err) => reject(err);
        };
        reader.onerror = (err) => reject(err);
    });
};

const PatternDisplayButton: React.FC<{
    patterns: Pattern[];
    value: string;
    onClick: () => void;
    disabled?: boolean;
}> = ({ patterns, value, onClick, disabled }) => {
    const selectedPattern = patterns.find(p => p.name === value);

    if (patterns.length === 0) {
        return <div className="w-full bg-gray-700 text-gray-400 rounded-md p-2 text-center">Lütfen Kalıp Ekleyin</div>;
    }

    return (
        <button type="button" onClick={onClick} disabled={disabled} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 flex items-center justify-between focus:ring-2 focus:ring-teal-500 focus:outline-none disabled:opacity-50 text-left">
            {selectedPattern ? (
                <>
                    <div className="flex items-center gap-2">
                        <img src={selectedPattern.image || `https://via.placeholder.com/150/4B5563/FFFFFF?text=${encodeURIComponent(selectedPattern.name)}`} alt={selectedPattern.name} className="h-6 w-6 rounded-sm object-cover" />
                        <span className="truncate">{selectedPattern.name}</span>
                    </div>
                    <span className="text-xs text-gray-400">{formatCurrency(selectedPattern.pricePerMeter)}/m</span>
                </>
            ) : <span className="text-gray-400">Kalıp Seçiniz...</span>}
        </button>
    );
};


// Job Edit Form Component
const EditJobForm: React.FC<{
    job: Job;
    patterns: Pattern[];
    onSave: (updatedJob: Job) => void;
    onCancel: () => void;
}> = ({ job, patterns, onSave, onCancel }) => {
    const [name, setName] = useState(job.name);
    const [fabricLength, setFabricLength] = useState(job.fabricLength?.toString() || '');
    const [patternName, setPatternName] = useState(job.patternName || (patterns.length > 0 ? patterns[0].name : ''));
    const [discountAmount, setDiscountAmount] = useState(job.discountAmount?.toString() || '');
    const [price, setPrice] = useState(job.price.toString());
    const [isPatternModalOpen, setIsPatternModalOpen] = useState(false);

    const { priceCalculation, timeCalculation } = useMemo(() => {
        const length = parseFloat(fabricLength);
        const pattern = patterns.find(p => p.name === patternName);
        const discount = parseFloat(discountAmount) || 0;
        if (isNaN(length) || !pattern || length <= 0) return { priceCalculation: 0, timeCalculation: 0 };
        const basePrice = length * pattern.pricePerMeter;
        const finalPrice = basePrice - discount;
        return {
            priceCalculation: finalPrice,
            timeCalculation: Math.round((length / 100) * 20)
        };
    }, [fabricLength, patternName, discountAmount, patterns]);

    useEffect(() => {
        setPrice(priceCalculation.toFixed(2).toString());
    }, [priceCalculation]);

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        const finalPrice = parseFloat(price);
        if (name.trim() === '' || isNaN(finalPrice)) return;

        const updatedJob: Job = {
            ...job,
            name: name.trim(),
            price: finalPrice,
            fabricLength: parseFloat(fabricLength) || undefined,
            patternName: patternName,
            discountAmount: parseFloat(discountAmount) > 0 ? parseFloat(discountAmount) : undefined,
            estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
        };
        onSave(updatedJob);
    };

    const handlePatternSelect = (pattern: Pattern) => {
        setPatternName(pattern.name);
        setIsPatternModalOpen(false);
    };

    return (
        <>
            <form onSubmit={handleSave} className="bg-gray-700 p-4 rounded-lg shadow-md space-y-3">
                <h4 className="text-lg font-semibold text-teal-400 border-b border-gray-600 pb-2 mb-3">İşi Düzenle</h4>
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="İş Adı" className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                <div className="flex gap-2">
                    <input type="number" value={fabricLength} onChange={(e) => setFabricLength(e.target.value)} placeholder="Metraj (m)" className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <PatternDisplayButton patterns={patterns} value={patternName} onClick={() => setIsPatternModalOpen(true)} />
                </div>
                <div className="flex gap-2">
                    <input type="number" step="0.01" value={discountAmount} onChange={(e) => setDiscountAmount(e.target.value)} placeholder="İskonto Tutarı (TRY)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <input type="number" value={price} onChange={(e) => setPrice(e.target.value)} placeholder="Nihai Fiyat (TRY)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                </div>
                {timeCalculation > 0 && <p className="text-xs text-center text-gray-400">Tahmini Süre: {Math.floor(timeCalculation / 60)} sa {timeCalculation % 60} dk</p>}
                <div className="flex justify-end gap-2"><button type="button" onClick={onCancel} className="px-3 py-1 bg-gray-500 text-white font-semibold rounded-lg hover:bg-gray-400">İptal</button><button type="submit" className="px-3 py-1 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 flex items-center gap-1"><SaveIcon/> Kaydet</button></div>
            </form>
            <PatternSelectorModal isOpen={isPatternModalOpen} patterns={patterns} onSelect={handlePatternSelect} onClose={() => setIsPatternModalOpen(false)} />
        </>
    );
};


interface JobItemProps {
    job: Job;
    customerId: string;
    setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
    onDeleteRequest: (jobId: string) => void;
    isEditing: boolean;
    onEditRequest: (jobId: string) => void;
    onSave: (job: Job) => void;
    onCancel: () => void;
    patterns: Pattern[];
}

const JobItem: React.FC<JobItemProps> = ({ job, customerId, setCustomers, onDeleteRequest, isEditing, onEditRequest, onSave, onCancel, patterns }) => {
    const [paymentAmount, setPaymentAmount] = useState('');
    const balance = job.price - job.paidAmount;

    const handleAddPayment = (e: React.FormEvent) => {
        e.preventDefault();
        const amount = parseFloat(paymentAmount);
        if(isNaN(amount) || amount <= 0) return;

        setCustomers(prevCustomers => prevCustomers.map(c => {
            if (c.id === customerId) {
                return { ...c, jobs: c.jobs.map(j => j.id === job.id ? { ...j, paidAmount: j.paidAmount + amount } : j) };
            }
            return c;
        }));
        setPaymentAmount('');
    };

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files) {
            const files = Array.from(e.target.files);
            const base64Photos = await Promise.all(files.map(file => compressAndEncodeImage(file)));
            setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, jobs: c.jobs.map(j => j.id === job.id ? { ...j, photos: [...(j.photos || []), ...base64Photos] } : j) } : c));
        }
    };

    const formatTime = (minutes?: number) => {
        if (minutes === undefined) return 'N/A';
        const hours = Math.floor(minutes / 60);
        const mins = minutes % 60;
        return `${hours > 0 ? `${hours} sa ` : ''}${mins} dk`;
    };

    if (isEditing) {
        return <li className="bg-gray-800 p-0 rounded-lg shadow-md"><EditJobForm job={job} patterns={patterns} onSave={onSave} onCancel={onCancel} /></li>
    }

    const balanceColor = balance > 0 ? 'text-red-400' : balance < 0 ? 'text-blue-400' : 'text-green-400';

    return (
        <li className="bg-gray-800 p-4 rounded-lg shadow-md space-y-4">
            <div className="flex justify-between items-start">
                <div>
                     <p className="font-semibold text-lg text-gray-200 flex items-center gap-2">
                        {job.name}
                        {job.discountAmount && job.discountAmount > 0 && (<span className="text-xs bg-teal-600 text-teal-100 font-bold px-2 py-0.5 rounded-full">{formatCurrency(job.discountAmount)} İndirim</span>)}
                    </p>
                    <p className="text-sm text-gray-400">{job.patternName || 'Desen Belirtilmemiş'} - {job.fabricLength || '0'}m</p>
                    <p className="text-xs text-gray-500">Tahmini Süre: {formatTime(job.estimatedTimeMinutes)}</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => onEditRequest(job.id)} className="text-gray-500 hover:text-teal-400 transition-colors" aria-label="İşi Düzenle"><EditIcon /></button>
                    <button onClick={() => onDeleteRequest(job.id)} className="text-gray-500 hover:text-red-500 transition-colors" aria-label="İşi Sil"><TrashIcon /></button>
                </div>
            </div>

            {job.photos && job.photos.length > 0 && (<div className="grid grid-cols-3 sm:grid-cols-4 gap-2">{job.photos.map((photo, index) => (<a key={index} href={photo} target="_blank" rel="noopener noreferrer"><img src={photo} alt={`Job photo ${index + 1}`} className="rounded-md object-cover aspect-square" /></a>))}</div>)}
            <div className="grid grid-cols-3 gap-2 text-center border-t border-b border-gray-700 py-3">
                <div><p className="text-xs text-gray-400">Fiyat</p><p className="font-semibold text-gray-100">{formatCurrency(job.price)}</p></div>
                <div><p className="text-xs text-gray-400">Ödenen</p><p className="font-semibold text-green-400">{formatCurrency(job.paidAmount)}</p></div>
                <div><p className="text-xs text-gray-400">Kalan</p><p className={`font-semibold ${balanceColor}`}>{formatCurrency(balance)}</p></div>
            </div>
            <div className="flex gap-2 items-center">
                <form onSubmit={handleAddPayment} className="flex-grow flex gap-2">
                    <input type="number" step="0.01" value={paymentAmount} onChange={(e) => setPaymentAmount(e.target.value)} placeholder="Ödeme Tutarı" className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none w-full min-w-0" />
                    <button type="submit" className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 transition-colors disabled:opacity-50" disabled={!paymentAmount}>Ekle</button>
                </form>
                <label className="cursor-pointer p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500 transition-colors"><CameraIcon /><input type="file" multiple accept="image/*" className="hidden" onChange={handlePhotoUpload} /></label>
            </div>
        </li>
    );
};


interface CustomerDetailScreenProps {
  customer: Customer;
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onBack: () => void;
  patterns: Pattern[];
}

const CustomerDetailScreen: React.FC<CustomerDetailScreenProps> = ({ customer, setCustomers, onBack, patterns }) => {
  const [isAddingJob, setIsAddingJob] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [showToast, setShowToast] = useState(false);
  const [isEditingName, setIsEditingName] = useState(false);
  const [editedName, setEditedName] = useState(customer.name);
  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isPatternModalOpen, setIsPatternModalOpen] = useState(false);

  // New Job Form State
  const [newJobName, setNewJobName] = useState('');
  const [newJobFabricLength, setNewJobFabricLength] = useState('');
  const [newJobPatternName, setNewJobPatternName] = useState(patterns.length > 0 ? patterns[0].name : '');
  const [newJobDiscountAmount, setNewJobDiscountAmount] = useState('');
  const [newJobPrice, setNewJobPrice] = useState('');

  const { priceCalculation, timeCalculation } = useMemo(() => {
    const length = parseFloat(newJobFabricLength);
    const pattern = patterns.find(p => p.name === newJobPatternName);
    const discount = parseFloat(newJobDiscountAmount) || 0;
    if (isNaN(length) || !pattern || length <= 0) return { priceCalculation: 0, timeCalculation: 0 };
    const basePrice = length * pattern.pricePerMeter;
    const finalPrice = basePrice - discount;
    return {
        priceCalculation: finalPrice,
        timeCalculation: Math.round((length / 100) * 20)
    };
  }, [newJobFabricLength, newJobPatternName, newJobDiscountAmount, patterns]);

  useEffect(() => { setNewJobPrice(priceCalculation.toFixed(2).toString()); }, [priceCalculation]);
  useEffect(() => { setEditedName(customer.name); }, [customer.name]);

  const resetForm = () => {
    setNewJobName('');
    setNewJobFabricLength('');
    setNewJobPatternName(patterns.length > 0 ? patterns[0].name : '');
    setNewJobDiscountAmount('');
    setNewJobPrice('');
    setIsAddingJob(false);
  };

  const handlePatternSelect = (pattern: Pattern) => {
    setNewJobPatternName(pattern.name);
    setIsPatternModalOpen(false);
  };

  const handleAddJob = (e: React.FormEvent) => {
    e.preventDefault();
    const price = parseFloat(newJobPrice);
    if (newJobName.trim() === '' || isNaN(price)) return;
    const newJob: Job = {
      id: Date.now().toString(),
      name: newJobName.trim(),
      price: price, paidAmount: 0, createdAt: new Date().toISOString(),
      fabricLength: parseFloat(newJobFabricLength) || undefined,
      patternName: newJobPatternName, photos: [],
      estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
      discountAmount: parseFloat(newJobDiscountAmount) > 0 ? parseFloat(newJobDiscountAmount) : undefined,
    };
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: [newJob, ...c.jobs] } : c));
    resetForm();
    setShowToast(true);
  };

  const handleSaveJob = (updatedJob: Job) => {
    setCustomers(prevCustomers => prevCustomers.map(c => {
        if (c.id === customer.id) {
            return { ...c, jobs: c.jobs.map(j => j.id === updatedJob.id ? updatedJob : j) };
        }
        return c;
    }));
    setEditingJobId(null);
  };

  const handleDeleteRequest = (jobId: string) => setJobToDelete(jobId);
  const handleConfirmDelete = () => {
    if (!jobToDelete) return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: c.jobs.filter(job => job.id !== jobToDelete) } : c));
    setJobToDelete(null);
  };

  const handleSaveName = () => {
    if (editedName.trim() === '') return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, name: editedName.trim() } : c));
    setIsEditingName(false);
  };

  return (
    <div>
      <Toast message="Lütfen taşların yeterli olduğunu kontrol edin." show={showToast} onClose={() => setShowToast(false)} />
      <div className="flex justify-between items-center mb-4">
        <button onClick={onBack} className="flex items-center gap-2 text-teal-400 hover:text-teal-300"><BackIcon /> Geri</button>
        {isEditingName ? (
            <div className="flex-grow flex items-center gap-2 mx-2">
                <input type="text" value={editedName} onChange={(e) => setEditedName(e.target.value)} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 text-2xl font-bold focus:ring-2 focus:ring-teal-500 focus:outline-none" autoFocus />
                <button onClick={handleSaveName} className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500">Kaydet</button>
                <button onClick={() => setIsEditingName(false)} className="px-3 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-500">İptal</button>
            </div>
        ) : (
             <div className="flex items-center gap-3">
                <h2 className="text-2xl font-bold text-teal-400 text-center truncate">{customer.name}</h2>
                <button onClick={() => setIsEditingName(true)} className="text-gray-400 hover:text-white"><EditIcon /></button>
            </div>
        )}
        <div className="w-16"></div>
      </div>

      <div className="flex justify-between items-center my-6">
        <h3 className="text-xl font-semibold">İşler</h3>
        <button onClick={() => setIsAddingJob(!isAddingJob)} className="inline-flex items-center gap-2 px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors"><PlusIcon /> {isAddingJob ? 'Kapat' : 'Yeni İş'}</button>
      </div>

      {isAddingJob && (
        <form onSubmit={handleAddJob} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-3">
          <input type="text" value={newJobName} onChange={(e) => setNewJobName(e.target.value)} placeholder="İş Adı (Örn: Siyah Penye)" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
          <div className="flex gap-2">
            <input type="number" value={newJobFabricLength} onChange={(e) => setNewJobFabricLength(e.target.value)} placeholder="Metraj (m)" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
             <PatternDisplayButton patterns={patterns} value={newJobPatternName} onClick={() => setIsPatternModalOpen(true)} />
          </div>
           <div className="flex gap-2">
            <input type="number" step="0.01" value={newJobDiscountAmount} onChange={(e) => setNewJobDiscountAmount(e.target.value)} placeholder="İskonto Tutarı (TRY)" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
            <input type="number" value={newJobPrice} onChange={(e) => setNewJobPrice(e.target.value)} placeholder="Nihai Fiyat (TRY)" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
          </div>
          {timeCalculation > 0 && <p className="text-xs text-center text-gray-400">Tahmini Süre: {Math.floor(timeCalculation / 60)} sa {timeCalculation % 60} dk</p>}
          <div className="flex justify-end"><button type="submit" className="px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">İş Ekle</button></div>
        </form>
      )}
      <PatternSelectorModal isOpen={isPatternModalOpen} patterns={patterns} onSelect={handlePatternSelect} onClose={() => setIsPatternModalOpen(false)} />

      <ul className="space-y-4">
        {customer.jobs.length > 0 ? customer.jobs.map(job => (<JobItem key={job.id} job={job} customerId={customer.id} setCustomers={setCustomers} onDeleteRequest={handleDeleteRequest} isEditing={editingJobId === job.id} onEditRequest={setEditingJobId} onSave={handleSaveJob} onCancel={() => setEditingJobId(null)} patterns={patterns} />)) : <p className="text-gray-500 text-center py-4">Bu müşteri için henüz iş eklenmemiş.</p>}
      </ul>

      <ConfirmationModal isOpen={!!jobToDelete} onClose={() => setJobToDelete(null)} onConfirm={handleConfirmDelete} title="İşi Silmeyi Onayla"><p>Bu işi kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p></ConfirmationModal>
    </div>
  );
};

export default CustomerDetailScreen;

