    onSave: (updatedJob: Job) => void;
    onCancel: () => void;
}> = ({ job, patterns, onSave, onCancel }) => {
    const [name, setName] = useState(job.name);
    const [fabricLength, setFabricLength] = useState(job.fabricLength?.toString() || '');
    const [patternName, setPatternName] = useState(job.patternName || (patterns.length > 0 ? patterns[0].name : ''));
    const [discountAmount, setDiscountAmount] = useState(job.discountAmount?.toString() || '');
    const [price, setPrice] = useState(job.price.toString());
    const [notes, setNotes] = useState(job.notes || '');
    const [isPatternModalOpen, setIsPatternModalOpen] = useState(false);

    const { priceCalculation, timeCalculation } = useMemo(() => {
        const length = parseFloat(fabricLength);
        const pattern = patterns.find(p => p.name === patternName);
        const discount = parseFloat(discountAmount) || 0;
        if (isNaN(length) || !pattern || length <= 0) return { priceCalculation: 0, timeCalculation: 0 };
        const basePrice = length * pattern.pricePerMeter;
        const finalPrice = basePrice - discount;
        return {
            priceCalculation: finalPrice,
            timeCalculation: Math.round((length / 100) * 20)
        };
    }, [fabricLength, patternName, discountAmount, patterns]);

    useEffect(() => {
        setPrice(priceCalculation.toFixed(2).toString());
    }, [priceCalculation]);

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        const finalPrice = parseFloat(price);
        if (name.trim() === '' || isNaN(finalPrice)) return;

        const updatedJob: Job = {
            ...job,
            name: name.trim(),
            price: finalPrice,
            fabricLength: parseFloat(fabricLength) || undefined,
            patternName: patternName,
            discountAmount: parseFloat(discountAmount) > 0 ? parseFloat(discountAmount) : undefined,
            estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
            notes: notes.trim(),
        };
        onSave(updatedJob);
    };

    const handlePatternSelect = (pattern: Pattern) => {
        setPatternName(pattern.name);
        setIsPatternModalOpen(false);
    };

    return (
        <>
            <form onSubmit={handleSave} className="bg-gray-700 p-4 rounded-lg shadow-md space-y-3">
                <h4 className="text-lg font-semibold text-teal-400 border-b border-gray-600 pb-2 mb-3">İşi Düzenle</h4>
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="İş Adı" className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                <div className="flex gap-2">
                    <input type="number" value={fabricLength} onChange={(e) => setFabricLength(e.target.value)} placeholder="Metraj (m)" className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <PatternDisplayButton patterns={patterns} value={patternName} onClick={() => setIsPatternModalOpen(true)} />
                </div>
                <div className="flex gap-2">
                    <input type="number" step="0.01" value={discountAmount} onChange={(e) => setDiscountAmount(e.target.value)} placeholder="İskonto Tutarı (TRY)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <input type="number" value={price} onChange={(e) => setPrice(e.target.value)} placeholder="Nihai Fiyat (TRY)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                </div>
                <textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="İş ile ilgili notlar..." className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" rows={3} />
                {timeCalculation > 0 && <p className="text-xs text-center text-gray-400">Tahmini Süre: {Math.floor(timeCalculation / 60)} sa {timeCalculation % 60} dk</p>}
                <div className="flex justify-end gap-2"><button type="button" onClick={onCancel} className="px-3 py-1 bg-gray-500 text-white font-semibold rounded-lg hover:bg-gray-400">İptal</button><button type="submit" className="px-3 py-1 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 flex items-center gap-1"><SaveIcon/> Kaydet</button></div>
            </form>
            <PatternSelectorModal isOpen={isPatternModalOpen} patterns={patterns} onSelect={handlePatternSelect} onClose={() => setIsPatternModalOpen(false)} />
        </>
    );
};


interface JobItemProps {
    job: Job;
    customerId: string;
    setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
    onDeleteRequest: (jobId: string) => void;
    onImageClick: (imageUrl: string) => void;
    isEditing: boolean;
    onEditRequest: (jobId: string) => void;
    onSave: (job: Job) => void;
    onCancel: () => void;
    patterns: Pattern[];
}

const JobItem: React.FC<JobItemProps> = ({ job, customerId, setCustomers, onDeleteRequest, onImageClick, isEditing, onEditRequest, onSave, onCancel, patterns }) => {
    const [paymentAmount, setPaymentAmount] = useState('');
    const [notesVisible, setNotesVisible] = useState(false);
    const balance = job.price - job.paidAmount;

    const handleAddPayment = (e: React.FormEvent) => {
        e.preventDefault();
        const amount = parseFloat(paymentAmount);
        if(isNaN(amount) || amount <= 0) return;

        setCustomers(prevCustomers => prevCustomers.map(c => {
            if (c.id === customerId) {
                return { ...c, jobs: c.jobs.map(j => j.id === job.id ? { ...j, paidAmount: j.paidAmount + amount } : j) };
            }
            return c;
        }));
        setPaymentAmount('');
    };

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const files = Array.from(e.target.files);
            const base64Photos = await Promise.all(files.map((file: File) => compressAndEncodeImage(file)));
            setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, jobs: c.jobs.map(j => j.id === job.id ? { ...j, photos: [...(j.photos || []), ...base64Photos] } : j) } : c));
        }
    };

    const formatTime = (minutes?: number) => {
        if (minutes === undefined) return 'N/A';
        const hours = Math.floor(minutes / 60);
        const mins = minutes % 60;
        return `${hours > 0 ? `${hours} sa ` : ''}${mins} dk`;
    };

    if (isEditing) {
        return <li className="bg-gray-800 p-0 rounded-lg shadow-md"><EditJobForm job={job} patterns={patterns} onSave={onSave} onCancel={onCancel} /></li>
    }

    const balanceColor = balance > 0 ? 'text-red-400' : balance < 0 ? 'text-blue-400' : 'text-green-400';

    return (
        <li className="bg-gray-800 p-4 rounded-lg shadow-md space-y-4">
            <div className="flex justify-between items-start">
                <div>
                     <p className="font-semibold text-lg text-gray-200 flex items-center gap-2">
                        {job.name}
                        {job.discountAmount && job.discountAmount > 0 && (<span className="text-xs bg-teal-600 text-teal-100 font-bold px-2 py-0.5 rounded-full">{formatCurrency(job.discountAmount)} İndirim</span>)}
                    </p>
                    <p className="text-sm text-gray-400">
                        {formatDate(job.createdAt)} &bull; {job.patternName || 'Desen Belirtilmemiş'} - {job.fabricLength || '0'}m
                    </p>
                    <p className="text-xs text-gray-500">Tahmini Süre: {formatTime(job.estimatedTimeMinutes)}</p>
                </div>
                <div className="flex gap-2">
                    <button onClick={() => onEditRequest(job.id)} className="text-gray-500 hover:text-teal-400 transition-colors" aria-label="İşi Düzenle"><EditIcon /></button>
                    <button onClick={() => onDeleteRequest(job.id)} className="text-gray-500 hover:text-red-500 transition-colors" aria-label="İşi Sil"><TrashIcon /></button>
                </div>
            </div>

            {job.photos && job.photos.length > 0 && (<div className="grid grid-cols-3 sm:grid-cols-4 gap-2">{job.photos.map((photo, index) => (<button key={index} onClick={() => onImageClick(photo)} className="focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-teal-500 rounded-md"><img src={photo} alt={`Job photo ${index + 1}`} className="rounded-md object-cover aspect-square" /></button>))}</div>)}

            {job.notes && (
                <div className="border-t border-gray-700 pt-3">
                    <button 
                        onClick={() => setNotesVisible(!notesVisible)}
                        className="flex items-center gap-2 text-sm text-teal-400 font-semibold w-full text-left"
                    >
                        <NoteIcon /> Notları {notesVisible ? 'Gizle' : 'Göster'}
                    </button>
                    {notesVisible && (
                        <div className="mt-2 p-3 bg-gray-700/50 rounded-md">
                            <pre className="text-gray-300 text-sm whitespace-pre-wrap font-sans">{job.notes}</pre>
                        </div>
                    )}
                </div>
            )}

            <div className="grid grid-cols-3 gap-2 text-center border-t border-b border-gray-700 py-3">
                <div><p className="text-xs text-gray-400">Fiyat</p><p className="font-semibold text-gray-100">{formatCurrency(job.price)}</p></div>
                <div><p className="text-xs text-gray-400">Ödenen</p><p className="font-semibold text-green-400">{formatCurrency(job.paidAmount)}</p></div>
                <div><p className="text-xs text-gray-400">Kalan</p><p className={`font-semibold ${balanceColor}`}>{formatCurrency(balance)}</p></div>
            </div>

            <div className="flex gap-2 items-center">
                <form onSubmit={handleAddPayment} className="flex-grow flex gap-2">
                    <input type="number" step="0.01" value={paymentAmount} onChange={(e) => setPaymentAmount(e.target.value)} placeholder="Ödeme Tutarı" className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none w-full min-w-0" />
                    <button type="submit" className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 transition-colors disabled:opacity-50" disabled={!paymentAmount}>Ekle</button>
                </form>
                <label title="Galeriden Yükle" className="cursor-pointer p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500 transition-colors"><ImageIcon /><input type="file" multiple accept="image/*" className="hidden" onChange={handlePhotoUpload} /></label>
                <label title="Fotoğraf Çek" className="cursor-pointer p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 transition-colors"><CameraIcon /><input type="file" accept="image/*" capture="environment" className="hidden" onChange={handlePhotoUpload} /></label>
            </div>
        </li>
    );
};


interface CustomerDetailScreenProps {
  customer: Customer;
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onBack: () => void;
  patterns: Pattern[];
}

const CustomerDetailScreen: React.FC<CustomerDetailScreenProps> = ({ customer, setCustomers, onBack, patterns }) => {
  const [isAddingJob, setIsAddingJob] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [toastInfo, setToastInfo] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

  // Customer Name Edit State
  const [isEditingName, setIsEditingName] = useState(false);
  const [editedName, setEditedName] = useState(customer.name);

  // Customer Info Edit State
  const [isEditingInfo, setIsEditingInfo] = useState(false);
  const [editedPhone, setEditedPhone] = useState(customer.phone || '');
  const [editedContact, setEditedContact] = useState(customer.contactPerson || '');
  const [editedAddress, setEditedAddress] = useState(customer.address || '');
  const [editedLocation, setEditedLocation] = useState(customer.location);
  const [isFetchingLocation, setIsFetchingLocation] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false);

  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [isPatternModalOpen, setIsPatternModalOpen] = useState(false);
  const [lightboxImage, setLightboxImage] = useState<string | null>(null);

  // New Job Form State
  const [newJobName, setNewJobName] = useState('');
  const [newJobFabricLength, setNewJobFabricLength] = useState('');
  const [newJobPatternName, setNewJobPatternName] = useState(patterns.length > 0 ? patterns[0].name : '');
  const [newJobDiscountAmount, setNewJobDiscountAmount] = useState('');
  const [newJobPrice, setNewJobPrice] = useState('');
  const [newJobNotes, setNewJobNotes] = useState('');

  const { priceCalculation, timeCalculation } = useMemo(() => {
    const length = parseFloat(newJobFabricLength);
    const pattern = patterns.find(p => p.name === newJobPatternName);
    const discount = parseFloat(newJobDiscountAmount) || 0;
    if (isNaN(length) || !pattern || length <= 0) return { priceCalculation: 0, timeCalculation: 0 };
    const basePrice = length * pattern.pricePerMeter;
    const finalPrice = basePrice - discount;
    return {
        priceCalculation: finalPrice,
        timeCalculation: Math.round((length / 100) * 20)
    };
  }, [newJobFabricLength, newJobPatternName, newJobDiscountAmount, patterns]);

  useEffect(() => { setNewJobPrice(priceCalculation.toFixed(2).toString()); }, [priceCalculation]);
  useEffect(() => { 
    setEditedName(customer.name);
    setEditedPhone(customer.phone || '');
    setEditedContact(customer.contactPerson || '');
    setEditedAddress(customer.address || '');
    setEditedLocation(customer.location);
  }, [customer]);

  const resetForm = () => {
    setNewJobName(''); setNewJobFabricLength(''); setNewJobPatternName(patterns.length > 0 ? patterns[0].name : '');
    setNewJobDiscountAmount(''); setNewJobPrice(''); setNewJobNotes(''); setIsAddingJob(false);
  };

  const handlePatternSelect = (pattern: Pattern) => { setNewJobPatternName(pattern.name); setIsPatternModalOpen(false); };

  const handleAddJob = (e: React.FormEvent) => {
    e.preventDefault();
    const price = parseFloat(newJobPrice);
    if (newJobName.trim() === '' || isNaN(price)) return;
    const newJob: Job = {
      id: Date.now().toString(), name: newJobName.trim(), price: price, paidAmount: 0, createdAt: new Date().toISOString(),
      fabricLength: parseFloat(newJobFabricLength) || undefined, patternName: newJobPatternName, photos: [],
      estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
      discountAmount: parseFloat(newJobDiscountAmount) > 0 ? parseFloat(newJobDiscountAmount) : undefined,
      notes: newJobNotes.trim(),
    };
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: [newJob, ...c.jobs] } : c));
    resetForm();
    setToastInfo({ message: "Yeni iş başarıyla eklendi.", type: 'success' });
  };

  const handleSaveJob = (updatedJob: Job) => {
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: c.jobs.map(j => j.id === updatedJob.id ? updatedJob : j) } : c));
    setEditingJobId(null);
  };

  const handleDeleteRequest = (jobId: string) => setJobToDelete(jobId);
  const handleConfirmDelete = () => {
    if (!jobToDelete) return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: c.jobs.filter(job => job.id !== jobToDelete) } : c));
    setJobToDelete(null);
  };

  const handleSaveName = () => {
    if (editedName.trim() === '') return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, name: editedName.trim() } : c));
    setIsEditingName(false);
  };

  const handleSaveInfo = () => {
    setCustomers(prev => prev.map(c => c.id === customer.id ? { 
        ...c, 
        phone: editedPhone.trim(),
        contactPerson: editedContact.trim(),
        address: editedAddress.trim(),
        location: editedLocation
     } : c));
    setIsEditingInfo(false);
