import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY environment variable not set. Gemini API will not function.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

export const parseTasksFromText = async (text: string): Promise<string[]> => {
    if (!API_KEY) {
        // Fallback for when API key is not available
        return text.split('\n').map(line => line.trim()).filter(line => line.length > 0);
    }

    try {
        const systemInstruction = `Sen, tekstil baskı sektöründe faaliyet gösteren üst düzey bir şirketin elit yönetici asistanısın. Görevin, kullanıcının karmaşık, günlük dildeki notlarını analiz edip, bunları net, eyleme geçirilebilir ve mantıksal olarak gruplandırılmış görev listesine dönüştürmektir.

Kuralların:
1.  **İlişkili Eylemleri Birleştir:** Birbiriyle bağlantılı adımları (kes, bas, paketle, kargola gibi) tek bir kapsamlı görev olarak birleştir. Örneğin, "Ahmet'in kumaşını bas, sonra paketle" ifadesini "Ahmet'in kumaşını basıp paketlemek" olarak tek bir görev yap.
2.  **Net ve Eylem Odaklı Ol:** Her görevi bir eylem fiili ile başlat. Belirsiz ifadeleri netleştir. "Depo düzenlenecek" yerine "Depoyu düzenlemek" de.
3.  **Gereksiz Bilgileri Filtrele:** Sohbet, yorum veya görev olmayan ifadeleri (örn: "bugün çok yoruldum", "umarım yetişir") tamamen yok say. Sadece somut eylemleri çıkar.
4.  **Sadece JSON Döndür:** Çıktın her zaman '{"tasks": ["görev1", "görev2", ...]}' formatında bir JSON nesnesi olmalı. Başka hiçbir metin, açıklama veya markdown ekleme. Girdi anlamsızsa veya görev içermiyorsa '{"tasks": []}' döndür.

Örnek 1:
Kullanıcı Girdisi: "ahmetin 100 metre siyah penyesini bas sonra paketle ve kargoya ver faturaları da kesmeyi unutma"
Çıktı: {"tasks": ["Ahmet'in 100m siyah penyesini basıp, paketleyerek kargoya vermek", "Faturaları kesmek"]}

Örnek 2:
Kullanıcı Girdisi: "selam, bugün çok iş var. önce depoyu bi düzenleyelim. öğleden sonra da yeni gelen kalıpları sisteme girmemiz lazım."
Çıktı: {"tasks": ["Depoyu düzenlemek", "Yeni gelen kalıpları sisteme girmek"]}

Örnek 3:
Kullanıcı Girdisi: "belki yarın ararım"
Çıktı: {"tasks": []}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Kullanıcı Girdisi:\n---\n${text}\n---`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
            },
        });

        const jsonString = response.text.trim();
        const parsed = JSON.parse(jsonString);

        if (parsed && Array.isArray(parsed.tasks) && parsed.tasks.every(t => typeof t === 'string')) {
            return parsed.tasks;
        }

        throw new Error("Invalid format from API. Expected { tasks: [...] }");

    } catch (error) {
        console.error("Error parsing tasks with Gemini:", error);
        // Fallback to simple line-by-line parsing on error
        return text.split('\n').filter(line => line.trim() !== '');
    }
};

export interface Pattern {
