// This defines the structure we expect from the AI model
interface ParsedTask {
    task: string;
    dueDate: string | null; // ISO 8601 format
    location: string | null;
}

export const parseTasksFromText = async (text: string): Promise<ParsedTask[]> => {
    if (!API_KEY) {
        // Fallback for when API key is not available, returns a simplified structure
        return text.split('\n').map(line => ({
            task: line.trim(),
            dueDate: null,
            location: null
        })).filter(item => item.task.length > 0);
    }

    try {
        const currentDate = new Date().toISOString();
        const systemInstruction = `Sen, tekstil baskı sektöründe faaliyet gösteren üst düzey bir şirketin elit, proaktif ve akıllı yönetici asistanısın. Görevin, kullanıcının karmaşık, günlük dildeki notlarını analiz edip, bunları net, eyleme geçirilebilir ve zenginleştirilmiş görev objelerine dönüştürmektir.

Kuralların:
1.  **İlişkili Eylemleri Birleştir:** Birbiriyle bağlantılı adımları (kes, bas, paketle, kargola gibi) tek bir kapsamlı görev olarak birleştir.
2.  **Tarih ve Saati Algıla ve Dönüştür:** Metindeki göreceli zaman ifadelerini ("yarın saat 10'da", "akşam 5'te", "2 saat sonra", "cuma günü") algıla. Mevcut tarih ve saati (${currentDate}) baz alarak bu ifadeleri MUTLAKA tam bir ISO 8601 formatına (YYYY-MM-DDTHH:mm:ss.sssZ) çevir. Eğer tarih/saat belirtilmemişse, dueDate değerini null yap.
3.  **Konum Bilgisini Çıkar:** Metindeki belirgin mekan, adres veya şirket isimlerini ("XYZ Kumaşçılık'a uğra", "Sultanahmet'teki atölye") algıla ve location alanına yaz. Konum yoksa, location değerini null yap.
4.  **Netleştir ve Eylem Odaklı Ol:** Her görevi bir eylem fiili ile başlat. Belirsiz ifadeleri netleştir.
5.  **Gereksiz Bilgileri Filtrele:** Sohbet, yorum veya görev olmayan ifadeleri tamamen yok say.
6.  **Sadece JSON Döndür:** Çıktın her zaman '{"tasks": [{"task": "...", "dueDate": "...", "location": "..."}, ...]}' formatında bir JSON nesnesi olmalı. Başka hiçbir metin veya açıklama ekleme. Girdi anlamsızsa '{"tasks": []}' döndür.

Örnek 1:
Kullanıcı Girdisi: "ahmetin 100 metre siyah penyesini bas sonra paketle ve kargoya ver faturaları da kesmeyi unutma yarın saat 15:00'e kadar bitsin"
Çıktı (Mevcut tarih 2024-05-20 ise): {"tasks": [{"task": "Ahmet'in 100m siyah penyesini basıp, paketleyerek kargoya vermek", "dueDate": "2024-05-21T12:00:00.000Z", "location": null}, {"task": "Faturaları kesmek", "dueDate": null, "location": null}]}

Örnek 2:
Kullanıcı Girdisi: "selam, bugün çok iş var. önce depoyu bi düzenleyelim. öğleden sonra da yeni gelen kalıpları ABC Tekstil'den almamız lazım."
Çıktı: {"tasks": [{"task": "Depoyu düzenlemek", "dueDate": null, "location": null}, {"task": "Yeni gelen kalıpları ABC Tekstil'den almak", "dueDate": null, "location": "ABC Tekstil"}]}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Kullanıcı Girdisi:\n---\n${text}\n---`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
            },
        });

        const jsonString = response.text.trim();
        const parsed = JSON.parse(jsonString);

        if (parsed && Array.isArray(parsed.tasks)) {
            // Further validation can be added here
            return parsed.tasks as ParsedTask[];
        }

        throw new Error("Invalid format from API. Expected { tasks: [...] }");

    } catch (error) {
        console.error("Error parsing tasks with Gemini:", error);
        // Fallback to simple line-by-line parsing on error
        return text.split('\n').map(line => ({
            task: line.trim(),
            dueDate: null,
            location: null
        })).filter(item => item.task.length > 0);
    }
};

