import type { Task } from '../types';
import { parseTasksFromText } from '../services/geminiService';
import { geocodeAddress } from '../services/locationService';
import { PlusIcon, MicrophoneIcon, StopIcon, TrashIcon, CalendarIcon, MapPinIcon } from './Icons';

interface AddTaskProps {
  onAddTask: (tasks: Omit<Task, 'id' | 'completed' | 'createdAt'>[]) => void;
}

const AddTask: React.FC<AddTaskProps> = ({ onAddTask }) => {
  const [text, setText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const recognitionRef = useRef<any | null>(null);
  const isListeningRef = useRef(isListening);
  isListeningRef.current = isListening;

  useEffect(() => {
    if ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window) {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      recognitionRef.current = new SpeechRecognition();
      const recognition = recognitionRef.current;
      recognition.continuous = true;
      recognition.lang = 'tr-TR';
      recognition.interimResults = false;

      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          transcript += event.results[i][0].transcript + ' ';
        }
        setText(prev => prev + transcript);
      };

      recognition.onerror = (event: any) => {
        console.error('Speech recognition error', event.error);
        setIsListening(false);
      };

      recognition.onend = () => {
        if (isListeningRef.current) {
          console.log("Recognition stopped, restarting...");
          recognition.start();
        }
      };

    } else {
      console.warn('Speech Recognition not supported in this browser.');
    }

    return () => {
        isListeningRef.current = false;
        recognitionRef.current?.stop();
    };
  }, []);

  const handleMicClick = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      if(recognitionRef.current) {
        setText('');
        recognitionRef.current.start();
        setIsListening(true);
      } else {
        alert("Mikrofon desteği bulunamadı.");
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() === '') return;

    if (isListening) {
        recognitionRef.current?.stop();
        setIsListening(false);
    }

    setIsLoading(true);
    const parsedTasks = await parseTasksFromText(text);

    const tasksWithCoords = await Promise.all(
      parsedTasks.map(async (pTask) => {
        let coords = undefined;
        if (pTask.location) {
          coords = await geocodeAddress(pTask.location);
        }
        return {
          text: pTask.task,
          dueDate: pTask.dueDate || undefined,
          locationName: pTask.location || undefined,
          locationCoords: coords,
        };
      })
    );

    if (tasksWithCoords.length > 0) {
      onAddTask(tasksWithCoords);
      setText('');
    }
    setIsLoading(false);
  };

  return (
    <form onSubmit={handleSubmit} className="mt-4 p-4 bg-gray-800 rounded-lg shadow-lg">
      <textarea
        className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Asistanınıza not bırakın... (örn: Yarın saat 10'da ABC Tekstil'den kumaşları al)"
        disabled={isLoading}
      />
      <div className="flex items-center justify-between mt-3">
        <button
          type="button"
          onClick={handleMicClick}
          className={`p-2 rounded-full transition-colors duration-200 ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
          disabled={isLoading}
          aria-label={isListening ? 'Kaydı Durdur' : 'Sesli Not Bırak'}
        >
          {isListening ? <StopIcon /> : <MicrophoneIcon />}
        </button>
        <button
          type="submit"
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-teal-500 transition-colors disabled:opacity-50"
          disabled={isLoading || text.trim() === ''}
        >
          {isLoading ? 'Ekleniyor...' : <> <PlusIcon /> Görev Ekle </>}
        </button>
      </div>
    </form>
  );
};

const formatDueDate = (isoString?: string) => {
    if (!isoString) return '';
    const date = new Date(isoString);
    return date.toLocaleString('tr-TR', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
};

interface TaskListScreenProps {
  tasks: Task[];
  setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
}

const TaskListScreen: React.FC<TaskListScreenProps> = ({ tasks, setTasks }) => {
  const handleAddTask = (taskData: Omit<Task, 'id' | 'completed' | 'createdAt'>[]) => {
    const newTasks: Task[] = taskData.map(data => ({
      id: Date.now().toString() + data.text.slice(0, 5),
      ...data,
      completed: false,
      createdAt: new Date().toISOString(),
    }));
    setTasks(prevTasks => [...newTasks, ...prevTasks]);
  };

  const toggleTask = (id: string) => {
    setTasks(tasks.map(task => task.id === id ? { ...task, completed: !task.completed } : task));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  return (
    <div>
      <AddTask onAddTask={handleAddTask} />
      <div className="mt-6">
        <h2 className="text-xl font-semibold text-gray-300 mb-3">Kişisel Asistan</h2>
        {tasks.length === 0 ? (
          <p className="text-gray-500 text-center py-4">Henüz görev eklenmemiş.</p>
        ) : (
          <ul className="space-y-3">
            {tasks.map(task => (
              <li key={task.id} className="bg-gray-800 p-4 rounded-lg shadow-md transition-all hover:bg-gray-700">
                <div className="flex items-start justify-between">
                    <div className="flex items-start flex-1 min-w-0">
                        <input
                            type="checkbox"
                            checked={task.completed}
                            onChange={() => toggleTask(task.id)}
                            className="h-5 w-5 rounded-md border-gray-600 bg-gray-700 text-teal-500 focus:ring-teal-600 cursor-pointer mt-1"
                        />
                        <div className="ml-4">
                            <span className={`text-gray-300 break-words ${task.completed ? 'line-through text-gray-500' : ''}`}>
                                {task.text}
                            </span>
                            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-2 text-xs text-gray-400">
                                {task.dueDate && (
                                    <span className="flex items-center gap-1">
                                        <CalendarIcon/>
                                        {formatDueDate(task.dueDate)}
                                    </span>
                                )}
                                {task.locationName && task.locationCoords && (
                                    <a 
                                        href={`https://www.google.com/maps?q=${task.locationCoords.lat},${task.locationCoords.lng}`} 
                                        target="_blank" 
                                        rel="noopener noreferrer"
                                        className="flex items-center gap-1 text-blue-400 hover:text-blue-300"
                                    >
                                        <MapPinIcon/>
                                        {task.locationName}
                                    </a>
                                )}
                            </div>
                        </div>
                    </div>
                    <button onClick={() => deleteTask(task.id)} className="ml-4 text-gray-500 hover:text-red-500 transition-colors flex-shrink-0" aria-label="Görevi Sil">
                        <TrashIcon />
                    </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default TaskListScreen;

/**
 * Fetches a human-readable address from geographic coordinates using the Nominatim (OpenStreetMap) API.
 * @param lat - Latitude.
 * @param lng - Longitude.
 * @returns A promise that resolves to the address string.
 */
export const getAddressFromCoordinates = async (lat: number, lng: number): Promise<string> => {
    const url = `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lng}`;
    try {
        const response = await fetch(url, {
            headers: {
                'Accept-Language': 'tr-TR,tr;q=0.9', // Request Turkish address if available
            }
        });
        if (!response.ok) {
            throw new Error(`Network response was not ok: ${response.statusText}`);
        }
        const data = await response.json();
        if (data && data.display_name) {
            return data.display_name;
        }
        return 'Adres detayı bulunamadı.';
    } catch (error) {
        console.error("Failed to fetch address:", error);
        return 'Adres alınamadı. İnternet bağlantınızı kontrol edin.';
    }
};

/**
 * Fetches geographic coordinates for a given address string using the Nominatim (OpenStreetMap) API.
 * @param address - The address string to search for.
 * @returns A promise that resolves to the location's coordinates or undefined if not found.
 */
export const geocodeAddress = async (address: string): Promise<{ lat: number; lng: number } | undefined> => {
    const url = `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(address)}&format=json&limit=1&countrycodes=tr`;
    try {
        const response = await fetch(url);
        if (!response.ok) {
            throw new Error(`Network response was not ok: ${response.statusText}`);
        }
        const data = await response.json();
        if (data && data.length > 0) {
            return {
                lat: parseFloat(data[0].lat),
                lng: parseFloat(data[0].lon),
            };
        }
        return undefined;
    } catch (error) {
        console.error("Failed to geocode address:", error);
        return undefined;
    }
};

/**
 * Calculates the Haversine distance between two points on the Earth.
 * @param start - The starting coordinates { lat, lng }.
 * @param end - The ending coordinates { lat, lng }.
 * @returns The distance in kilometers.
 */
const haversineDistance = (start: { lat: number; lng: number }, end: { lat: number; lng: number }): number => {
    const R = 6371; // Radius of the Earth in km
    const dLat = (end.lat - start.lat) * (Math.PI / 180);
    const dLon = (end.lng - start.lng) * (Math.PI / 180);
    const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos(start.lat * (Math.PI / 180)) * Math.cos(end.lat * (Math.PI / 180)) *
        Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
};

/**
 * Estimates travel time based on distance.
 * This is a simplified estimation and doesn't account for traffic.
 * @param start - The starting coordinates { lat, lng }.
 * @param end - The ending coordinates { lat, lng }.
 * @returns The estimated travel time in minutes.
 */
export const calculateTravelTime = (start: { lat: number; lng: number }, end: { lat: number; lng: number }): number => {
    const distance = haversineDistance(start, end);
    // Assume an average speed of 40 km/h for urban/suburban travel
    const AVERAGE_SPEED_KMH = 40;
    const timeHours = distance / AVERAGE_SPEED_KMH;
    return Math.round(timeHours * 60);
};

