import React, { useState, useEffect } from 'react';

interface ConfirmationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  title: string;
  children: React.ReactNode;
  confirmButtonText?: string;
  confirmButtonClass?: string;
}

const ConfirmationModal: React.FC<ConfirmationModalProps> = ({ 
  isOpen, 
  onClose, 
  onConfirm, 
  title, 
  children,
  confirmButtonText = "Silmeyi Onayla",
  confirmButtonClass = "bg-red-600 hover:bg-red-500"
}) => {
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    // Reset state when modal is opened or closed
    if (isOpen) {
      setPassword('');
      setError('');
    }
  }, [isOpen]);

  if (!isOpen) {
    return null;
  }

  const handleConfirm = () => {
    if (password === '1234') {
      onConfirm();
      onClose();
    } else {
      setError('Hatalı şifre. Lütfen tekrar deneyin.');
      setPassword('');
    }
  };

  const handleWrapperClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      onClose();
    }
  };

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50"
      onClick={handleWrapperClick}
    >
      <div className="bg-gray-800 rounded-lg shadow-xl p-6 w-11/12 max-w-sm">
        <h2 className="text-xl font-bold text-teal-400 mb-4">{title}</h2>
        <div className="text-gray-300 mb-4">
          {children}
        </div>
        <div className="space-y-4">
          <input
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Onay için şifreyi girin (1234)"
            className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-red-500 focus:outline-none"
            autoFocus
          />
          {error && <p className="text-red-400 text-sm">{error}</p>}
        </div>
        <div className="flex justify-end gap-4 mt-6">
          <button 
            onClick={onClose} 
            className="px-4 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-500 transition-colors"
          >
            İptal
          </button>
          <button 
            onClick={handleConfirm}
            className={`px-4 py-2 text-white font-semibold rounded-lg transition-colors ${confirmButtonClass}`}
          >
            {confirmButtonText}
          </button>
        </div>
      </div>
    </div>
  );
};

