export default CustomerDetailScreen;

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY environment variable not set. Gemini API will not function.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// This defines the structure we expect from the AI model
interface ParsedTask {
    task: string;
    dueDate: string | null; // ISO 8601 format
    location: string | null;
}

export const parseTasksFromText = async (text: string): Promise<ParsedTask[]> => {
    if (!API_KEY) {
        // Fallback for when API key is not available, returns a simplified structure
        return text.split('\n').map(line => ({
            task: line.trim(),
            dueDate: null,
            location: null
        })).filter(item => item.task.length > 0);
    }

    try {
        const currentDate = new Date().toISOString();
        const systemInstruction = `Sen, tekstil baskı sektöründe faaliyet gösteren üst düzey bir şirketin elit, proaktif ve akıllı yönetici asistanısın. Görevin, kullanıcının karmaşık, günlük dildeki notlarını analiz edip, bunları net, eyleme geçirilebilir ve zenginleştirilmiş görev objelerine dönüştürmektir.

Kuralların:
1.  **İlişkili Eylemleri Birleştir:** Birbiriyle bağlantılı adımları (kes, bas, paketle, kargola gibi) tek bir kapsamlı görev olarak birleştir.
2.  **Tarih ve Saati Algıla ve Dönüştür:** Metindeki göreceli zaman ifadelerini ("yarın saat 10'da", "akşam 5'te", "2 saat sonra", "cuma günü", "3 gün sonra") algıla. Mevcut tarih ve saati (${currentDate}) baz alarak bu ifadeleri MUTLAKA tam bir ISO 8601 formatına (YYYY-MM-DDTHH:mm:ss.sssZ) çevir. Eğer tarih/saat belirtilmemişse, dueDate değerini null yap.
3.  **Konum Bilgisini Çıkar:** Metindeki belirgin mekan, adres veya şirket isimlerini ("XYZ Kumaşçılık'a uğra", "Sultanahmet'teki atölye") algıla ve location alanına yaz. Konum yoksa, location değerini null yap.
4.  **Netleştir ve Eylem Odaklı Ol:** Her görevi bir eylem fiili ile başlat. Belirsiz ifadeleri netleştir.
5.  **Gereksiz Bilgileri Filtrele:** Sohbet, yorum veya görev olmayan ifadeleri tamamen yok say.
6.  **Sadece JSON Döndür:** Çıktın her zaman '{"tasks": [{"task": "...", "dueDate": "...", "location": "..."}, ...]}' formatında bir JSON nesnesi olmalı. Başka hiçbir metin veya açıklama ekleme. Girdi anlamsızsa '{"tasks": []}' döndür.

Örnek 1:
Kullanıcı Girdisi: "ahmetin 100 metre siyah penyesini bas sonra paketle ve kargoya ver faturaları da kesmeyi unutma yarın saat 15:00'e kadar bitsin"
Çıktı (Mevcut tarih 2024-05-20T10:00:00.000Z ise): {"tasks": [{"task": "Ahmet'in 100m siyah penyesini basıp, paketleyerek kargoya vermek", "dueDate": "2024-05-21T15:00:00.000Z", "location": null}, {"task": "Faturaları kesmek", "dueDate": null, "location": null}]}

Örnek 2:
Kullanıcı Girdisi: "selam, bugün çok iş var. önce depoyu bi düzenleyelim. öğleden sonra da yeni gelen kalıpları ABC Tekstil'den almamız lazım. 2 saat sonra başla"
Çıktı (Mevcut tarih 2024-05-20T11:00:00.000Z ise): {"tasks": [{"task": "Depoyu düzenlemek", "dueDate": null, "location": null}, {"task": "Yeni gelen kalıpları ABC Tekstil'den almak", "dueDate": "2024-05-20T13:00:00.000Z", "location": "ABC Tekstil"}]}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Kullanıcı Girdisi:\n---\n${text}\n---`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
            },
        });

        const jsonString = response.text.trim();
        const parsed = JSON.parse(jsonString);

        if (parsed && Array.isArray(parsed.tasks)) {
            // Further validation can be added here
            return parsed.tasks as ParsedTask[];
        }

        throw new Error("Invalid format from API. Expected { tasks: [...] }");

    } catch (error) {
        console.error("Error parsing tasks with Gemini:", error);
        // Fallback to simple line-by-line parsing on error
        return text.split('\n').map(line => ({
            task: line.trim(),
            dueDate: null,
            location: null
        })).filter(item => item.task.length > 0);
    }
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import type { Task } from '../types';
import { parseTasksFromText } from '../services/geminiService';
import { geocodeAddress } from '../services/locationService';
import { PlusIcon, MicrophoneIcon, StopIcon, TrashIcon, CalendarIcon, MapPinIcon } from './Icons';

interface AddTaskProps {
  onAddTask: (tasks: Omit<Task, 'id' | 'completed' | 'createdAt'>[]) => void;
}

const AddTask: React.FC<AddTaskProps> = ({ onAddTask }) => {
  const [text, setText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const recognitionRef = useRef<any | null>(null);
  const isListeningRef = useRef(isListening);
  isListeningRef.current = isListening;

  useEffect(() => {
    if ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window) {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      recognitionRef.current = new SpeechRecognition();
      const recognition = recognitionRef.current;
      recognition.continuous = true;
      recognition.lang = 'tr-TR';
      recognition.interimResults = false;

      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          transcript += event.results[i][0].transcript + ' ';
        }
        setText(prev => prev + transcript);
      };

      recognition.onerror = (event: any) => {
        console.error('Speech recognition error', event.error);
        setIsListening(false);
      };

      recognition.onend = () => {
        if (isListeningRef.current) {
          console.log("Recognition stopped, restarting...");
          recognition.start();
        }
      };

    } else {
      console.warn('Speech Recognition not supported in this browser.');
    }

    return () => {
        isListeningRef.current = false;
        recognitionRef.current?.stop();
    };
  }, []);

  const handleMicClick = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      if(recognitionRef.current) {
        setText('');
        recognitionRef.current.start();
        setIsListening(true);
      } else {
        alert("Mikrofon desteği bulunamadı.");
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() === '') return;

    if (isListening) {
        recognitionRef.current?.stop();
        setIsListening(false);
    }

    setIsLoading(true);
    const parsedTasks = await parseTasksFromText(text);

    const tasksWithCoords = await Promise.all(
      parsedTasks.map(async (pTask) => {
        let coords = undefined;
        if (pTask.location) {
          coords = await geocodeAddress(pTask.location);
        }
        return {
          text: pTask.task,
          dueDate: pTask.dueDate || undefined,
          locationName: pTask.location || undefined,
          locationCoords: coords,
        };
      })
    );

    if (tasksWithCoords.length > 0) {
      onAddTask(tasksWithCoords);
      setText('');
    }
    setIsLoading(false);
  };

  return (
    <form onSubmit={handleSubmit} className="mt-4 p-4 bg-gray-800 rounded-lg shadow-lg">
      <textarea
        className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Asistanınıza not bırakın... (örn: Yarın saat 10'da ABC Tekstil'den kumaşları al)"
        disabled={isLoading}
      />
      <div className="flex items-center justify-between mt-3">
        <button
          type="button"
          onClick={handleMicClick}
          className={`p-2 rounded-full transition-colors duration-200 ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
          disabled={isLoading}
          aria-label={isListening ? 'Kaydı Durdur' : 'Sesli Not Bırak'}
        >
          {isListening ? <StopIcon /> : <MicrophoneIcon />}
        </button>
        <button
          type="submit"
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-teal-500 transition-colors disabled:opacity-50"
          disabled={isLoading || text.trim() === ''}
        >
          {isLoading ? 'Ekleniyor...' : <> <PlusIcon /> Görev Ekle </>}
        </button>
      </div>
    </form>
  );
};

const formatDueDate = (isoString?: string) => {
    if (!isoString) return '';
    const date = new Date(isoString);
    return date.toLocaleString('tr-TR', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
};

interface TaskListScreenProps {
  tasks: Task[];
  setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
}

const TaskListScreen: React.FC<TaskListScreenProps> = ({ tasks, setTasks }) => {
  const handleAddTask = (taskData: Omit<Task, 'id' | 'completed' | 'createdAt'>[]) => {
    const newTasks: Task[] = taskData.map(data => ({
      id: Date.now().toString() + data.text.slice(0, 5),
      ...data,
      completed: false,
      createdAt: new Date().toISOString(),
    }));
    setTasks(prevTasks => [...newTasks, ...prevTasks]);
  };

  const toggleTask = (id: string) => {
    setTasks(tasks.map(task => task.id === id ? { ...task, completed: !task.completed } : task));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  const sortedTasks = useMemo(() => {
    return [...tasks].sort((a, b) => {
      // 1. Completed tasks go to the bottom
      if (a.completed && !b.completed) return 1;
      if (!a.completed && b.completed) return -1;

      // 2. Sort by due date (tasks without a due date are treated as far in the future)
      const aHasDueDate = !!a.dueDate;
      const bHasDueDate = !!b.dueDate;

      if (aHasDueDate && !bHasDueDate) return -1; // a comes first
      if (!aHasDueDate && bHasDueDate) return 1;  // b comes first

      if (aHasDueDate && bHasDueDate) {
        const aTime = new Date(a.dueDate!).getTime();
        const bTime = new Date(b.dueDate!).getTime();
        if (aTime !== bTime) {
          return aTime - bTime; // Sort by due date ascending
        }
      }

      // 3. For tasks with same due date or no due date, sort by creation date (newest on top)
      return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
    });
  }, [tasks]);


  return (
    <div>
      <AddTask onAddTask={handleAddTask} />
      <div className="mt-6">
        <h2 className="text-xl font-semibold text-gray-300 mb-3">Kişisel Asistan</h2>
        {tasks.length === 0 ? (
          <p className="text-gray-500 text-center py-4">Henüz görev eklenmemiş.</p>
        ) : (
          <ul className="space-y-3">
            {sortedTasks.map(task => (
              <li key={task.id} className="bg-gray-800 p-4 rounded-lg shadow-md transition-all hover:bg-gray-700">
                <div className="flex items-start justify-between">
                    <div className="flex items-start flex-1 min-w-0">
                        <input
                            type="checkbox"
                            checked={task.completed}
                            onChange={() => toggleTask(task.id)}
                            className="h-5 w-5 rounded-md border-gray-600 bg-gray-700 text-teal-500 focus:ring-teal-600 cursor-pointer mt-1"
                        />
                        <div className="ml-4">
                            <span className={`text-gray-300 break-words ${task.completed ? 'line-through text-gray-500' : ''}`}>
                                {task.text}
                            </span>
                            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-2 text-xs text-gray-400">
                                {task.dueDate && (
                                    <span className="flex items-center gap-1">
                                        <CalendarIcon/>
                                        {formatDueDate(task.dueDate)}
                                    </span>
                                )}
                                {task.locationName && task.locationCoords && (
                                    <a 
                                        href={`https://www.google.com/maps?q=${task.locationCoords.lat},${task.locationCoords.lng}`} 
                                        target="_blank" 
                                        rel="noopener noreferrer"
                                        className="flex items-center gap-1 text-blue-400 hover:text-blue-300"
                                    >
                                        <MapPinIcon/>
                                        {task.locationName}
                                    </a>
                                )}
                            </div>
                        </div>
                    </div>
                    <button onClick={() => deleteTask(task.id)} className="ml-4 text-gray-500 hover:text-red-500 transition-colors flex-shrink-0" aria-label="Görevi Sil">
                        <TrashIcon />
                    </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default TaskListScreen;

import { GoogleGenAI } from "@google/genai";

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY environment variable not set. Gemini API will not function.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// This defines the structure we expect from the AI model
interface ParsedTask {
    task: string;
    dueDate: string | null; // ISO 8601 format
    location: string | null;
}

export const parseTasksFromText = async (text: string): Promise<ParsedTask[]> => {
    if (!API_KEY) {
        // Fallback for when API key is not available, returns a simplified structure
        return text.split('\n').map(line => ({
            task: line.trim(),
            dueDate: null,
            location: null
        })).filter(item => item.task.length > 0);
    }

    try {
        const currentDate = new Date().toISOString();
        const systemInstruction = `Sen, tekstil baskı sektöründe faaliyet gösteren üst düzey bir şirketin elit, proaktif ve akıllı yönetici asistanısın. Görevin, kullanıcının karmaşık, günlük dildeki notlarını analiz edip, bunları net, eyleme geçirilebilir ve zenginleştirilmiş görev objelerine dönüştürmektir.

Mevcut tarih ve saat: ${currentDate}

Kesinlikle uyman gereken kurallar:
1.  **Tarih ve Saat Yorumlama (En Önemli Kural):**
    *   **Referans Noktası:** Tüm zaman hesaplamalarını SADECE yukarıda verilen mevcut tarih ve saati referans alarak yap.
    *   **Dönüşüm:** Metindeki TÜM zaman ifadelerini ("yarın saat 10'da", "akşam 5'te", "sabah 7", "2 saat sonra", "cuma günü", "3 gün sonra", "10 şubat saat 14:30") algıla. Bu ifadeleri MUTLAKA tam ve doğru bir ISO 8601 formatına (YYYY-MM-DDTHH:mm:ss.sssZ) çevir.
    *   **Göreceli İfadeler:** "yarın" bir sonraki gün, "bugün" mevcut gün demektir. "sabah" (örn: 07:00-11:00), "öğlen" (örn: 12:00-14:00), "akşam" (örn: 18:00-22:00) gibi ifadeleri mantıklı saatlere çevir.
    *   **Varsayılan Yıl:** Eğer kullanıcı bir yıl belirtmemişse, mevcut yılı kullan. Eğer ortaya çıkan tarih geçmişte kalıyorsa, bir sonraki yılı kullan. Asla alakasız veya çok uzak bir gelecek yılı (örn: 2026) uydurma.
    *   **Zaman Yoksa:** Eğer bir görev için hiçbir tarih veya saat belirtilmemişse, \`dueDate\` değerini \`null\` olarak ayarla.
2.  **İlişkili Eylemleri Birleştir:** Birbiriyle bağlantılı adımları (kes, bas, paketle, kargola gibi) tek bir kapsamlı görev olarak birleştir.
3.  **Konum Bilgisini Çıkar:** Metindeki belirgin mekan, adres veya şirket isimlerini ("XYZ Kumaşçılık'a uğra", "Sultanahmet'teki atölye") algıla ve \`location\` alanına yaz. Konum yoksa, \`location\` değerini \`null\` yap.
4.  **Netleştir ve Eylem Odaklı Ol:** Her görevi bir eylem fiili ile başlat. Belirsiz ifadeleri netleştir.
5.  **Gereksiz Bilgileri Filtrele:** Sohbet, yorum veya görev olmayan ifadeleri tamamen yok say.
6.  **Sadece JSON Döndür:** Çıktın her zaman '{"tasks": [{"task": "...", "dueDate": "...", "location": "..."}, ...]}' formatında bir JSON nesnesi olmalı. Başka hiçbir metin veya açıklama ekleme. Girdi anlamsızsa '{"tasks": []}' döndür.

Örnek 1:
Kullanıcı Girdisi: "ahmetin 100 metre siyah penyesini bas sonra paketle ve kargoya ver faturaları da kesmeyi unutma yarın saat 15:00'e kadar bitsin"
Çıktı (Mevcut tarih 2024-05-20T10:00:00.000Z ise): {"tasks": [{"task": "Ahmet'in 100m siyah penyesini basıp, paketleyerek kargoya vermek", "dueDate": "2024-05-21T12:00:00.000Z", "location": null}, {"task": "Faturaları kesmek", "dueDate": null, "location": null}]}

Örnek 2:
Kullanıcı Girdisi: "yarın sabah 7'de Abbasi'ye git, akşam 9'da da pasaportu evden al"
Çıktı (Mevcut tarih 2024-05-20T20:00:00.000Z ise): {"tasks": [{"task": "Abbasi'ye gitmek", "dueDate": "2024-05-21T04:00:00.000Z", "location": "Abbasi"}, {"task": "Pasaportu evden almak", "dueDate": "2024-05-21T18:00:00.000Z", "location": "Ev"}]}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Kullanıcı Girdisi:\n---\n${text}\n---`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
            },
        });

        const jsonString = response.text.trim();
        const parsed = JSON.parse(jsonString);

        if (parsed && Array.isArray(parsed.tasks)) {
            // Further validation can be added here
            return parsed.tasks as ParsedTask[];
        }

        throw new Error("Invalid format from API. Expected { tasks: [...] }");

    } catch (error) {
        console.error("Error parsing tasks with Gemini:", error);
        // Fallback to simple line-by-line parsing on error
        return text.split('\n').map(line => ({
            task: line.trim(),
            dueDate: null,
            location: null
        })).filter(item => item.task.length > 0);
    }
};

