interface HomeScreenProps {
  customers: Customer[];
  tasks: Task[];
  onNavigate: (view: View) => void;
}

const StatCard: React.FC<{ label: string; value: number | string; }> = ({ label, value }) => (
  <div className="bg-gray-800 p-4 rounded-lg text-center shadow-md">
    <p className="text-2xl font-bold text-teal-400">{value}</p>
    <p className="text-sm text-gray-400">{label}</p>
  </div>
);

const NavCard: React.FC<{ title: string; description: string; icon: React.ReactElement; onClick: () => void; }> = ({ title, description, icon, onClick }) => (
  <button
    onClick={onClick}
    className="bg-gray-800 p-6 rounded-lg shadow-lg text-left w-full transition-all duration-300 ease-in-out hover:bg-gray-700 hover:shadow-teal-500/20 hover:scale-105 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-900 focus:ring-teal-500"
  >
    <div className="flex items-center gap-4">
      <div className="bg-gray-900 p-3 rounded-lg text-teal-400">
         {icon}
      </div>
      <div>
        <h3 className="text-xl font-bold text-gray-100">{title}</h3>
        <p className="text-gray-400 mt-1">{description}</p>
      </div>
    </div>
  </button>
);

const HomeScreen: React.FC<HomeScreenProps> = ({ customers, tasks, onNavigate }) => {
  const activeTasks = tasks.filter(t => !t.completed).length;
  const totalBalance = customers.reduce((total, customer) => {
      const customerBalance = customer.jobs.reduce((balance, job) => balance + (job.price - job.paidAmount), 0);
      return total + (customerBalance > 0 ? customerBalance : 0);
  }, 0);

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
  };

  return (
    <div className="space-y-8">
      <div>
        <h2 className="text-3xl font-bold text-gray-100">Hoş Geldiniz</h2>
        <p className="text-gray-400 mt-1">İşlerinizi yönetmeye başlayın.</p>
      </div>

      <div className="grid grid-cols-3 gap-4">
        <StatCard label="Aktif Görevler" value={activeTasks} />
        <StatCard label="Müşteri Sayısı" value={customers.length} />
        <StatCard label="Toplam Bakiye" value={formatCurrency(totalBalance)} />
      </div>

      <div className="space-y-4">
        <NavCard 
          title="Kişisel Asistan"
          description="Günlük görevlerinizi ve hatırlatıcılarınızı yönetin."
          icon={<TasksIcon />}
          onClick={() => onNavigate('assistant')}
        />
        <NavCard 
          title="Müşteriler"
          description="Müşteri listesini ve işlerini görüntüleyin."
          icon={<CustomersIcon />}
          onClick={() => onNavigate('customers')}
        />
        <NavCard 
          title="Kalıplar"
          description="Baskı kalıplarınızı ve fiyatlarını düzenleyin."
          icon={<PatternIcon />}
          onClick={() => onNavigate('patterns')}
        />
      </div>
    </div>
  );
};

export default HomeScreen;

