import { GoogleGenAI } from "@google/genai";
import type { Task } from '../types';

const API_KEY = process.env.API_KEY;

if (!API_KEY) {
  console.warn("API_KEY environment variable not set. Gemini API will not function.");
}

const ai = new GoogleGenAI({ apiKey: API_KEY });

// This defines the structure we expect from the AI model
interface ParsedTask {
    task: string;
    dueDate: string | null; // ISO 8601 format
    location: string | null;
}

interface UpdatedTask extends Partial<ParsedTask> {
    id: string;
}

interface GeminiResponse {
    newTasks: ParsedTask[];
    updatedTasks: UpdatedTask[];
}


export const parseTasksFromText = async (text: string, existingTasks: Task[]): Promise<GeminiResponse> => {
    if (!API_KEY) {
        // Fallback for when API key is not available
        return {
            newTasks: text.split('\n').map(line => ({
                task: line.trim(),
                dueDate: null,
                location: null
            })).filter(item => item.task.length > 0),
            updatedTasks: []
        };
    }

    try {
        const currentDate = new Date().toISOString();
        // Only send relevant info to save tokens
        const simplifiedExistingTasks = existingTasks.map(t => ({ id: t.id, text: t.text, dueDate: t.dueDate, locationName: t.locationName }));

        const systemInstruction = `Sen, tekstil baskı sektöründe faaliyet gösteren üst düzey bir şirketin elit, proaktif ve akıllı yönetici asistanısın. Görevin, kullanıcının yeni metin girdisini ve MEVCUT GÖREV LİSTESİNİ analiz etmektir.

Mevcut tarih ve saat: ${currentDate}
Mevcut Görev Listesi: ${JSON.stringify(simplifiedExistingTasks)}

Kesinlikle uyman gereken kurallar:
1.  **Analiz ve Karar Verme:**
    *   Kullanıcının yeni girdisini oku.
    *   Bu girdinin mevcut görev listesindeki bir görevle ilgili olup olmadığını belirle. Örneğin, "patates de al" girdisi, içinde "market" veya "alışveriş" geçen bir görevle ilgilidir. "toplantıyı 3'e al" girdisi, mevcut bir toplantı görevinin zamanını günceller.
    *   Eğer girdi mevcut bir görevi güncelliyor veya ona ekleme yapıyorsa, o görevi GÜNCELLE.
    *   Eğer girdi tamamen yeni ve bağımsız bir görevse, YENİ bir görev oluştur.

2.  **Çıktı Formatı (En Önemli Kural):**
    *   Çıktın HER ZAMAN şu formatta bir JSON nesnesi olmalı: '{"newTasks": [...], "updatedTasks": [...] }'.
    *   \`newTasks\` dizisi: Tamamen yeni oluşturulmuş görevleri içerir. Bu görevlerin 'id'si OLMAYACAK. Her görev objesi 'task', 'dueDate' (ISO 8601 veya null), ve 'location' (string veya null) alanlarını içermelidir.
    *   \`updatedTasks\` dizisi: Mevcut görevlerden güncellenmiş olanları içerir. Her görev objesi, güncellenen görevin ORİJİNAL 'id'sini MUTLAKA içermelidir. Ayrıca sadece DEĞİŞEN alanları içermelidir (örn: \`{"id": "123", "task": "Domates, biber ve patates al"}\`). Eğer bir görevin tüm metni değişiyorsa, tüm metni gönder.
    *   Eğer hiçbir görev oluşturulmadı veya güncellenmediyse, boş diziler döndür: \`{"newTasks": [], "updatedTasks": []}\`.
    *   Başka hiçbir metin veya açıklama ekleme.

3.  **Tarih ve Saat Yorumlama:** Metindeki TÜM zaman ifadelerini ("yarın saat 10'da", "akşam 5'te") algıla ve MUTLAKA tam ve doğru bir ISO 8601 formatına (YYYY-MM-DDTHH:mm:ss.sssZ) çevir. Eğer yıl belirtilmemişse, mevcut yılı kullan; tarih geçmişte kalıyorsa bir sonraki yılı kullan. Asla alakasız bir gelecek yılı (örn: 2026) uydurma.

4.  **Konum Bilgisini Çıkar:** Metindeki belirgin mekan, adres veya şirket isimlerini algıla ve \`location\` alanına yaz. Konum yoksa, \`location\` değerini \`null\` yap.

Örnek 1 (Yeni Görev):
Mevcut Görevler: []
Kullanıcı Girdisi: "yarın sabah 9'da XYZ Tekstil'e git"
Çıktı: {"newTasks": [{"task": "XYZ Tekstil'e gitmek", "dueDate": "${new Date(new Date().setDate(new Date().getDate() + 1)).toISOString().split('T')[0]}T06:00:00.000Z", "location": "XYZ Tekstil"}], "updatedTasks": []}

Örnek 2 (Görev Güncelleme/Birleştirme):
Mevcut Görevler: [{"id": "abc-123", "text": "Akşam markete uğrayıp domates ve biber al", "locationName": "Market"}]
Kullanıcı Girdisi: "patates de alınacak"
Çıktı: {"newTasks": [], "updatedTasks": [{"id": "abc-123", "task": "Akşam markete uğrayıp domates, biber ve patates al"}]}
`;

        const response = await ai.models.generateContent({
            model: 'gemini-3-flash-preview',
            contents: `Kullanıcı Girdisi:\n---\n${text}\n---`,
            config: {
                systemInstruction: systemInstruction,
                responseMimeType: "application/json",
            },
        });

        const jsonString = response.text.trim();
        const parsed = JSON.parse(jsonString);

        if (parsed && Array.isArray(parsed.newTasks) && Array.isArray(parsed.updatedTasks)) {
            return parsed as GeminiResponse;
        }

        throw new Error("Invalid format from API. Expected { newTasks: [...], updatedTasks: [...] }");

    } catch (error) {
        console.error("Error parsing tasks with Gemini:", error);
        // Fallback to simple line-by-line parsing on error
        return { 
            newTasks: text.split('\n').map(line => ({
                task: line.trim(),
                dueDate: null,
                location: null
            })).filter(item => item.task.length > 0),
            updatedTasks: []
        };
    }
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import type { Task } from '../types';
import { parseTasksFromText } from '../services/geminiService';
import { geocodeAddress } from '../services/locationService';
import { PlusIcon, MicrophoneIcon, StopIcon, TrashIcon, CalendarIcon, MapPinIcon } from './Icons';

interface AddTaskProps {
  tasks: Task[];
  onTasksUpdate: (updates: { 
    newTasks: Omit<Task, 'id' | 'completed' | 'createdAt'>[], 
    updatedTasks: (Partial<Task> & { id: string })[] 
  }) => void;
}

const AddTask: React.FC<AddTaskProps> = ({ tasks, onTasksUpdate }) => {
  const [text, setText] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const recognitionRef = useRef<any | null>(null);
  const isListeningRef = useRef(isListening);
  isListeningRef.current = isListening;

  useEffect(() => {
    if ('SpeechRecognition' in window || 'webkitSpeechRecognition' in window) {
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      recognitionRef.current = new SpeechRecognition();
      const recognition = recognitionRef.current;
      recognition.continuous = true;
      recognition.lang = 'tr-TR';
      recognition.interimResults = false;

      recognition.onresult = (event: any) => {
        let transcript = '';
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          transcript += event.results[i][0].transcript + ' ';
        }
        setText(prev => prev + transcript);
      };

      recognition.onerror = (event: any) => {
        console.error('Speech recognition error', event.error);
        setIsListening(false);
      };

      recognition.onend = () => {
        if (isListeningRef.current) {
          console.log("Recognition stopped, restarting...");
          recognition.start();
        }
      };

    } else {
      console.warn('Speech Recognition not supported in this browser.');
    }

    return () => {
        isListeningRef.current = false;
        recognitionRef.current?.stop();
    };
  }, []);

  const handleMicClick = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      if(recognitionRef.current) {
        setText('');
        recognitionRef.current.start();
        setIsListening(true);
      } else {
        alert("Mikrofon desteği bulunamadı.");
      }
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (text.trim() === '') return;

    if (isListening) {
        recognitionRef.current?.stop();
        setIsListening(false);
    }

    setIsLoading(true);
    const { newTasks, updatedTasks } = await parseTasksFromText(text, tasks);

    const processedNewTasks = await Promise.all(
      newTasks.map(async (pTask) => {
        let coords = undefined;
        if (pTask.location) {
          coords = await geocodeAddress(pTask.location);
        }
        return {
          text: pTask.task,
          dueDate: pTask.dueDate || undefined,
          locationName: pTask.location || undefined,
          locationCoords: coords,
        };
      })
    );

    const processedUpdatedTasks = await Promise.all(
        updatedTasks.map(async (pTask) => {
            const taskToUpdate: Partial<Task> & { id: string } = { id: pTask.id };
            if (pTask.task) taskToUpdate.text = pTask.task;
            if (pTask.dueDate) taskToUpdate.dueDate = pTask.dueDate;
            if (pTask.location) {
                const coords = await geocodeAddress(pTask.location);
                taskToUpdate.locationName = pTask.location;
                taskToUpdate.locationCoords = coords;
            }
            return taskToUpdate;
        })
    );

    if (processedNewTasks.length > 0 || processedUpdatedTasks.length > 0) {
      onTasksUpdate({ newTasks: processedNewTasks, updatedTasks: processedUpdatedTasks });
      setText('');
    }
    setIsLoading(false);
  };

  return (
    <form onSubmit={handleSubmit} className="mt-4 p-4 bg-gray-800 rounded-lg shadow-lg">
      <textarea
        className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none transition"
        rows={3}
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="Asistanınıza not bırakın... (örn: Yarın saat 10'da ABC Tekstil'den kumaşları al)"
        disabled={isLoading}
      />
      <div className="flex items-center justify-between mt-3">
        <button
          type="button"
          onClick={handleMicClick}
          className={`p-2 rounded-full transition-colors duration-200 ${isListening ? 'bg-red-500 text-white animate-pulse' : 'bg-blue-600 text-white hover:bg-blue-500'}`}
          disabled={isLoading}
          aria-label={isListening ? 'Kaydı Durdur' : 'Sesli Not Bırak'}
        >
          {isListening ? <StopIcon /> : <MicrophoneIcon />}
        </button>
        <button
          type="submit"
          className="flex items-center gap-2 px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-teal-500 transition-colors disabled:opacity-50"
          disabled={isLoading || text.trim() === ''}
        >
          {isLoading ? 'İşleniyor...' : <> <PlusIcon /> Görev Ekle </>}
        </button>
      </div>
    </form>
  );
};

const formatDueDate = (isoString?: string) => {
    if (!isoString) return '';
    const date = new Date(isoString);
    return date.toLocaleString('tr-TR', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
};

interface TaskListScreenProps {
  tasks: Task[];
  setTasks: React.Dispatch<React.SetStateAction<Task[]>>;
}

const TaskListScreen: React.FC<TaskListScreenProps> = ({ tasks, setTasks }) => {

  const handleTasksUpdate = (updates: { 
    newTasks: Omit<Task, 'id' | 'completed' | 'createdAt'>[], 
    updatedTasks: (Partial<Task> & { id: string })[] 
  }) => {
    setTasks(prevTasks => {
      // Handle updates first
      let updatedList = prevTasks.map(task => {
        const updatePayload = updates.updatedTasks.find(u => u.id === task.id);
        if (updatePayload) {
          return { ...task, ...updatePayload };
        }
        return task;
      });

      // Handle new tasks
      const newTasksToAdd: Task[] = updates.newTasks.map(data => ({
        id: Date.now().toString() + data.text.slice(0, 5),
        ...data,
        completed: false,
        createdAt: new Date().toISOString(),
      }));

      return [...newTasksToAdd, ...updatedList];
    });
  };

  const toggleTask = (id: string) => {
    setTasks(tasks.map(task => task.id === id ? { ...task, completed: !task.completed } : task));
  };

  const deleteTask = (id: string) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  const sortedTasks = useMemo(() => {
    return [...tasks].sort((a, b) => {
      // 1. Completed tasks go to the bottom
      if (a.completed && !b.completed) return 1;
      if (!a.completed && b.completed) return -1;

      // 2. Sort by due date (tasks without a due date are treated as far in the future)
      const aHasDueDate = !!a.dueDate;
      const bHasDueDate = !!b.dueDate;

      if (aHasDueDate && !bHasDueDate) return -1; // a comes first
      if (!aHasDueDate && bHasDueDate) return 1;  // b comes first

      if (aHasDueDate && bHasDueDate) {
        const aTime = new Date(a.dueDate!).getTime();
        const bTime = new Date(b.dueDate!).getTime();
        if (aTime !== bTime) {
          return aTime - bTime; // Sort by due date ascending
        }
      }

      // 3. For tasks with same due date or no due date, sort by creation date (newest on top)
      return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
    });
  }, [tasks]);


  return (
    <div>
      <AddTask tasks={tasks} onTasksUpdate={handleTasksUpdate} />
      <div className="mt-6">
        <h2 className="text-xl font-semibold text-gray-300 mb-3">Kişisel Asistan</h2>
        {tasks.length === 0 ? (
          <p className="text-gray-500 text-center py-4">Henüz görev eklenmemiş.</p>
        ) : (
          <ul className="space-y-3">
            {sortedTasks.map(task => (
              <li key={task.id} className="bg-gray-800 p-4 rounded-lg shadow-md transition-all hover:bg-gray-700">
                <div className="flex items-start justify-between">
                    <div className="flex items-start flex-1 min-w-0">
                        <input
                            type="checkbox"
                            checked={task.completed}
                            onChange={() => toggleTask(task.id)}
                            className="h-5 w-5 rounded-md border-gray-600 bg-gray-700 text-teal-500 focus:ring-teal-600 cursor-pointer mt-1"
                        />
                        <div className="ml-4">
                            <span className={`text-gray-300 break-words ${task.completed ? 'line-through text-gray-500' : ''}`}>
                                {task.text}
                            </span>
                            <div className="flex flex-wrap items-center gap-x-4 gap-y-1 mt-2 text-xs text-gray-400">
                                {task.dueDate && (
                                    <span className="flex items-center gap-1">
                                        <CalendarIcon/>
                                        {formatDueDate(task.dueDate)}
                                    </span>
                                )}
                                {task.locationName && task.locationCoords && (
                                    <a 
                                        href={`https://www.google.com/maps?q=${task.locationCoords.lat},${task.locationCoords.lng}`} 
                                        target="_blank" 
                                        rel="noopener noreferrer"
                                        className="flex items-center gap-1 text-blue-400 hover:text-blue-300"
                                    >
                                        <MapPinIcon/>
                                        {task.locationName}
                                    </a>
                                )}
                            </div>
                        </div>
                    </div>
                    <button onClick={() => deleteTask(task.id)} className="ml-4 text-gray-500 hover:text-red-500 transition-colors flex-shrink-0" aria-label="Görevi Sil">
                        <TrashIcon />
                    </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
};

export default TaskListScreen;

