import React from 'react';
import type { Customer } from '../types';
import { XIcon } from './Icons';

interface BalanceDetailModalProps {
  isOpen: boolean;
  onClose: () => void;
  customers: Customer[];
}

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' }).format(amount);
};

const BalanceDetailModal: React.FC<BalanceDetailModalProps> = ({ isOpen, onClose, customers }) => {
  if (!isOpen) {
    return null;
  }

  const totalReceivable = customers.reduce((total, customer) => {
      const customerBalance = customer.jobs.reduce((balance, job) => balance + (job.price - job.paidAmount), 0);
      return total + (customerBalance > 0 ? customerBalance : 0);
  }, 0);

  const totalTurnover = customers.reduce((total, customer) => {
      const customerTurnover = customer.jobs.reduce((turnover, job) => turnover + job.paidAmount, 0);
      return total + customerTurnover;
  }, 0);

  return (
    <div 
      className="fixed inset-0 bg-gray-900 bg-opacity-70 backdrop-blur-sm flex justify-center items-center z-50"
      onClick={onClose}
    >
      <div 
        className="bg-gray-800 rounded-lg shadow-xl p-6 w-11/12 max-w-md border border-gray-700"
        onClick={e => e.stopPropagation()}
      >
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold text-teal-400">Finansal Özet</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white">
            <XIcon />
          </button>
        </div>

        <div className="space-y-4">
            <div className="bg-gray-700 p-4 rounded-lg text-center">
                <p className="text-sm text-gray-400">Toplam Alacak (Tahsil Edilmemiş)</p>
                <p className="text-3xl font-bold text-red-400 mt-1">{formatCurrency(totalReceivable)}</p>
            </div>
            <div className="bg-gray-700 p-4 rounded-lg text-center">
                <p className="text-sm text-gray-400">Toplam Ciro (Tahsil Edilmiş)</p>
                <p className="text-3xl font-bold text-green-400 mt-1">{formatCurrency(totalTurnover)}</p>
            </div>
        </div>

        <p className="text-xs text-gray-500 text-center mt-6">
            Bu rakamlar, kayıtlı tüm müşteriler ve işler üzerinden hesaplanmıştır.
        </p>

      </div>
    </div>
  );
};

