import ManufacturingSlipPDF from './ManufacturingSlipPDF';


interface ManufacturingSlipModalProps {
  job: Job | null;
  customer: Customer;
  patterns: Pattern[];
  onClose: () => void;
}

const ManufacturingSlipModal: React.FC<ManufacturingSlipModalProps> = ({ job, customer, patterns, onClose }) => {
  const [isClient, setIsClient] = useState(false);

  useEffect(() => {
    // @react-pdf/renderer client-side only, so we prevent rendering on the server.
    setIsClient(true);
  }, []);

  if (!job) {
    return null;
  }

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4 no-print"
      onClick={onClose}
    >
      <div 
        className="bg-gray-800 rounded-lg shadow-xl w-full max-w-md mx-auto flex flex-col"
        onClick={e => e.stopPropagation()}
      >
        <header className="flex justify-between items-center p-4 border-b border-gray-700 flex-shrink-0">
          <h2 className="text-xl font-bold text-teal-400">İmalat Föyü Oluştur</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white">
            <XIcon />
          </button>
        </header>

        <div className="p-6 text-center">
            <p className="text-gray-300">
                <strong className="text-white">{customer.name}</strong> müşterisinin <strong className="text-white">{job.name}</strong> işi için imalat föyü hazır.
            </p>
            <p className="text-sm text-gray-400 mt-2">
                Aşağıdaki butona tıklayarak föyü PDF formatında indirebilirsiniz. Bu dosyayı daha sonra paylaşabilir veya yazdırabilirsiniz.
            </p>
            <div className="mt-6">
                {isClient && (
                    <PDFDownloadLink
                        document={<ManufacturingSlipPDF job={job} customer={customer} patterns={patterns} />}
                        fileName={`Foy_${customer.name.replace(/\s+/g, '_')}_${job.name.replace(/\s+/g, '_')}.pdf`}
