const EditJobForm: React.FC<{
    job: Job;
    patterns: Pattern[];
    onSave: (updatedJob: Job) => void;
    onCancel: () => void;
}> = ({ job, patterns, onSave, onCancel }) => {
    const [name, setName] = useState(job.name);
    const [patternDetails, setPatternDetails] = useState<PatternDetail[]>(job.patternDetails);
    const [discountAmount, setDiscountAmount] = useState(job.discountAmount?.toString() || '');
    const [price, setPrice] = useState(job.price.toString());
    const [notes, setNotes] = useState(job.notes || '');
    const [fabricType, setFabricType] = useState(job.fabricType || '');
    const [fabricColor, setFabricColor] = useState(job.fabricColor || '');
    const [deadline, setDeadline] = useState(job.deadline ? job.deadline.split('T')[0] : '');
    const [personInCharge, setPersonInCharge] = useState(job.personInCharge || '');

    // State for adding a new pattern detail
    const [isAddingPattern, setIsAddingPattern] = useState(false);
    const [currentPatternName, setCurrentPatternName] = useState(patterns.length > 0 ? patterns[0].name : '');
    const [currentFabricLength, setCurrentFabricLength] = useState('');
    const [currentPricePerMeter, setCurrentPricePerMeter] = useState('');
    const [isPatternModalOpen, setIsPatternModalOpen] = useState(false);

    useEffect(() => {
        const pattern = patterns.find(p => p.name === currentPatternName);
        if (pattern) {
            setCurrentPricePerMeter(pattern.pricePerMeter.toString());
        }
    }, [currentPatternName, patterns]);

    const { priceCalculation, timeCalculation } = useMemo(() => {
        const totalFromPatterns = patternDetails.reduce((sum, detail) => sum + (detail.fabricLength * detail.pricePerMeter), 0);
        const discount = parseFloat(discountAmount) || 0;
        const totalLength = patternDetails.reduce((sum, detail) => sum + detail.fabricLength, 0);

        return {
            priceCalculation: totalFromPatterns - discount,
            timeCalculation: Math.round((totalLength / 100) * 20)
        };
    }, [patternDetails, discountAmount]);


    useEffect(() => {
        setPrice(priceCalculation.toFixed(2).toString());
    }, [priceCalculation]);

    const handleSave = (e: React.FormEvent) => {
        e.preventDefault();
        const finalPrice = parseFloat(price);
        if (name.trim() === '' || isNaN(finalPrice) || patternDetails.length === 0) return;

        const updatedJob: Job = {
            ...job,
            name: name.trim(),
            price: finalPrice,
            patternDetails: patternDetails,
            discountAmount: parseFloat(discountAmount) > 0 ? parseFloat(discountAmount) : undefined,
            estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
            notes: notes.trim(),
            fabricType: fabricType.trim(),
            fabricColor: fabricColor.trim(),
            deadline: deadline ? new Date(deadline).toISOString() : undefined,
            personInCharge: personInCharge.trim(),
        };
        onSave(updatedJob);
    };

    const handlePatternSelect = (pattern: Pattern) => {
        setCurrentPatternName(pattern.name);
        setCurrentPricePerMeter(pattern.pricePerMeter.toString());
        setIsPatternModalOpen(false);
    };

    const handleAddPatternDetail = () => {
        const length = parseFloat(currentFabricLength);
        const ppm = parseFloat(currentPricePerMeter);

        if(currentPatternName && !isNaN(length) && length > 0 && !isNaN(ppm)) {
            const newDetail: PatternDetail = {
                id: Date.now().toString(),
                patternName: currentPatternName,
                fabricLength: length,
                pricePerMeter: ppm
            };
            setPatternDetails([...patternDetails, newDetail]);
            // Reset form
            setCurrentFabricLength('');
            setIsAddingPattern(false);
        }
    };

    const handleRemovePatternDetail = (id: string) => {
        setPatternDetails(patternDetails.filter(d => d.id !== id));
    };


    return (
        <>
            <form onSubmit={handleSave} className="bg-gray-700 p-4 rounded-lg shadow-md space-y-3">
                <h4 className="text-lg font-semibold text-teal-400 border-b border-gray-600 pb-2 mb-3">İşi Düzenle</h4>
                <input type="text" value={name} onChange={(e) => setName(e.target.value)} placeholder="İş Adı / Modeli" className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                <div className="flex gap-2">
                    <input type="text" value={fabricType} onChange={e => setFabricType(e.target.value)} placeholder="Kumaş Türü" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <input type="text" value={fabricColor} onChange={e => setFabricColor(e.target.value)} placeholder="Kumaş Rengi" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                </div>
                <div className="flex gap-2">
                    <input type="date" value={deadline} onChange={e => setDeadline(e.target.value)} placeholder="Termin Tarihi" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <input type="text" value={personInCharge} onChange={e => setPersonInCharge(e.target.value)} placeholder="Sorumlu Kişi" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                </div>

                {/* Pattern Details List */}
                <div className="space-y-2">
                    <h5 className="text-md font-semibold text-gray-300">Kalıp Detayları</h5>
                    {patternDetails.length > 0 ? (
                        <ul className="divide-y divide-gray-600">
                            {patternDetails.map(detail => (
                                <li key={detail.id} className="flex justify-between items-center py-2">
                                    <div className="text-sm">
                                        <p className="font-bold text-gray-200">{detail.patternName}</p>
                                        <p className="text-gray-400">{detail.fabricLength}m x {formatCurrency(detail.pricePerMeter)}/m</p>
                                    </div>
                                    <button type="button" onClick={() => handleRemovePatternDetail(detail.id)} className="text-red-500 hover:text-red-400"><TrashIcon className="h-4 w-4"/></button>
                                </li>
                            ))}
                        </ul>
                    ) : <p className="text-xs text-gray-400 text-center p-2 bg-gray-600 rounded-md">Henüz kalıp eklenmedi.</p>}
                </div>

                {/* Add new pattern detail form */}
                {isAddingPattern ? (
                    <div className="p-3 bg-gray-600 rounded-lg space-y-2">
                         <PatternDisplayButton patterns={patterns} value={currentPatternName} onClick={() => setIsPatternModalOpen(true)} />
                         <div className="flex gap-2">
                            <input type="number" value={currentFabricLength} onChange={(e) => setCurrentFabricLength(e.target.value)} placeholder="Metraj (m)" className="w-1/2 bg-gray-500 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                            <input type="number" step="0.01" value={currentPricePerMeter} onChange={(e) => setCurrentPricePerMeter(e.target.value)} placeholder="Metre Fiyatı" className="w-1/2 bg-gray-500 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                         </div>
                         <div className="flex justify-end gap-2">
                            <button type="button" onClick={() => setIsAddingPattern(false)} className="text-xs px-2 py-1 bg-gray-500 rounded-md">İptal</button>
                            <button type="button" onClick={handleAddPatternDetail} className="text-xs px-2 py-1 bg-teal-600 rounded-md">Ekle</button>
                         </div>
                    </div>
                ) : (
                    <button type="button" onClick={() => setIsAddingPattern(true)} className="w-full text-center text-sm py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                        Kalıp Ekle
                    </button>
                )}

                <div className="flex gap-2">
                    <input type="number" step="0.01" value={discountAmount} onChange={(e) => setDiscountAmount(e.target.value)} placeholder="İskonto Tutarı (TRY)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <input type="number" value={price} onChange={(e) => setPrice(e.target.value)} placeholder="Nihai Fiyat (TRY)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                </div>
                <textarea value={notes} onChange={(e) => setNotes(e.target.value)} placeholder="İş ile ilgili notlar..." className="w-full bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" rows={3} />
                {timeCalculation > 0 && <p className="text-xs text-center text-gray-400">Tahmini Süre: {Math.floor(timeCalculation / 60)} sa {timeCalculation % 60} dk</p>}
                <div className="flex justify-end gap-2"><button type="button" onClick={onCancel} className="px-3 py-1 bg-gray-500 text-white font-semibold rounded-lg hover:bg-gray-400">İptal</button><button type="submit" className="px-3 py-1 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 flex items-center gap-1"><SaveIcon/> Kaydet</button></div>
            </form>
            <PatternSelectorModal isOpen={isPatternModalOpen} patterns={patterns} onSelect={handlePatternSelect} onClose={() => setIsPatternModalOpen(false)} />
        </>
    );
};


interface JobItemProps {
    job: Job;
    customerId: string;
    setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
    onDeleteRequest: (jobId: string) => void;
    onImageClick: (imageUrl: string) => void;
    onDeletePhotoRequest: (photoIndex: number) => void;
    isEditing: boolean;
    onEditRequest: (jobId: string) => void;
    onSave: (job: Job) => void;
    onCancel: () => void;
    patterns: Pattern[];
    onGenerateSlip: (job: Job) => void;
    onGenerateInvoice: (job: Job) => void;
}

const JobItem: React.FC<JobItemProps> = ({ job, customerId, setCustomers, onDeleteRequest, onImageClick, onDeletePhotoRequest, isEditing, onEditRequest, onSave, onCancel, patterns, onGenerateSlip, onGenerateInvoice }) => {
    const [paymentAmount, setPaymentAmount] = useState('');
    const [notesVisible, setNotesVisible] = useState(false);
    const [isEditingWasted, setIsEditingWasted] = useState(false);
    const [wastedFabricInput, setWastedFabricInput] = useState(job.wastedFabricLength?.toString() || '');
    const balance = job.price - job.paidAmount;

    const totalFabricLength = useMemo(() => {
        return job.patternDetails.reduce((sum, detail) => sum + detail.fabricLength, 0);
    }, [job.patternDetails]);

    const handleAddPayment = () => {
        const amount = parseFloat(paymentAmount);
        if (isNaN(amount) || amount <= 0) return;

        setCustomers(prevCustomers => prevCustomers.map(c => {
            if (c.id === customerId) {
                return { ...c, jobs: c.jobs.map(j => j.id === job.id ? { ...j, paidAmount: j.paidAmount + amount } : j) };
            }
            return c;
        }));
        setPaymentAmount('');
    };

    const handleSubtractPayment = () => {
        const amount = parseFloat(paymentAmount);
        if (isNaN(amount) || amount <= 0) return;

        setCustomers(prevCustomers => prevCustomers.map(c => {
            if (c.id === customerId) {
                return {
                    ...c,
                    jobs: c.jobs.map(j => {
                        if (j.id === job.id) {
                            const newPaidAmount = Math.max(0, j.paidAmount - amount);
                            return { ...j, paidAmount: newPaidAmount };
                        }
                        return j;
                    })
                };
            }
            return c;
        }));
        setPaymentAmount('');
    };

    const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files.length > 0) {
            const files = Array.from(e.target.files);
            const base64Photos = await Promise.all(files.map((file: File) => compressAndEncodeImage(file)));
            setCustomers(prev => prev.map(c => c.id === customerId ? { ...c, jobs: c.jobs.map(j => j.id === job.id ? { ...j, photos: [...(j.photos || []), ...base64Photos] } : j) } : c));
        }
    };

    const handleSaveWastedFabric = () => {
        const amount = parseFloat(wastedFabricInput);
        const finalAmount = isNaN(amount) || amount <= 0 ? undefined : amount;

        setCustomers(prevCustomers => prevCustomers.map(c => {
            if (c.id === customerId) {
                return { 
                    ...c, 
                    jobs: c.jobs.map(j => 
                        j.id === job.id ? { ...j, wastedFabricLength: finalAmount } : j
                    ) 
                };
            }
            return c;
        }));
        setIsEditingWasted(false);
    };

    const formatTime = (minutes?: number) => {
        if (minutes === undefined) return 'N/A';
        const hours = Math.floor(minutes / 60);
        const mins = minutes % 60;
        return `${hours > 0 ? `${hours} sa ` : ''}${mins} dk`;
    };

    if (isEditing) {
        return <li className="bg-gray-800 p-0 rounded-lg shadow-md"><EditJobForm job={job} patterns={patterns} onSave={onSave} onCancel={onCancel} /></li>
    }

    const balanceColor = balance > 0 ? 'text-red-400' : balance < 0 ? 'text-blue-400' : 'text-green-400';

    return (
        <li className="bg-gray-800 p-4 rounded-lg shadow-md space-y-4">
            <div className="flex justify-between items-start">
                <div>
                     <p className="font-semibold text-lg text-gray-200 flex items-center gap-2">
                        {job.name}
                        {job.discountAmount && job.discountAmount > 0 && (<span className="text-xs bg-teal-600 text-teal-100 font-bold px-2 py-0.5 rounded-full">{formatCurrency(job.discountAmount)} İndirim</span>)}
                    </p>
                    <div className="text-sm text-gray-400 mt-1">
                        {formatDate(job.createdAt)} &bull; Toplam <span className="font-bold">{totalFabricLength}m</span>
                        <ul className="text-xs list-disc list-inside pl-2 mt-1">
                            {job.patternDetails.map(d => <li key={d.id}>{d.patternName} - {d.fabricLength}m</li>)}
                        </ul>
                    </div>
                    <p className="text-xs text-gray-500 mt-1">Tahmini Süre: {formatTime(job.estimatedTimeMinutes)}</p>
                </div>
                <div className="flex flex-col items-end gap-2">
                    <div className="flex gap-2">
                      <button onClick={() => onEditRequest(job.id)} className="text-gray-500 hover:text-teal-400 transition-colors" aria-label="İşi Düzenle"><EditIcon /></button>
                      <button onClick={() => onDeleteRequest(job.id)} className="text-gray-500 hover:text-red-500 transition-colors" aria-label="İşi Sil"><TrashIcon /></button>
                    </div>
                    <div className="flex gap-2 mt-2">
                        <button onClick={() => onGenerateSlip(job)} className="flex items-center gap-2 text-xs px-2 py-1 bg-gray-600 hover:bg-gray-500 text-white rounded-md transition-colors" aria-label="İmalat Föyü Oluştur">
                            <PrintIcon /> Föy
                        </button>
                        <button onClick={() => onGenerateInvoice(job)} className="flex items-center gap-2 text-xs px-2 py-1 bg-blue-600 hover:bg-blue-500 text-white rounded-md transition-colors" aria-label="Fatura Oluştur">
                            <BillIcon /> Fatura
                        </button>
                    </div>
                </div>
            </div>

            {job.photos && job.photos.length > 0 && (
                <div className="grid grid-cols-3 sm:grid-cols-4 gap-2">
                    {job.photos.map((photo, index) => (
                        <div key={index} className="relative group aspect-square">
                            <button
                                onClick={(e) => {
                                    e.stopPropagation();
                                    onDeletePhotoRequest(index);
                                }}
                                className="absolute top-1 right-1 z-10 p-1 bg-red-600/80 hover:bg-red-500 rounded-full text-white"
                                aria-label="Fotoğrafı Sil"
                            >
                                <TrashIcon className="h-4 w-4" />
                            </button>
                            <button
                                onClick={() => onImageClick(photo)}
                                className="w-full h-full focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-offset-gray-800 focus:ring-teal-500 rounded-md"
                            >
                                <img src={photo} alt={`Job photo ${index + 1}`} className="rounded-md object-cover w-full h-full" />
                            </button>
                        </div>
                    ))}
                </div>
            )}

            {job.notes && (
                <div className="border-t border-gray-700 pt-3">
                    <button 
                        onClick={() => setNotesVisible(!notesVisible)}
                        className="flex items-center gap-2 text-sm text-teal-400 font-semibold w-full text-left"
                    >
                        <NoteIcon /> Notları {notesVisible ? 'Gizle' : 'Göster'}
                    </button>
                    {notesVisible && (
                        <div className="mt-2 p-3 bg-gray-700/50 rounded-md">
                            <pre className="text-gray-300 text-sm whitespace-pre-wrap font-sans">{job.notes}</pre>
                        </div>
                    )}
                </div>
            )}

            <div className="border-t border-gray-700 pt-3 space-y-2">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-2">
                        <ScissorsIcon />
                        <span className="text-sm font-semibold text-gray-300">Bozuk Kumaş:</span>
                        {!isEditingWasted && (
                            <span className="text-sm text-yellow-400 font-bold">{job.wastedFabricLength ? `${job.wastedFabricLength} m` : 'Girilmedi'}</span>
                        )}
                    </div>
                    <button onClick={() => setIsEditingWasted(!isEditingWasted)} className="text-xs px-2 py-1 bg-gray-600 hover:bg-gray-500 rounded-md">
                        {isEditingWasted ? 'İptal' : 'Düzenle'}
                    </button>
                </div>
                {isEditingWasted && (
                    <div className="flex items-center gap-2 pl-7">
                        <input
                            type="number"
                            step="0.01"
                            value={wastedFabricInput}
                            onChange={(e) => setWastedFabricInput(e.target.value)}
                            placeholder="Metre"
                            className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none w-full min-w-0"
                        />
                        <button onClick={handleSaveWastedFabric} className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500">
                            Kaydet
                        </button>
                    </div>
                )}
            </div>

            <div className="grid grid-cols-3 gap-2 text-center border-t border-b border-gray-700 py-3">
                <div><p className="text-xs text-gray-400">Fiyat</p><p className="font-semibold text-gray-100">{formatCurrency(job.price)}</p></div>
                <div><p className="text-xs text-gray-400">Ödenen</p><p className="font-semibold text-green-400">{formatCurrency(job.paidAmount)}</p></div>
                <div><p className="text-xs text-gray-400">Kalan</p><p className={`font-semibold ${balanceColor}`}>{formatCurrency(balance)}</p></div>
            </div>

            <div className="flex gap-2 items-center">
                <div className="flex-grow flex gap-2">
                    <input
                        type="number"
                        step="0.01"
                        value={paymentAmount}
                        onChange={(e) => setPaymentAmount(e.target.value)}
                        placeholder="Ödeme/İade Tutarı"
                        className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none w-full min-w-0"
                    />
                    <button
                        type="button"
                        onClick={handleAddPayment}
                        className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 transition-colors disabled:opacity-50"
                        disabled={!paymentAmount}
                    >
                        Ekle
                    </button>
                    <button
                        type="button"
                        onClick={handleSubtractPayment}
                        className="px-3 py-2 bg-red-600 text-white font-semibold rounded-lg hover:bg-red-500 transition-colors disabled:opacity-50"
                        disabled={!paymentAmount || job.paidAmount <= 0}
                    >
                        Geri Al
                    </button>
                </div>
                <label title="Galeriden Yükle" className="cursor-pointer p-2 bg-blue-600 text-white rounded-lg hover:bg-blue-500 transition-colors"><ImageIcon /><input type="file" multiple accept="image/*" className="hidden" onChange={handlePhotoUpload} /></label>
                <label title="Fotoğraf Çek" className="cursor-pointer p-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-500 transition-colors"><CameraIcon /><input type="file" accept="image/*" capture="environment" className="hidden" onChange={handlePhotoUpload} /></label>
            </div>
        </li>
    );
};


interface CustomerDetailScreenProps {
  customer: Customer;
  setCustomers: React.Dispatch<React.SetStateAction<Customer[]>>;
  onBack: () => void;
  patterns: Pattern[];
}

const CustomerDetailScreen: React.FC<CustomerDetailScreenProps> = ({ customer, setCustomers, onBack, patterns }) => {
  const [isAddingJob, setIsAddingJob] = useState(false);
  const [jobToDelete, setJobToDelete] = useState<string | null>(null);
  const [photoToDelete, setPhotoToDelete] = useState<{ jobId: string; photoIndex: number } | null>(null);
  const [toastInfo, setToastInfo] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
  const [jobForSlip, setJobForSlip] = useState<Job | null>(null);
  const [jobForInvoice, setJobForInvoice] = useState<Job | null>(null);

  // Customer Name Edit State
  const [isEditingName, setIsEditingName] = useState(false);
  const [editedName, setEditedName] = useState(customer.name);

  // Customer Info Edit State
  const [isEditingInfo, setIsEditingInfo] = useState(false);
  const [editedPhone, setEditedPhone] = useState(customer.phone || '');
  const [editedContact, setEditedContact] = useState(customer.contactPerson || '');
  const [editedAddress, setEditedAddress] = useState(customer.address || '');
  const [editedLocation, setEditedLocation] = useState(customer.location);
  const [isFetchingLocation, setIsFetchingLocation] = useState(false);
  const [isMapOpen, setIsMapOpen] = useState(false);

  const [editingJobId, setEditingJobId] = useState<string | null>(null);
  const [lightboxImage, setLightboxImage] = useState<string | null>(null);

  // New Job Form State
  const [newJobName, setNewJobName] = useState('');
  const [newJobPatternDetails, setNewJobPatternDetails] = useState<PatternDetail[]>([]);
  const [newJobDiscountAmount, setNewJobDiscountAmount] = useState('');
  const [newJobPrice, setNewJobPrice] = useState('0');
  const [newJobNotes, setNewJobNotes] = useState('');
  const [newJobFabricType, setNewJobFabricType] = useState('');
  const [newJobFabricColor, setNewJobFabricColor] = useState('');
  const [newJobDeadline, setNewJobDeadline] = useState('');
  const [newJobPersonInCharge, setNewJobPersonInCharge] = useState('');

  // State for adding a single pattern detail to a new job
  const [isAddingPattern, setIsAddingPattern] = useState(false);
  const [currentPatternName, setCurrentPatternName] = useState(patterns.length > 0 ? patterns[0].name : '');
  const [currentFabricLength, setCurrentFabricLength] = useState('');
  const [currentPricePerMeter, setCurrentPricePerMeter] = useState('');
  const [isPatternModalOpen, setIsPatternModalOpen] = useState(false);

  useEffect(() => {
    const pattern = patterns.find(p => p.name === currentPatternName);
    if(pattern) {
        setCurrentPricePerMeter(pattern.pricePerMeter.toString());
    }
  }, [currentPatternName, patterns]);


  const { priceCalculation, timeCalculation } = useMemo(() => {
    const totalFromPatterns = newJobPatternDetails.reduce((sum, detail) => sum + (detail.fabricLength * detail.pricePerMeter), 0);
    const discount = parseFloat(newJobDiscountAmount) || 0;
    const totalLength = newJobPatternDetails.reduce((sum, detail) => sum + detail.fabricLength, 0);

    return {
        priceCalculation: totalFromPatterns - discount,
        timeCalculation: Math.round((totalLength / 100) * 20)
    };
  }, [newJobPatternDetails, newJobDiscountAmount]);

  useEffect(() => { setNewJobPrice(priceCalculation.toFixed(2).toString()); }, [priceCalculation]);
  useEffect(() => { 
    setEditedName(customer.name);
    setEditedPhone(customer.phone || '');
    setEditedContact(customer.contactPerson || '');
    setEditedAddress(customer.address || '');
    setEditedLocation(customer.location);
  }, [customer]);

  const resetForm = () => {
    setNewJobName(''); 
    setNewJobPatternDetails([]);
    setNewJobDiscountAmount(''); 
    setNewJobPrice('0'); 
    setNewJobNotes(''); 
    setNewJobFabricType('');
    setNewJobFabricColor('');
    setNewJobDeadline('');
    setNewJobPersonInCharge('');
    setIsAddingJob(false);
    setIsAddingPattern(false);
  };

  const handlePatternSelect = (pattern: Pattern) => { 
    setCurrentPatternName(pattern.name);
    setCurrentPricePerMeter(pattern.pricePerMeter.toString());
    setIsPatternModalOpen(false); 
  };

  const handleAddPatternDetail = () => {
    const length = parseFloat(currentFabricLength);
    const ppm = parseFloat(currentPricePerMeter);
    if (currentPatternName && !isNaN(length) && length > 0 && !isNaN(ppm)) {
        const newDetail: PatternDetail = {
            id: Date.now().toString(),
            patternName: currentPatternName,
            fabricLength: length,
            pricePerMeter: ppm,
        };
        setNewJobPatternDetails([...newJobPatternDetails, newDetail]);
        // Reset local form
        setCurrentFabricLength('');
        setIsAddingPattern(false);
    } else {
        setToastInfo({ message: "Lütfen geçerli metraj ve fiyat girin.", type: 'error' });
    }
  };

  const handleRemovePatternDetail = (id: string) => {
    setNewJobPatternDetails(newJobPatternDetails.filter(d => d.id !== id));
  };


  const handleAddJob = (e: React.FormEvent) => {
    e.preventDefault();
    const price = parseFloat(newJobPrice);
    if (newJobName.trim() === '' || isNaN(price) || newJobPatternDetails.length === 0) {
        setToastInfo({ message: "İş adı ve en az bir kalıp detayı girilmelidir.", type: 'error' });
        return;
    }

    const newJob: Job = {
      id: Date.now().toString(), name: newJobName.trim(), price: price, paidAmount: 0, createdAt: new Date().toISOString(),
      patternDetails: newJobPatternDetails, photos: [],
      estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
      discountAmount: parseFloat(newJobDiscountAmount) > 0 ? parseFloat(newJobDiscountAmount) : undefined,
      notes: newJobNotes.trim(),
      fabricType: newJobFabricType.trim(),
      fabricColor: newJobFabricColor.trim(),
      deadline: newJobDeadline ? new Date(newJobDeadline).toISOString() : undefined,
      personInCharge: newJobPersonInCharge.trim(),
    };
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: [newJob, ...c.jobs] } : c));
    resetForm();
    setToastInfo({ message: "Yeni iş başarıyla eklendi.", type: 'success' });
  };

  const handleSaveJob = (updatedJob: Job) => {
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: c.jobs.map(j => j.id === updatedJob.id ? updatedJob : j) } : c));
    setEditingJobId(null);
  };

  const handleDeleteRequest = (jobId: string) => setJobToDelete(jobId);
  const handleConfirmDelete = () => {
    if (!jobToDelete) return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: c.jobs.filter(job => job.id !== jobToDelete) } : c));
    setJobToDelete(null);
  };

  const handleDeletePhotoRequest = (jobId: string, photoIndex: number) => {
    setPhotoToDelete({ jobId, photoIndex });
  };

  const handleConfirmPhotoDelete = () => {
    if (!photoToDelete) return;
    const { jobId, photoIndex } = photoToDelete;

    setCustomers(prevCustomers => prevCustomers.map(c => {
        if (c.id === customer.id) {
            return {
                ...c,
                jobs: c.jobs.map(j => {
                    if (j.id === jobId) {
                        const updatedPhotos = j.photos?.filter((_, index) => index !== photoIndex);
                        return { ...j, photos: updatedPhotos };
                    }
                    return j;
                })
            };
        }
        return c;
    }));

    setPhotoToDelete(null);
  };


  const handleSaveName = () => {
    if (editedName.trim() === '') return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, name: editedName.trim() } : c));
    setIsEditingName(false);
  };

  const handleSaveInfo = () => {
    setCustomers(prev => prev.map(c => c.id === customer.id ? { 
        ...c, 
        phone: editedPhone.trim(),
        contactPerson: editedContact.trim(),
        address: editedAddress.trim(),
        location: editedLocation
     } : c));
    setIsEditingInfo(false);
  };

  const handleCancelEditInfo = () => {
    setEditedPhone(customer.phone || '');
    setEditedContact(customer.contactPerson || '');
    setEditedAddress(customer.address || '');
    setEditedLocation(customer.location);
    setIsEditingInfo(false);
  };

  const handleLocationSelectFromMap = async (location: { lat: number, lng: number }) => {
    setIsMapOpen(false);
    setIsFetchingLocation(true);
    try {
        const address = await getAddressFromCoordinates(location.lat, location.lng);
        setEditedAddress(address);
        setEditedLocation(location);
        setToastInfo({ message: "Adres alınıp forma eklendi. Kaydetmeyi unutmayın.", type: 'success' });
    } catch (error) {
        console.error("Failed to fetch address:", error);
        setToastInfo({ message: 'Adres bilgisi alınamadı.', type: 'error' });
    } finally {
        setIsFetchingLocation(false);
    }
  };

  const handleShareLocation = async () => {
    if (navigator.share && customer.location) {
        const mapUrl = `https://www.google.com/maps?q=${customer.location.lat},${customer.location.lng}`;
        try {
            await navigator.share({
                title: `${customer.name} Konumu`,
                text: `${customer.name} için adres bilgisi.`,
                url: mapUrl,
            });
        } catch (error) {
            console.error('Error sharing location:', error);
        }
    } else {
        alert('Cihazınız paylaşma özelliğini desteklemiyor veya konum kayıtlı değil.');
    }
  };


  return (
    <div>
      {toastInfo && <Toast message={toastInfo.message} type={toastInfo.type} show={!!toastInfo} onClose={() => setToastInfo(null)} />}
      <div className="flex justify-between items-center mb-4">
        <button onClick={onBack} className="flex items-center gap-2 text-teal-400 hover:text-teal-300"><BackIcon /> Geri</button>
        {isEditingName ? (
            <div className="flex-grow flex items-center gap-2 mx-2">
                <input type="text" value={editedName} onChange={(e) => setEditedName(e.target.value)} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 text-2xl font-bold focus:ring-2 focus:ring-teal-500 focus:outline-none" autoFocus />
                <button onClick={handleSaveName} className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500">Kaydet</button>
                <button onClick={() => setIsEditingName(false)} className="px-3 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-500">İptal</button>
            </div>
        ) : (
             <div className="flex items-center gap-3">
                <h2 className="text-2xl font-bold text-teal-400 text-center truncate">{customer.name}</h2>
                <button onClick={() => setIsEditingName(true)} className="text-gray-400 hover:text-white"><EditIcon /></button>
            </div>
        )}
        <div className="w-16"></div>
      </div>

       {/* Customer Info Section */}
       <div className="bg-gray-800 p-4 rounded-lg shadow-md mb-6">
        <div className="flex justify-between items-center mb-3">
          <h3 className="text-lg font-semibold text-teal-400">Müşteri Bilgileri</h3>
          {!isEditingInfo && <button onClick={() => setIsEditingInfo(true)} className="text-gray-400 hover:text-white flex items-center gap-1 text-sm"><EditIcon /> Düzenle</button>}
        </div>
        {isEditingInfo ? (
            <div className="space-y-3">
                <input type="tel" value={editedPhone} onChange={e => setEditedPhone(e.target.value)} placeholder="Telefon Numarası" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"/>
                <input type="text" value={editedContact} onChange={e => setEditedContact(e.target.value)} placeholder="Yetkili Kişi" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"/>
                <textarea value={editedAddress} onChange={e => setEditedAddress(e.target.value)} placeholder="Adres" rows={3} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"/>
                <button type="button" onClick={() => setIsMapOpen(true)} disabled={isFetchingLocation} className="w-full text-center px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-500 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
                    {isFetchingLocation ? 'Adres Aranıyor...' : 'Haritadan Seç'}
                </button>
                <div className="flex justify-end gap-2"><button type="button" onClick={handleCancelEditInfo} className="px-3 py-1 bg-gray-500 text-white font-semibold rounded-lg hover:bg-gray-400">İptal</button><button onClick={handleSaveInfo} className="px-3 py-1 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 flex items-center gap-1"><SaveIcon/> Kaydet</button></div>
            </div>
        ) : (
             <div className="space-y-2 text-sm">
                <p><strong className="text-gray-400 w-20 inline-block">Telefon:</strong> {customer.phone || 'Belirtilmemiş'}</p>
                <p><strong className="text-gray-400 w-20 inline-block">Yetkili:</strong> {customer.contactPerson || 'Belirtilmemiş'}</p>
                <p className="flex items-start"><strong className="text-gray-400 w-20 inline-block flex-shrink-0">Adres:</strong> <span className="flex-1">{customer.address || 'Belirtilmemiş'}</span></p>
                {customer.location && (
                   <div className="flex items-center gap-4 mt-2">
                     <a href={`https://www.google.com/maps?q=${customer.location.lat},${customer.location.lng}`} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1 text-blue-400 hover:text-blue-300">
                        <MapPinIcon /> Haritada Göster
                    </a>
                    {navigator.share && (
                        <button onClick={handleShareLocation} className="inline-flex items-center gap-1 text-blue-400 hover:text-blue-300">
                            <ShareIcon /> Paylaş
                        </button>
                    )}
                   </div>
                )}
            </div>
        )}
      </div>

      <div className="flex justify-between items-center my-6">
        <h3 className="text-xl font-semibold">İşler</h3>
        <button onClick={() => setIsAddingJob(!isAddingJob)} className="inline-flex items-center gap-2 px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors"><PlusIcon /> {isAddingJob ? 'Kapat' : 'Yeni İş'}</button>
      </div>

      {isAddingJob && (
        <form onSubmit={handleAddJob} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-4">
          <input type="text" value={newJobName} onChange={(e) => setNewJobName(e.target.value)} placeholder="İş Adı / Modeli" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
          <div className="flex gap-2">
            <input type="text" value={newJobFabricType} onChange={e => setNewJobFabricType(e.target.value)} placeholder="Kumaş Türü" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
            <input type="text" value={newJobFabricColor} onChange={e => setNewJobFabricColor(e.target.value)} placeholder="Kumaş Rengi" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
          </div>
          <div className="flex gap-2">
            <input type="date" value={newJobDeadline} onChange={e => setNewJobDeadline(e.target.value)} placeholder="Termin Tarihi" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
            <input type="text" value={newJobPersonInCharge} onChange={e => setNewJobPersonInCharge(e.target.value)} placeholder="Sorumlu Kişi" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
          </div>
           {/* Pattern Details List */}
            <div className="space-y-2">
                <h5 className="text-md font-semibold text-gray-300">Kalıp Detayları</h5>
                {newJobPatternDetails.length > 0 ? (
                    <ul className="divide-y divide-gray-700">
                        {newJobPatternDetails.map(detail => (
                            <li key={detail.id} className="flex justify-between items-center py-2">
                                <div className="text-sm">
                                    <p className="font-bold text-gray-200">{detail.patternName}</p>
                                    <p className="text-gray-400">{detail.fabricLength}m x {formatCurrency(detail.pricePerMeter)}/m = {formatCurrency(detail.fabricLength * detail.pricePerMeter)}</p>
                                </div>
                                <button type="button" onClick={() => handleRemovePatternDetail(detail.id)} className="text-red-500 hover:text-red-400"><TrashIcon className="h-4 w-4"/></button>
                            </li>
                        ))}
                    </ul>
                ) : <p className="text-xs text-gray-500 text-center p-2 bg-gray-700 rounded-md">Henüz kalıp eklenmedi.</p>}
            </div>

            {/* Add new pattern detail form */}
            {isAddingPattern ? (
                <div className="p-3 bg-gray-700 rounded-lg space-y-2">
                        <PatternDisplayButton patterns={patterns} value={currentPatternName} onClick={() => setIsPatternModalOpen(true)} />
                        <div className="flex gap-2">
                        <input type="number" value={currentFabricLength} onChange={(e) => setCurrentFabricLength(e.target.value)} placeholder="Metraj (m)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                        <input type="number" step="0.01" value={currentPricePerMeter} onChange={(e) => setCurrentPricePerMeter(e.target.value)} placeholder="Metre Fiyatı" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                        </div>
                        <div className="flex justify-end gap-2">
                        <button type="button" onClick={() => setIsAddingPattern(false)} className="text-xs px-2 py-1 bg-gray-500 rounded-md">İptal</button>
                        <button type="button" onClick={handleAddPatternDetail} className="text-xs px-2 py-1 bg-teal-600 rounded-md">Ekle</button>
                        </div>
                </div>
            ) : (
                <button type="button" onClick={() => setIsAddingPattern(true)} className="w-full text-center text-sm py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                    Kalıp Ekle
                </button>
            )}


          <div className="flex gap-2"><input type="number" step="0.01" value={newJobDiscountAmount} onChange={(e) => setNewJobDiscountAmount(e.target.value)} placeholder="İskonto Tutarı (TRY)" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" /><input type="text" value={formatCurrency(parseFloat(newJobPrice))} placeholder="Nihai Fiyat (TRY)" className="w-1/2 bg-gray-700 text-gray-400 rounded-md p-2" readOnly /></div>
          <textarea value={newJobNotes} onChange={(e) => setNewJobNotes(e.target.value)} placeholder="İş ile ilgili notlar ekleyin (isteğe bağlı)..." className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" rows={2} />
          {timeCalculation > 0 && <p className="text-xs text-center text-gray-400">Tahmini Süre: {Math.floor(timeCalculation / 60)} sa {timeCalculation % 60} dk</p>}
          <div className="flex justify-end"><button type="submit" className="px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">İş Ekle</button></div>
        </form>
      )}
      <PatternSelectorModal isOpen={isPatternModalOpen} patterns={patterns} onSelect={handlePatternSelect} onClose={() => setIsPatternModalOpen(false)} />

      <MapSelectorModal isOpen={isMapOpen} onClose={() => setIsMapOpen(false)} onLocationSelect={handleLocationSelectFromMap} />

      <ul className="space-y-4">
        {customer.jobs.length > 0 ? customer.jobs.map(job => (<JobItem key={job.id} job={job} customerId={customer.id} setCustomers={setCustomers} onDeleteRequest={handleDeleteRequest} onImageClick={setLightboxImage} onDeletePhotoRequest={(photoIndex) => handleDeletePhotoRequest(job.id, photoIndex)} isEditing={editingJobId === job.id} onEditRequest={setEditingJobId} onSave={handleSaveJob} onCancel={() => setEditingJobId(null)} patterns={patterns} onGenerateSlip={setJobForSlip} onGenerateInvoice={setJobForInvoice} />)) : <p className="text-gray-500 text-center py-4">Bu müşteri için henüz iş eklenmemiş.</p>}
      </ul>

      {lightboxImage && <ImageLightbox src={lightboxImage} onClose={() => setLightboxImage(null)} />}

      {jobForSlip && <ManufacturingSlipModal job={jobForSlip} customer={customer} patterns={patterns} onClose={() => setJobForSlip(null)} />}

      {jobForInvoice && <InvoiceModal job={jobForInvoice} customer={customer} patterns={patterns} onClose={() => setJobForInvoice(null)} />}

      <ConfirmationModal isOpen={!!jobToDelete} onClose={() => setJobToDelete(null)} onConfirm={handleConfirmDelete} title="İşi Silmeyi Onayla"><p>Bu işi kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p></ConfirmationModal>

      <ConfirmationModal
          isOpen={!!photoToDelete}
          onClose={() => setPhotoToDelete(null)}
          onConfirm={handleConfirmPhotoDelete}
          title="Fotoğrafı Silmeyi Onayla"
      >
          <p>Bu fotoğrafı kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p>
      </ConfirmationModal>
    </div>
  );
};

