import React from 'react';
import type { Customer, Job, Pattern } from '../types';
import { XIcon, PrintIcon } from './Icons';
import InvoiceHTML from './InvoiceHTML';

interface InvoiceModalProps {
  job: Job | null;
  customer: Customer;
  patterns: Pattern[];
  onClose: () => void;
}

const InvoiceModal: React.FC<InvoiceModalProps> = ({ job, customer, patterns, onClose }) => {
  if (!job) {
    return null;
  }

  const handlePrint = () => {
    window.print();
  };

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4 no-print"
      onClick={onClose}
    >
      <div 
        className="bg-gray-800 rounded-lg shadow-xl w-full max-w-3xl mx-auto flex flex-col h-[90vh]"
        onClick={e => e.stopPropagation()}
      >
        <header className="flex justify-between items-center p-4 border-b border-gray-700 flex-shrink-0">
          <h2 className="text-xl font-bold text-teal-400">Fatura</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white">
            <XIcon />
          </button>
        </header>

        <div className="p-4 bg-gray-600 overflow-y-auto flex-grow">
            <InvoiceHTML job={job} customer={customer} patterns={patterns} />
        </div>

        <footer className="flex justify-end items-center p-4 border-t border-gray-700 flex-shrink-0">
            <button
                onClick={handlePrint}
                className="inline-flex items-center gap-2 rounded-md border border-transparent bg-teal-600 px-6 py-3 text-base font-medium text-white shadow-sm hover:bg-teal-700 transition-colors focus:outline-none focus:ring-2 focus:ring-teal-500 focus:ring-offset-2 focus:ring-offset-gray-800"
            >
                <PrintIcon />
                Yazdır
            </button>
        </footer>

      </div>
    </div>
  );
};

