                                <td className="p-2 text-right">{formatCurrency(detail.pricePerMeter)}</td>
                                <td className="p-2 text-right font-semibold">{formatCurrency(detail.fabricLength * detail.pricePerMeter)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </section>

            {/* TOTALS SECTION */}
            <section className="flex justify-end">
                <div className="w-1/2 space-y-2">
                    <div className="flex justify-between">
                        <span className="text-gray-600">Ara Toplam:</span>
                        <span className="font-semibold">{formatCurrency(subTotal)}</span>
                    </div>
                    {discount > 0 && (
                         <div className="flex justify-between">
                            <span className="text-gray-600">İskonto:</span>
                            <span className="font-semibold text-red-600">- {formatCurrency(discount)}</span>
