                    )}
                    <div className="flex justify-between border-t-2 border-b-2 border-gray-800 py-2">
                        <span className="font-bold text-lg">Genel Toplam:</span>
                        <span className="font-bold text-lg">{formatCurrency(grandTotal)}</span>
                    </div>
                     <div className="flex justify-between pt-2">
                        <span className="text-gray-600">Ödenen Tutar:</span>
                        <span className="font-semibold text-green-600">{formatCurrency(job.paidAmount)}</span>
                    </div>
                     <div className="flex justify-between">
                        <span className="font-bold text-gray-800">Kalan Bakiye:</span>
                        <span className="font-bold text-red-600">{formatCurrency(balance)}</span>
                    </div>
                </div>
            </section>

             {/* FOOTER */}
            <footer className="text-center text-gray-500 mt-12 pt-4 border-t border-gray-300">
                <p>Ödemeleriniz için teşekkür ederiz.</p>
                <p>AB AYÇAM | info@abaycam.com</p>
            </footer>
        </div>
    );
};

