    setNewJobPatternDetails([]);
    setNewJobDiscountAmount(''); 
    setNewJobPrice('0'); 
    setNewJobNotes(''); 
    setNewJobFabricType('');
    setNewJobFabricColor('');
    setNewJobDeadline('');
    setNewJobPersonInCharge('');
    setIsAddingJob(false);
    setIsAddingPattern(false);
  };

  const handlePatternSelect = (pattern: Pattern) => { 
    setCurrentPatternName(pattern.name);
    setCurrentPricePerMeter(pattern.pricePerMeter.toString());
    setIsPatternModalOpen(false); 
  };

  const handleAddPatternDetail = () => {
    const length = parseFloat(currentFabricLength);
    const ppm = parseFloat(currentPricePerMeter);
    if (currentPatternName && !isNaN(length) && length > 0 && !isNaN(ppm)) {
        const newDetail: PatternDetail = {
            id: Date.now().toString(),
            patternName: currentPatternName,
            fabricLength: length,
            pricePerMeter: ppm,
        };
        setNewJobPatternDetails([...newJobPatternDetails, newDetail]);
        // Reset local form
        setCurrentFabricLength('');
        setIsAddingPattern(false);
    } else {
        setToastInfo({ message: "Lütfen geçerli metraj ve fiyat girin.", type: 'error' });
    }
  };

  const handleRemovePatternDetail = (id: string) => {
    setNewJobPatternDetails(newJobPatternDetails.filter(d => d.id !== id));
  };


  const handleAddJob = (e: React.FormEvent) => {
    e.preventDefault();
    const price = parseFloat(newJobPrice);
    if (newJobName.trim() === '' || isNaN(price) || newJobPatternDetails.length === 0) {
        setToastInfo({ message: "İş adı ve en az bir kalıp detayı girilmelidir.", type: 'error' });
        return;
    }

    const newJob: Job = {
      id: Date.now().toString(), name: newJobName.trim(), price: price, paidAmount: 0, createdAt: new Date().toISOString(),
      patternDetails: newJobPatternDetails, photos: [],
      estimatedTimeMinutes: timeCalculation > 0 ? timeCalculation : undefined,
      estimatedCost: costCalculation > 0 ? costCalculation : undefined,
      discountAmount: parseFloat(newJobDiscountAmount) > 0 ? parseFloat(newJobDiscountAmount) : undefined,
      notes: newJobNotes.trim(),
      fabricType: newJobFabricType.trim(),
      fabricColor: newJobFabricColor.trim(),
      deadline: newJobDeadline ? new Date(newJobDeadline).toISOString() : undefined,
      personInCharge: newJobPersonInCharge.trim(),
    };
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: [newJob, ...c.jobs] } : c));
    resetForm();
    setToastInfo({ message: "Yeni iş başarıyla eklendi.", type: 'success' });
  };

  const handleSaveJob = (updatedJob: Job) => {
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: c.jobs.map(j => j.id === updatedJob.id ? updatedJob : j) } : c));
    setEditingJobId(null);
  };

  const handleDeleteRequest = (jobId: string) => setJobToDelete(jobId);
  const handleConfirmDelete = () => {
    if (!jobToDelete) return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, jobs: c.jobs.filter(job => job.id !== jobToDelete) } : c));
    setJobToDelete(null);
  };

  const handleDeletePhotoRequest = (jobId: string, photoIndex: number) => {
    setPhotoToDelete({ jobId, photoIndex });
  };

  const handleConfirmPhotoDelete = () => {
    if (!photoToDelete) return;
    const { jobId, photoIndex } = photoToDelete;

    setCustomers(prevCustomers => prevCustomers.map(c => {
        if (c.id === customer.id) {
            return {
                ...c,
                jobs: c.jobs.map(j => {
                    if (j.id === jobId) {
                        const updatedPhotos = j.photos?.filter((_, index) => index !== photoIndex);
                        return { ...j, photos: updatedPhotos };
                    }
                    return j;
                })
            };
        }
        return c;
    }));

    setPhotoToDelete(null);
  };


  const handleSaveName = () => {
    if (editedName.trim() === '') return;
    setCustomers(prev => prev.map(c => c.id === customer.id ? { ...c, name: editedName.trim() } : c));
    setIsEditingName(false);
  };

  const handleSaveInfo = () => {
    setCustomers(prev => prev.map(c => c.id === customer.id ? { 
        ...c, 
        phone: editedPhone.trim(),
        contactPerson: editedContact.trim(),
        address: editedAddress.trim(),
        location: editedLocation
     } : c));
    setIsEditingInfo(false);
  };

  const handleCancelEditInfo = () => {
    setEditedPhone(customer.phone || '');
    setEditedContact(customer.contactPerson || '');
    setEditedAddress(customer.address || '');
    setEditedLocation(customer.location);
    setIsEditingInfo(false);
  };

  const handleLocationSelectFromMap = async (location: { lat: number, lng: number }) => {
    setIsMapOpen(false);
    setIsFetchingLocation(true);
    try {
        const address = await getAddressFromCoordinates(location.lat, location.lng);
        setEditedAddress(address);
        setEditedLocation(location);
        setToastInfo({ message: "Adres alınıp forma eklendi. Kaydetmeyi unutmayın.", type: 'success' });
    } catch (error) {
        console.error("Failed to fetch address:", error);
        setToastInfo({ message: 'Adres bilgisi alınamadı.', type: 'error' });
    } finally {
        setIsFetchingLocation(false);
    }
  };

  const handleShareLocation = async () => {
    if (navigator.share && customer.location) {
        const mapUrl = `https://www.google.com/maps?q=${customer.location.lat},${customer.location.lng}`;
        try {
            await navigator.share({
                title: `${customer.name} Konumu`,
                text: `${customer.name} için adres bilgisi.`,
                url: mapUrl,
            });
        } catch (error) {
            console.error('Error sharing location:', error);
        }
    } else {
        alert('Cihazınız paylaşma özelliğini desteklemiyor veya konum kayıtlı değil.');
    }
  };

  const handleLanguageSelect = (lang: 'tr' | 'ar' | 'en') => {
    if (languageModalTarget) {
      if (languageModalTarget.type === 'invoice') {
        setInvoiceRequest({ job: languageModalTarget.job, lang: lang });
      } else {
        setSlipRequest({ job: languageModalTarget.job, lang: lang });
      }
    }
    setLanguageModalTarget(null);
  };

  return (
    <div>
      {toastInfo && <Toast message={toastInfo.message} type={toastInfo.type} show={!!toastInfo} onClose={() => setToastInfo(null)} />}
      <div className="flex justify-between items-center mb-4">
        <button onClick={onBack} className="flex items-center gap-2 text-teal-400 hover:text-teal-300"><BackIcon /> Geri</button>
        {isEditingName ? (
            <div className="flex-grow flex items-center gap-2 mx-2">
                <input type="text" value={editedName} onChange={(e) => setEditedName(e.target.value)} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 text-2xl font-bold focus:ring-2 focus:ring-teal-500 focus:outline-none" autoFocus />
                <button onClick={handleSaveName} className="px-3 py-2 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500">Kaydet</button>
                <button onClick={() => setIsEditingName(false)} className="px-3 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-500">İptal</button>
            </div>
        ) : (
             <div className="flex items-center gap-3">
                <h2 className="text-2xl font-bold text-teal-400 text-center truncate">{customer.name}</h2>
                <button onClick={() => setIsEditingName(true)} className="text-gray-400 hover:text-white"><EditIcon /></button>
            </div>
        )}
        <div className="w-16"></div>
      </div>

       {/* Customer Info Section */}
       <div className="bg-gray-800 p-4 rounded-lg shadow-md mb-6">
        <div className="flex justify-between items-center mb-3">
          <h3 className="text-lg font-semibold text-teal-400">Müşteri Bilgileri</h3>
          {!isEditingInfo && <button onClick={() => setIsEditingInfo(true)} className="text-gray-400 hover:text-white flex items-center gap-1 text-sm"><EditIcon /> Düzenle</button>}
        </div>
        {isEditingInfo ? (
            <div className="space-y-3">
                <input type="tel" value={editedPhone} onChange={e => setEditedPhone(e.target.value)} placeholder="Telefon Numarası" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"/>
                <input type="text" value={editedContact} onChange={e => setEditedContact(e.target.value)} placeholder="Yetkili Kişi" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"/>
                <textarea value={editedAddress} onChange={e => setEditedAddress(e.target.value)} placeholder="Adres" rows={3} className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"/>
                <button type="button" onClick={() => setIsMapOpen(true)} disabled={isFetchingLocation} className="w-full text-center px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-500 transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
                    {isFetchingLocation ? 'Adres Aranıyor...' : 'Haritadan Seç'}
                </button>
                <div className="flex justify-end gap-2"><button type="button" onClick={handleCancelEditInfo} className="px-3 py-1 bg-gray-500 text-white font-semibold rounded-lg hover:bg-gray-400">İptal</button><button onClick={handleSaveInfo} className="px-3 py-1 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-500 flex items-center gap-1"><SaveIcon/> Kaydet</button></div>
            </div>
        ) : (
             <div className="space-y-2 text-sm">
                <p><strong className="text-gray-400 w-20 inline-block">Telefon:</strong> {customer.phone || 'Belirtilmemiş'}</p>
                <p><strong className="text-gray-400 w-20 inline-block">Yetkili:</strong> {customer.contactPerson || 'Belirtilmemiş'}</p>
                <p className="flex items-start"><strong className="text-gray-400 w-20 inline-block flex-shrink-0">Adres:</strong> <span className="flex-1">{customer.address || 'Belirtilmemiş'}</span></p>
                {customer.location && (
                   <div className="flex items-center gap-4 mt-2">
                     <a href={`https://www.google.com/maps?q=${customer.location.lat},${customer.location.lng}`} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1 text-blue-400 hover:text-blue-300">
                        <MapPinIcon /> Haritada Göster
                    </a>
                    {navigator.share && (
                        <button onClick={handleShareLocation} className="inline-flex items-center gap-1 text-blue-400 hover:text-blue-300">
                            <ShareIcon /> Paylaş
                        </button>
                    )}
                   </div>
                )}
            </div>
        )}
      </div>

      <div className="flex justify-between items-center my-6">
        <h3 className="text-xl font-semibold">İşler</h3>
        <button onClick={() => setIsAddingJob(!isAddingJob)} className="inline-flex items-center gap-2 px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors"><PlusIcon /> {isAddingJob ? 'Kapat' : 'Yeni İş'}</button>
      </div>

      {isAddingJob && (
        <form onSubmit={handleAddJob} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-4">
          <input type="text" value={newJobName} onChange={(e) => setNewJobName(e.target.value)} placeholder="İş Adı / Modeli" className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
          <div className="flex gap-2">
            <input type="text" value={newJobFabricType} onChange={e => setNewJobFabricType(e.target.value)} placeholder="Kumaş Türü" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
            <input type="text" value={newJobFabricColor} onChange={e => setNewJobFabricColor(e.target.value)} placeholder="Kumaş Rengi" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
          </div>
          <div className="flex gap-2">
            <input type="date" value={newJobDeadline} onChange={e => setNewJobDeadline(e.target.value)} placeholder="Termin Tarihi" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
            <input type="text" value={newJobPersonInCharge} onChange={e => setNewJobPersonInCharge(e.target.value)} placeholder="Sorumlu Kişi" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
          </div>
           {/* Pattern Details List */}
            <div className="space-y-2">
                <h5 className="text-md font-semibold text-gray-300">Kalıp Detayları</h5>
                {newJobPatternDetails.length > 0 ? (
                    <ul className="divide-y divide-gray-700">
                        {newJobPatternDetails.map(detail => (
                            <li key={detail.id} className="flex justify-between items-center py-2">
                                <div className="text-sm">
                                    <p className="font-bold text-gray-200">{detail.patternName}</p>
                                    <p className="text-gray-400">{detail.fabricLength}m x {formatCurrency(detail.pricePerMeter)}/m = {formatCurrency(detail.fabricLength * detail.pricePerMeter)}</p>
                                </div>
                                <button type="button" onClick={() => handleRemovePatternDetail(detail.id)} className="text-red-500 hover:text-red-400"><TrashIcon className="h-4 w-4"/></button>
                            </li>
                        ))}
                    </ul>
                ) : <p className="text-xs text-gray-500 text-center p-2 bg-gray-700 rounded-md">Henüz kalıp eklenmedi.</p>}
            </div>

            {/* Add new pattern detail form */}
            {isAddingPattern ? (
                <div className="p-3 bg-gray-700 rounded-lg space-y-2">
                        <PatternDisplayButton patterns={patterns} value={currentPatternName} onClick={() => setIsPatternModalOpen(true)} />
                        <div className="flex gap-2">
                        <input type="number" value={currentFabricLength} onChange={(e) => setCurrentFabricLength(e.target.value)} placeholder="Metraj (m)" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                        <input type="number" step="0.01" value={currentPricePerMeter} onChange={(e) => setCurrentPricePerMeter(e.target.value)} placeholder="Metre Fiyatı" className="w-1/2 bg-gray-600 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                        </div>
                        <div className="flex justify-end gap-2">
                        <button type="button" onClick={() => setIsAddingPattern(false)} className="text-xs px-2 py-1 bg-gray-500 rounded-md">İptal</button>
                        <button type="button" onClick={handleAddPatternDetail} className="text-xs px-2 py-1 bg-teal-600 rounded-md">Ekle</button>
                        </div>
                </div>
            ) : (
                <button type="button" onClick={() => setIsAddingPattern(true)} className="w-full text-center text-sm py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                    Kalıp Ekle
                </button>
            )}


          <div className="flex gap-2"><input type="number" step="0.01" value={newJobDiscountAmount} onChange={(e) => setNewJobDiscountAmount(e.target.value)} placeholder="İskonto Tutarı" className="w-1/2 bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" /><input type="text" value={formatCurrency(parseFloat(newJobPrice))} placeholder="Nihai Fiyat" className="w-1/2 bg-gray-700 text-gray-400 rounded-md p-2" readOnly /></div>
          <textarea value={newJobNotes} onChange={(e) => setNewJobNotes(e.target.value)} placeholder="İş ile ilgili notlar ekleyin (isteğe bağlı)..." className="w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" rows={2} />
          {timeCalculation > 0 && <p className="text-xs text-center text-gray-400">Tahmini Süre: {Math.floor(timeCalculation / 60)} sa {timeCalculation % 60} dk</p>}
          {costCalculation > 0 && <p className="text-xs text-center text-yellow-400">Tahmini Gider: {formatCurrency(costCalculation)}</p>}
          <div className="flex justify-end"><button type="submit" className="px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">İş Ekle</button></div>
        </form>
      )}
      <PatternSelectorModal isOpen={isPatternModalOpen} patterns={patterns} onSelect={handlePatternSelect} onClose={() => setIsPatternModalOpen(false)} />

      <MapSelectorModal isOpen={isMapOpen} onClose={() => setIsMapOpen(false)} onLocationSelect={handleLocationSelectFromMap} />

      <ul className="space-y-4">
        {customer.jobs.length > 0 ? customer.jobs.map(job => (<JobItem key={job.id} job={job} customerId={customer.id} setCustomers={setCustomers} onDeleteRequest={handleDeleteRequest} onImageClick={setLightboxImage} onDeletePhotoRequest={(photoIndex) => handleDeletePhotoRequest(job.id, photoIndex)} isEditing={editingJobId === job.id} onEditRequest={setEditingJobId} onSave={handleSaveJob} onCancel={() => setEditingJobId(null)} patterns={patterns} settings={settings}
          onGenerateSlip={(job) => setLanguageModalTarget({ type: 'slip', job })} 
          onGenerateInvoice={(job) => setLanguageModalTarget({ type: 'invoice', job })} 
        />)) : <p className="text-gray-500 text-center py-4">Bu müşteri için henüz iş eklenmemiş.</p>}
      </ul>

      {lightboxImage && <ImageLightbox src={lightboxImage} onClose={() => setLightboxImage(null)} />}

      {slipRequest && <ManufacturingSlipModal job={slipRequest.job} customer={customer} patterns={patterns} lang={slipRequest.lang} settings={settings} onClose={() => setSlipRequest(null)} />}

      {invoiceRequest && <InvoiceModal job={invoiceRequest.job} customer={customer} lang={invoiceRequest.lang} onClose={() => setInvoiceRequest(null)} />}

      <LanguageSelectionModal
        isOpen={!!languageModalTarget}
        onClose={() => setLanguageModalTarget(null)}
        onSelect={handleLanguageSelect}
      />

      <ConfirmationModal isOpen={!!jobToDelete} onClose={() => setJobToDelete(null)} onConfirm={handleConfirmDelete} title="İşi Silmeyi Onayla"><p>Bu işi kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p></ConfirmationModal>

      <ConfirmationModal
          isOpen={!!photoToDelete}
          onClose={() => setPhotoToDelete(null)}
          onConfirm={handleConfirmPhotoDelete}
          title="Fotoğrafı Silmeyi Onayla"
      >
          <p>Bu fotoğrafı kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p>
      </ConfirmationModal>
    </div>
  );
};

export default CustomerDetailScreen;

