interface ManufacturingSlipHTMLProps {
  job: Job;
  customer: Customer;
  patterns: Pattern[];
  lang: 'tr' | 'ar' | 'en';
  settings: Settings;
}

const ManufacturingSlipHTML: React.FC<ManufacturingSlipHTMLProps> = ({ job, customer, patterns, lang, settings }) => {
    const T = translations[lang];

    const formatDate = (isoString?: string) => {
        if (!isoString) return '.............';
        const date = new Date(isoString);
        const options: Intl.DateTimeFormatOptions = { day: '2-digit', month: '2-digit', year: 'numeric' };
        return date.toLocaleDateString(lang === 'ar' ? 'ar-EG' : (lang === 'en' ? 'en-US' : 'tr-TR'), options);
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('tr-TR', { style: 'decimal', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount);
    };

    const totalFabricLength = job.patternDetails.reduce((sum, detail) => sum + detail.fabricLength, 0);
    const totalStonesGross = totalFabricLength * settings.rhinestonesPerMeter;
    const totalStoneWeightKg = (totalStonesGross * settings.rhinestoneWeightGramsPerGross) / 1000;
    const timeHours = (job.estimatedTimeMinutes || 0) / 60;
    const totalElectricityKwh = (settings.machinePowerWatt / 1000) * timeHours;

    return (
    <div className="printable-area p-6 bg-white text-black font-sans text-xs max-w-2xl mx-auto shadow-lg" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      {/* HEADER */}
      <header className="flex justify-between items-center border-b-2 border-gray-300 pb-3 mb-6">
        <div>
          <h1 className="text-xl font-bold text-gray-800">AB AYÇAM</h1>
          <p className="text-xs text-gray-500">{T.slipTitle}</p>
        </div>
        <div className="text-right">
          <p><strong>{T.date}</strong> {formatDate(job.createdAt)}</p>
