import React, { useState } from 'react';
import type { Settings } from '../types';
import Toast from './Toast';

// A string representation of the Settings object for the form state.
type StringifiedSettings = {
    [K in keyof Settings]: string;
};

// InputField is now a standalone component defined outside of SettingsScreen.
// This prevents it from being re-created on every render, thus preserving focus.
const InputField: React.FC<{
    name: keyof Settings;
    label: string;
    description: string;
    value: string;
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
}> = ({ name, label, description, value, onChange }) => (
    <div>
        <label htmlFor={name} className="block text-sm font-medium text-gray-300">{label}</label>
        <input
            type="text"
            inputMode="decimal" // Provides a better keyboard on mobile devices
            id={name}
            name={name}
            value={value}
            onChange={onChange}
            className="mt-1 w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
        />
        <p className="text-xs text-gray-500 mt-1">{description}</p>
    </div>
);


interface SettingsScreenProps {
    settings: Settings;
    setSettings: React.Dispatch<React.SetStateAction<Settings>>;
}

const SettingsScreen: React.FC<SettingsScreenProps> = ({ settings, setSettings }) => {
    // Form state is now stored as strings to allow partial input like "123."
    const [formState, setFormState] = useState<StringifiedSettings>(() =>
        Object.keys(settings).reduce((acc, key) => {
            acc[key as keyof Settings] = String(settings[key as keyof Settings]);
            return acc;
        }, {} as StringifiedSettings)
    );

    const [toastInfo, setToastInfo] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        // Allow only valid decimal number patterns
        if (/^\d*\.?\d*$/.test(value)) {
            setFormState(prev => ({
                ...prev,
                [name]: value,
            }));
        }
    };

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        // Convert string values back to numbers before saving
        const newSettings = Object.keys(formState).reduce((acc, key) => {
            const typedKey = key as keyof Settings;
            acc[typedKey] = parseFloat(formState[typedKey]) || 0;
            return acc;
        }, {} as Settings);

        setSettings(newSettings);
        setToastInfo({ message: "Ayarlar başarıyla kaydedildi.", type: 'success' });
    };

    return (
        <div>
            {toastInfo && <Toast message={toastInfo.message} type={toastInfo.type} show={!!toastInfo} onClose={() => setToastInfo(null)} />}
            <h2 className="text-2xl font-bold text-teal-400 mb-6">Maliyet Ayarları</h2>
            <form onSubmit={handleSubmit} className="space-y-6 bg-gray-800 p-6 rounded-lg shadow-lg">
                <InputField 
                    name="electricityCostKwh"
                    label="Elektrik Maliyeti (kWh başına)"
                    description="Elektrik faturanızdaki 1 kWh (kilowatt-saat) birim fiyatını girin."
                    value={formState.electricityCostKwh}
                    onChange={handleChange}
                />
                <InputField
                    name="machinePowerWatt"
                    label="Makine Gücü (Watt)"
                    description="Kullandığınız baskı makinesinin saatte harcadığı ortalama gücü Watt cinsinden girin."
                    value={formState.machinePowerWatt}
                    onChange={handleChange}
                />
                <InputField
                    name="rhinestoneCostPerGross"
                    label="Taş Maliyeti (Gross başına)"
                    description="1 Gross (144 adet) kristal taşın size olan maliyetini girin."
                    value={formState.rhinestoneCostPerGross}
                    onChange={handleChange}
                />
                <InputField
                    name="rhinestoneWeightGramsPerGross"
                    label="Taş Ağırlığı (Gross başına Gram)"
                    description="1 Gross taşın gram cinsinden ağırlığını girin. Bu, föyde ağırlık hesabı için kullanılır."
                    value={formState.rhinestoneWeightGramsPerGross}
                    onChange={handleChange}
                />

                <div className="flex justify-end">
                    <button
                        type="submit"
                        className="px-6 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors"
                    >
                        Ayarları Kaydet
                    </button>
                </div>
            </form>
        </div>
    );
};

