interface ManufacturingSlipHTMLProps {
  job: Job;
  customer: Customer;
  patterns: Pattern[];
  lang: 'tr' | 'ar' | 'en';
  settings: Settings;
}

const ManufacturingSlipHTML: React.FC<ManufacturingSlipHTMLProps> = ({ job, customer, patterns, lang, settings }) => {
    const T = translations[lang];

    const formatDate = (isoString?: string) => {
        if (!isoString) return '.............';
        const date = new Date(isoString);
        const options: Intl.DateTimeFormatOptions = { day: '2-digit', month: '2-digit', year: 'numeric' };
        return date.toLocaleDateString(lang === 'ar' ? 'ar-EG' : (lang === 'en' ? 'en-US' : 'tr-TR'), options);
    };

    const formatCurrency = (amount: number) => {
        return new Intl.NumberFormat('tr-TR', { style: 'decimal', minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(amount);
    };

    const totalStonesGross = job.patternDetails.reduce((sum, detail) => {
        const pattern = patterns.find(p => p.name === detail.patternName);
        if (pattern) {
            return sum + (detail.fabricLength * pattern.rhinestonesPerMeter);
        }
        return sum;
    }, 0);
    const totalStoneWeightKg = (totalStonesGross * settings.rhinestoneWeightGramsPerGross) / 1000;
    const timeHours = (job.estimatedTimeMinutes || 0) / 60;
    const totalElectricityKwh = (settings.machinePowerWatt / 1000) * timeHours;

    return (
    <div className="printable-area p-6 bg-white text-black font-sans text-[10px] max-w-2xl mx-auto shadow-lg" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
      {/* HEADER */}
      <header className="flex justify-between items-center border-b-2 border-gray-300 pb-3 mb-6">
        <div>
          <h1 className="text-lg font-bold text-gray-800">AB AYÇAM</h1>
          <p className="text-[9px] text-gray-500">{T.slipTitle}</p>
        </div>
        <div className="text-right">
          <p><strong>{T.date}</strong> {formatDate(job.createdAt)}</p>
        </div>
      </header>

      {/* CUSTOMER INFO */}
      <section className="mb-4 border border-gray-200 rounded p-3">
        <div className="flex">
          <p className="w-28 font-bold text-gray-600">{T.customerName}</p>
          <p className="flex-1">{customer.name || ''}</p>
        </div>
        <div className="flex mt-1">
          <p className="w-28 font-bold text-gray-600">{T.contact}</p>
          <p className="flex-1">{customer.phone || ''}</p>
        </div>
      </section>

      {/* ORDER DETAILS */}
      <section className="mb-4 border border-gray-200 rounded p-3">
        <h2 className="text-sm font-bold mb-3 border-b border-gray-200 pb-2 text-gray-800">{T.orderDetails}</h2>
        <div className="flex mt-1">
          <p className="w-28 font-bold text-gray-600">{T.model}</p>
          <p className="flex-1">{job.name || ''}</p>
        </div>
        <div className="mt-3">
          {job.patternDetails.map(detail => {
              const pattern = patterns.find(p => p.name === detail.patternName);
              return (
                  <div key={detail.id} className="flex items-center border-b border-gray-100 py-2 last:border-b-0">
                      <img className="w-10 h-10 mx-3 rounded object-cover bg-gray-100" src={pattern?.image || 'https://via.placeholder.com/150/EEEEEE/000000?text=?'} alt={detail.patternName} />
                      <div className="flex-grow">
                          <p className="font-bold text-xs">{detail.patternName}</p>
                      </div>
                      <div className="text-right">
                         <p className="font-semibold">{detail.fabricLength.toFixed(2)} {T.meter}</p>
                      </div>
                  </div>
              );
          })}
        </div>
      </section>

      {/* PRODUCTION DETAILS & COSTS */}
      <section className="mb-4 border border-gray-200 rounded p-3">
        <h2 className="text-sm font-bold mb-3 border-b border-gray-200 pb-2 text-gray-800">{T.productionDetails}</h2>
        <div className="space-y-2 text-xs">
            <div className="flex justify-between items-center">
                <span className="font-semibold text-gray-600">{T.totalStones}</span>
                <span className="font-bold">{totalStonesGross.toFixed(2)} Gross</span>
            </div>
            <div className="flex justify-between items-center">
                <span className="font-semibold text-gray-600">{T.totalWeight}</span>
                <span className="font-bold">{totalStoneWeightKg.toFixed(3)} kg</span>
            </div>
            <div className="flex justify-between items-center">
                <span className="font-semibold text-gray-600">{T.totalElectricity}</span>
                <span className="font-bold">{totalElectricityKwh.toFixed(2)} kWh</span>
            </div>
            <div className="flex justify-between items-center border-t border-gray-300 pt-2 mt-2">
                <span className="font-bold text-gray-800 text-sm">{T.totalCost}</span>
                <span className="font-bold text-red-600 text-sm">{job.estimatedCost ? formatCurrency(job.estimatedCost) : 'N/A'}</span>
            </div>
        </div>
      </section>


      {/* TIMELINE & NOTES */}
      <section className="grid grid-cols-2 gap-4">
        <div className="border border-gray-200 rounded p-3">
             <div className="flex items-center">
                <p className="w-28 font-bold text-gray-600">{T.departureDay}</p>
                <span className="flex-1 border-b border-dotted border-gray-400 h-4"></span>
            </div>
        </div>
        <div className="border border-gray-200 rounded p-3">
            <h3 className="font-bold text-gray-600 mb-1">{T.notes}</h3>
            <div className="p-1 bg-gray-50 rounded min-h-[40px]">
                <p className="text-[9px] whitespace-pre-wrap">{job.notes || ''}</p>
