                <p>{T.footerThanks}</p>
                <p className="font-semibold mt-1">AB AYÇAM</p>
                {settings.companyAddress && <p className="whitespace-pre-wrap">{settings.companyAddress}</p>}
            </footer>
        </div>
    );
};

export default InvoiceHTML;

