import React, { useState } from 'react';
import type { Customer, Job, Settings } from '../types';
import { XIcon, PrintIcon, ShareIcon } from './Icons';
import InvoiceHTML from './InvoiceHTML';
import html2canvas from 'html2canvas';

interface InvoiceModalProps {
  job: Job | null;
  customer: Customer;
  lang: 'tr' | 'ar' | 'en';
  settings: Settings;
  onClose: () => void;
}

const InvoiceModal: React.FC<InvoiceModalProps> = ({ job, customer, lang, settings, onClose }) => {
  const [isSharing, setIsSharing] = useState(false);

  if (!job) {
    return null;
  }

  const T = {
    tr: { title: 'Fatura', text: 'için fatura detayı.', sharing: 'Paylaşılıyor...', share: 'Paylaş', print: 'Yazdır' },
    ar: { title: 'فاتورة', text: 'تفاصيل الفاتورة لـ', sharing: 'جارى المشاركة...', share: 'مشاركة', print: 'طباعة' },
    en: { title: 'Invoice', text: 'invoice details.', sharing: 'Sharing...', share: 'Share', print: 'Print' },
  }[lang];

  const handlePrint = () => {
    window.print();
  };

  const handleShare = async () => {
    const invoiceElement = document.querySelector('.printable-area');
    if (!invoiceElement || isSharing) return;

    setIsSharing(true);
    try {
        const canvas = await html2canvas(invoiceElement as HTMLElement, {
            scale: 2, // Higher resolution image
            backgroundColor: '#ffffff',
            useCORS: true,
        });

        canvas.toBlob(async (blob) => {
            if (blob) {
                const file = new File([blob], `fatura-${job.id}.png`, { type: 'image/png' });
                const shareData = {
                    title: `${T.title} ${customer.name}`,
                    text: `${customer.name} ${T.text}`,
                    files: [file],
                };

                if (navigator.canShare && navigator.canShare(shareData)) {
                    await navigator.share(shareData);
                } else {
                    alert('Tarayıcınız bu dosyayı paylaşmayı desteklemiyor.');
                }
            } else {
                throw new Error("Canvas to Blob conversion failed.");
            }
            setIsSharing(false);
        }, 'image/png');

    } catch (error) {
        console.error('Error sharing invoice:', error);
        alert('Fatura paylaşılırken bir hata oluştu.');
        setIsSharing(false);
    }
  };

  return (
    <div 
      className="fixed inset-0 bg-black bg-opacity-70 flex justify-center items-center z-50 p-4 no-print"
      onClick={onClose}
    >
      <div 
        className="bg-gray-800 rounded-lg shadow-xl w-full max-w-3xl mx-auto flex flex-col h-[90vh]"
        onClick={e => e.stopPropagation()}
      >
        <header className="flex justify-between items-center p-4 border-b border-gray-700 flex-shrink-0">
          <h2 className="text-xl font-bold text-teal-400">{T.title}</h2>
          <button onClick={onClose} className="text-gray-400 hover:text-white">
            <XIcon />
          </button>
        </header>

        <div className="p-4 bg-gray-600 overflow-y-auto flex-grow">
            <InvoiceHTML job={job} customer={customer} lang={lang} settings={settings} />
        </div>

        <footer className="flex justify-end items-center p-4 border-t border-gray-700 flex-shrink-0 gap-4">
             <button
                onClick={handleShare}
                disabled={isSharing || !navigator.share}
                className="inline-flex items-center gap-2 rounded-md border border-transparent bg-blue-600 px-6 py-3 text-base font-medium text-white shadow-sm hover:bg-blue-700 transition-colors focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 focus:ring-offset-gray-800 disabled:opacity-50"
            >
                <ShareIcon />
                {isSharing ? T.sharing : T.share}
            </button>
            <button
                onClick={handlePrint}
                className="inline-flex items-center gap-2 rounded-md border border-transparent bg-teal-600 px-6 py-3 text-base font-medium text-white shadow-sm hover:bg-teal-700 transition-colors focus:outline-none focus:ring-2 focus:ring-teal-500 focus:ring-offset-2 focus:ring-offset-gray-800"
            >
                <PrintIcon />
                {T.print}
            </button>
        </footer>

      </div>
    </div>
  );
};

