}

const InvoiceHTML: React.FC<InvoiceHTMLProps> = ({ job, customer, lang, settings }) => {
    const T = translations[lang];

    const formatDate = (isoString?: string) => {
        if (!isoString) return '.............';
        const date = new Date(isoString);
        const options: Intl.DateTimeFormatOptions = { day: '2-digit', month: '2-digit', year: 'numeric' };
        return date.toLocaleDateString(lang === 'ar' ? 'ar-EG' : (lang === 'en' ? 'en-US' : 'tr-TR'), options);
    };

    const formatCurrency = (amount: number) => {
        // Para birimi simgesini göstermeden sayıyı formatla
        return new Intl.NumberFormat(lang === 'ar' ? 'ar-EG' : (lang === 'en' ? 'en-US' : 'tr-TR'), {
            style: 'decimal',
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
        }).format(amount);
    };


    const subTotal = job.patternDetails.reduce((sum, detail) => sum + (detail.fabricLength * detail.pricePerMeter), 0);
    const discount = job.discountAmount || 0;
    const grandTotal = job.price;
    const balance = job.price - job.paidAmount;

    return (
        <div className="printable-area p-6 bg-white text-black font-sans text-[9px] max-w-2xl mx-auto shadow-lg" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
            {/* HEADER */}
