interface SettingsScreenProps {
    settings: Settings;
    setSettings: React.Dispatch<React.SetStateAction<Settings>>;
}

const SettingsScreen: React.FC<SettingsScreenProps> = ({ settings, setSettings }) => {
    const [formState, setFormState] = useState<FormState>({
        electricityCostKwh: String(settings.electricityCostKwh),
        machinePowerWatt: String(settings.machinePowerWatt),
        rhinestoneCostPerGross: String(settings.rhinestoneCostPerGross),
        rhinestoneWeightGramsPerGross: String(settings.rhinestoneWeightGramsPerGross),
        companyName: settings.companyName || '',
        companyAddress: settings.companyAddress || '',
        companyPhoneNumbers: settings.companyPhoneNumbers || [''],
        companyEmail: settings.companyEmail || '',
        companyTaxNumber: settings.companyTaxNumber || '',
        companyLogo: settings.companyLogo || '',
    });

    const [toastInfo, setToastInfo] = useState<{ message: string, type: 'success' | 'error' } | null>(null);

    const handleNumericChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (/^\d*\.?\d*$/.test(value)) {
            setFormState(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (index: number, value: string) => {
        const newPhones = [...formState.companyPhoneNumbers];
        newPhones[index] = value;
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const addPhone = () => {
        setFormState(prev => ({ ...prev, companyPhoneNumbers: [...prev.companyPhoneNumbers, ''] }));
    };

    const removePhone = (index: number) => {
        // Keep at least one input field
        if (formState.companyPhoneNumbers.length <= 1) return;
        const newPhones = formState.companyPhoneNumbers.filter((_, i) => i !== index);
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0]);
                setFormState(prev => ({...prev, companyLogo: base64}));
            } catch (error) {
                console.error("Error compressing and encoding image:", error);
                setToastInfo({ message: "Logo yüklenirken hata oluştu.", type: 'error' });
            }
        }
    };


    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const newSettings: Settings = {
            electricityCostKwh: parseFloat(formState.electricityCostKwh) || 0,
            machinePowerWatt: parseFloat(formState.machinePowerWatt) || 0,
            rhinestoneCostPerGross: parseFloat(formState.rhinestoneCostPerGross) || 0,
            rhinestoneWeightGramsPerGross: parseFloat(formState.rhinestoneWeightGramsPerGross) || 0,
            companyName: formState.companyName.trim(),
            companyAddress: formState.companyAddress.trim(),
            companyPhoneNumbers: formState.companyPhoneNumbers.map(p => p.trim()).filter(p => p),
            companyEmail: formState.companyEmail.trim(),
            companyTaxNumber: formState.companyTaxNumber.trim(),
            companyLogo: formState.companyLogo || undefined,
        };

        setSettings(newSettings);
        setToastInfo({ message: "Ayarlar başarıyla kaydedildi.", type: 'success' });
    };

    return (
        <div>
            {toastInfo && <Toast message={toastInfo.message} type={toastInfo.type} show={!!toastInfo} onClose={() => setToastInfo(null)} />}
            <h2 className="text-2xl font-bold text-teal-400 mb-6">Genel Ayarlar</h2>
            <form onSubmit={handleSubmit} className="space-y-6 bg-gray-800 p-6 rounded-lg shadow-lg">

                {/* Cost Settings */}
                <h3 className="text-lg font-semibold text-gray-300 border-b border-gray-700 pb-2">Maliyet Ayarları</h3>
                <InputField name="electricityCostKwh" label="Elektrik Maliyeti (kWh başına)" description="1 kWh birim fiyatını girin." value={formState.electricityCostKwh} onChange={handleNumericChange} type="text" inputMode="decimal" />
                <InputField name="machinePowerWatt" label="Makine Gücü (Watt)" description="Makinenin saatte harcadığı ortalama gücü girin." value={formState.machinePowerWatt} onChange={handleNumericChange} type="text" inputMode="decimal" />
                <InputField name="rhinestoneCostPerGross" label="Taş Maliyeti (Gross başına)" description="1 Gross (144 adet) taşın maliyetini girin." value={formState.rhinestoneCostPerGross} onChange={handleNumericChange} type="text" inputMode="decimal" />
                <InputField name="rhinestoneWeightGramsPerGross" label="Taş Ağırlığı (Gross başına Gram)" description="1 Gross taşın gram cinsinden ağırlığını girin." value={formState.rhinestoneWeightGramsPerGross} onChange={handleNumericChange} type="text" inputMode="decimal" />

                {/* Invoice Settings */}
                <h3 className="text-lg font-semibold text-gray-300 border-b border-gray-700 pb-2 pt-4">Fatura Ayarları</h3>

                <div>
                    <label className="block text-sm font-medium text-gray-300">Firma Logosu</label>
                    <div className="mt-2 flex items-center gap-4">
                        {formState.companyLogo ? (
                            <img src={formState.companyLogo} alt="Firma Logosu" className="h-16 w-16 object-contain bg-white p-1 rounded-md" />
                        ) : (
                            <div className="h-16 w-16 bg-gray-700 rounded-md flex items-center justify-center text-gray-500 text-xs text-center">Logo Yok</div>
                        )}
                        <div className="flex flex-col gap-2">
                             <label className="cursor-pointer px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                                Logo Yükle
                                <input type="file" accept="image/png, image/jpeg" className="hidden" onChange={handleLogoUpload} />
                            </label>
                            {formState.companyLogo && (
                                <button type="button" onClick={() => setFormState(p => ({...p, companyLogo: ''}))} className="px-3 py-1 bg-red-600 text-white text-sm font-semibold rounded-lg hover:bg-red-500 transition-colors">
                                    Logoyu Kaldır
                                </button>
                            )}
                        </div>
                    </div>
                </div>

                <InputField name="companyName" label="Firma Adı" value={formState.companyName} onChange={handleTextChange} />
                <TextareaField name="companyAddress" label="Firma Adresi" description="Faturada görünecek açık adresi girin." value={formState.companyAddress} onChange={handleTextChange} />

                <div>
                    <label className="block text-sm font-medium text-gray-300 mb-2">Telefon Numaraları</label>
                    {formState.companyPhoneNumbers.map((phone, index) => (
                        <div key={index} className="flex items-center gap-2 mb-2">
                            <input
                                type="tel"
                                value={phone}
                                onChange={(e) => handlePhoneChange(index, e.target.value)}
                                className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
                                placeholder="örn: +90 555 123 4567"
                            />
                            <button type="button" onClick={() => removePhone(index)} disabled={formState.companyPhoneNumbers.length <= 1} className="p-2 bg-red-600 text-white rounded-md hover:bg-red-500 disabled:opacity-50 disabled:cursor-not-allowed">
                                <TrashIcon className="h-4 w-4" />
                            </button>
                        </div>
                    ))}
                    <button type="button" onClick={addPhone} className="flex items-center gap-2 text-sm px-3 py-1 bg-blue-600 text-white rounded-md hover:bg-blue-500">
                        <PlusIcon /> Yeni Telefon Ekle
                    </button>
                </div>

                <InputField name="companyEmail" label="E-posta Adresi" value={formState.companyEmail} onChange={handleTextChange} type="email" inputMode="email" />
                <InputField name="companyTaxNumber" label="Vergi Numarası" value={formState.companyTaxNumber} onChange={handleTextChange} />

                <div className="flex justify-end pt-4">
                    <button type="submit" className="px-6 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">
                        Ayarları Kaydet
                    </button>
                </div>
            </form>
        </div>
    );
};

export default SettingsScreen;

