interface InvoiceHTMLProps {
  job: Job;
  customer: Customer;
  lang: 'tr' | 'ar' | 'en';
  settings: Settings;
}

const InvoiceHTML: React.FC<InvoiceHTMLProps> = ({ job, customer, lang, settings }) => {
    const T = translations[lang];

    const formatDate = (isoString?: string) => {
        if (!isoString) return '.............';
        const date = new Date(isoString);
        const options: Intl.DateTimeFormatOptions = { day: '2-digit', month: '2-digit', year: 'numeric' };
        return date.toLocaleDateString(lang === 'ar' ? 'ar-EG' : (lang === 'en' ? 'en-US' : 'tr-TR'), options);
    };

    const formatCurrency = (amount: number) => {
        // Para birimi simgesini göstermeden sayıyı formatla
        return new Intl.NumberFormat(lang === 'ar' ? 'ar-EG' : (lang === 'en' ? 'en-US' : 'tr-TR'), {
            style: 'decimal',
            minimumFractionDigits: 2,
            maximumFractionDigits: 2,
        }).format(amount);
    };


    const subTotal = job.patternDetails.reduce((sum, detail) => sum + (detail.fabricLength * detail.pricePerMeter), 0);
    const discount = job.discountAmount || 0;
    const grandTotal = job.price;
    const balance = job.price - job.paidAmount;

    return (
        <div className="printable-area p-6 bg-white text-black font-sans text-[9px] max-w-2xl mx-auto shadow-lg" dir={lang === 'ar' ? 'rtl' : 'ltr'}>
            {/* HEADER */}
            <header className="flex justify-between items-start border-b-2 border-black pb-3 mb-6">
                <div className="flex items-center gap-4">
                    {settings.companyLogo && (
                        <img src={settings.companyLogo} alt="Firma Logosu" className="h-14 w-auto object-contain" />
                    )}
                    <div>
                        <h1 className="text-lg font-bold text-black">{settings.companyName || 'AB AYÇAM'}</h1>
                        <p className="text-black text-[8px]">{T.companyInfo}</p>
                    </div>
                </div>
                <div className="text-end">
                    <h2 className="text-base font-semibold text-black">{T.invoiceTitle}</h2>
                    <p className="text-black text-[8px] mt-1"><strong>{T.invoiceNo}</strong> #{job.id.slice(-6).toUpperCase()}</p>
                    <p className="text-black text-[8px]"><strong>{T.date}</strong> {formatDate(job.createdAt)}</p>
                </div>
            </header>

            {/* CUSTOMER INFO */}
            <section className="mb-6">
                <h3 className="font-semibold text-black mb-2 text-[8px] uppercase">{T.customerInfo}</h3>
                <div className="p-3 bg-gray-100 border border-gray-300 rounded text-start">
                    <p className="font-bold text-xs text-black">{customer.name}</p>
                    {customer.phone && <p className="text-black text-[10px]">{customer.phone}</p>}
                    {customer.address && <p className="text-black mt-1 text-[10px]">{customer.address}</p>}
                </div>
            </section>

            {/* LINE ITEMS TABLE */}
            <section className="mb-6">
                <table className="w-full text-start">
                    <thead className="bg-black text-white text-[8px]">
                        <tr>
                            <th className="p-2 w-1/2 font-semibold text-start">{T.description}</th>
                            <th className="p-2 text-center font-semibold">{T.quantity}</th>
                            <th className="p-2 text-end font-semibold">{T.unitPrice}</th>
                            <th className="p-2 text-end font-semibold">{T.total}</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200">
                        {job.patternDetails.map(detail => (
                            <tr key={detail.id}>
                                <td className="p-2 align-top">
                                    <p className="font-semibold text-[10px] text-black">{detail.patternName}</p>
                                    <p className="text-black text-[9px]">{job.name}</p>
                                </td>
                                <td className="p-2 text-center align-top text-[10px] text-black">{detail.fabricLength.toFixed(2)} {T.meter}</td>
                                <td className="p-2 text-end align-top text-[10px] text-black">{formatCurrency(detail.pricePerMeter)}</td>
                                <td className="p-2 text-end font-semibold align-top text-[10px] text-black">{formatCurrency(detail.fabricLength * detail.pricePerMeter)}</td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </section>

            {/* TOTALS SECTION */}
            <section className="flex justify-end">
                <div className="w-1/2 space-y-1 text-[10px]">
                    <div className="flex justify-between">
                        <span className="text-black">{T.subTotal}</span>
                        <span className="font-semibold text-black">{formatCurrency(subTotal)}</span>
                    </div>
                    {discount > 0 && (
                         <div className="flex justify-between">
                            <span className="text-black">{T.discount}</span>
                            <span className="font-semibold text-red-600">- {formatCurrency(discount)}</span>
                        </div>
                    )}
                    <div className="flex justify-between border-t-2 border-b-2 border-black py-1 my-1">
                        <span className="font-bold text-xs text-black">{T.grandTotal}</span>
                        <span className="font-bold text-xs text-black">{formatCurrency(grandTotal)}</span>
                    </div>
                     <div className="flex justify-between pt-1">
                        <span className="text-black">{T.paidAmount}</span>
                        <span className="font-semibold text-green-600">{formatCurrency(job.paidAmount)}</span>
                    </div>
                     <div className="flex justify-between">
                        <span className="font-bold text-black">{T.balance}</span>
                        <span className="font-bold text-red-600">{formatCurrency(balance)}</span>
                    </div>
                </div>
            </section>

            {/* FOOTER */}
            <footer className="text-black mt-10 pt-2 border-t-2 border-black">
                <div className="text-center text-gray-500 space-y-1">
                    {settings.companyAddress && (
                        <p className="text-[6px] leading-tight">
                            {settings.companyAddress.replace(/\n/g, ', ')}
                        </p>
                    )}
                    <p className="text-[6px] leading-tight">
                        {[
                            settings.companyPhoneNumbers?.length > 0 && settings.companyPhoneNumbers.join(' | '),
                            settings.companyEmail,
                            settings.companyTaxNumber && `V.N: ${settings.companyTaxNumber}`
                        ].filter(Boolean).join(' • ')}
                    </p>
                </div>
            </footer>
        </div>
    );
};

