      <PatternSelectorModal isOpen={isPatternModalOpen} patterns={patterns} onSelect={handlePatternSelect} onClose={() => setIsPatternModalOpen(false)} />

      <MapSelectorModal isOpen={isMapOpen} onClose={() => setIsMapOpen(false)} onLocationSelect={handleLocationSelectFromMap} />

      <ul className="space-y-4">
        {customer.jobs.length > 0 ? customer.jobs.map(job => (<JobItem key={job.id} job={job} customerId={customer.id} setCustomers={setCustomers} onDeleteRequest={handleDeleteRequest} onImageClick={setLightboxImage} onDeletePhotoRequest={(photoIndex) => handleDeletePhotoRequest(job.id, photoIndex)} isEditing={editingJobId === job.id} onEditRequest={setEditingJobId} onSave={handleSaveJob} onCancel={() => setEditingJobId(null)} patterns={patterns} settings={settings}
          onGenerateSlip={(job) => setLanguageModalTarget({ type: 'slip', job })} 
          onGenerateInvoice={(job) => setLanguageModalTarget({ type: 'invoice', job })} 
        />)) : <p className="text-gray-500 text-center py-4">Bu müşteri için henüz iş eklenmemiş.</p>}
      </ul>

      {lightboxImage && <ImageLightbox src={lightboxImage} onClose={() => setLightboxImage(null)} />}

      {slipRequest && <ManufacturingSlipModal job={slipRequest.job} customer={customer} patterns={patterns} lang={slipRequest.lang} settings={settings} onClose={() => setSlipRequest(null)} />}

      {invoiceRequest && <InvoiceModal job={invoiceRequest.job} customer={customer} lang={invoiceRequest.lang} settings={settings} onClose={() => setInvoiceRequest(null)} />}

      <LanguageSelectionModal
        isOpen={!!languageModalTarget}
        onClose={() => setLanguageModalTarget(null)}
        onSelect={handleLanguageSelect}
      />

      <ConfirmationModal isOpen={!!jobToDelete} onClose={() => setJobToDelete(null)} onConfirm={handleConfirmDelete} title="İşi Silmeyi Onayla"><p>Bu işi kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p></ConfirmationModal>

      <ConfirmationModal
          isOpen={!!photoToDelete}
          onClose={() => setPhotoToDelete(null)}
          onConfirm={handleConfirmPhotoDelete}
          title="Fotoğrafı Silmeyi Onayla"
      >
          <p>Bu fotoğrafı kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p>
      </ConfirmationModal>
    </div>
  );
};

