// A string representation of the Settings object for the form state.
type FormState = {
    electricityCostKwh: string;
    machinePowerWatt: string;
    rhinestoneCostPerGross: string;
    rhinestoneWeightGramsPerGross: string;
    companyName: string;
    companyAddress: string;
    companyPhoneNumbers: string[];
    companyEmail: string;
    companyTaxNumber: string;
    companyLogo: string;
    minutesPer100Meters: string;
    requirePasswordForDelete: boolean;
    confirmationPassword: string;
};

type ActiveTab = 'company' | 'costs' | 'calculations' | 'security';


const compressAndEncodeImage = (file: File, maxDimension: number = 200, quality: number = 0.8): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            if (!event.target?.result) {
                return reject(new Error("FileReader failed to read file."));
            }
            const img = new Image();
            img.src = event.target.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let { width, height } = img;

                if (width > height) {
                    if (width > maxDimension) {
                        height = Math.round((height * maxDimension) / width);
                        width = maxDimension;
                    }
                } else {
                    if (height > maxDimension) {
                        width = Math.round((width * maxDimension) / height);
                        height = maxDimension;
                    }
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    return reject(new Error('Could not get 2D context from canvas.'));
                }
                ctx.drawImage(img, 0, 0, width, height);

                const dataUrl = canvas.toDataURL('image/png', quality); // Use PNG for transparency
                resolve(dataUrl);
            };
            img.onerror = (err) => reject(err);
        };
        reader.onerror = (err) => reject(err);
    });
};


const InputField: React.FC<{
    name: keyof FormState;
    label: string;
    description?: string;
    value: string;
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
    type?: string;
    inputMode?: 'decimal' | 'text' | 'email' | 'tel' | 'password';
}> = ({ name, label, description, value, onChange, type = 'text', inputMode = 'text' }) => (
    <div>
        <label htmlFor={name.toString()} className="block text-sm font-medium text-gray-300">{label}</label>
        <input
            type={type}
            inputMode={inputMode}
            id={name.toString()}
            name={name.toString()}
            value={value}
            onChange={onChange}
            className="mt-1 w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
        />
        {description && <p className="text-xs text-gray-500 mt-1">{description}</p>}
    </div>
);

const TextareaField: React.FC<{
    name: 'companyAddress';
    label: string;
    description: string;
    value: string;
    onChange: (e: React.ChangeEvent<HTMLTextAreaElement>) => void;
}> = ({ name, label, description, value, onChange }) => (
    <div>
        <label htmlFor={name} className="block text-sm font-medium text-gray-300">{label}</label>
        <textarea
            id={name}
            name={name}
            value={value}
            onChange={onChange}
            rows={3}
            className="mt-1 w-full bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none"
        />
        <p className="text-xs text-gray-500 mt-1">{description}</p>
    </div>
);


const IconNavButton: React.FC<{
    label: string;
    icon: React.ReactElement;
    isActive: boolean;
    onClick: () => void;
}> = ({ label, icon, isActive, onClick }) => {
    const activeClasses = 'bg-teal-600 text-white';
    const inactiveClasses = 'bg-gray-700 text-gray-400 hover:bg-gray-600 hover:text-white';
    return (
        <button
            type="button"
            onClick={onClick}
            title={label}
            aria-label={label}
            className={`flex items-center justify-center h-12 w-12 rounded-lg transition-colors duration-200 ${isActive ? activeClasses : inactiveClasses}`}
        >
            {icon}
        </button>
    );
};


interface SettingsScreenProps {
    settings: Settings;
    setSettings: React.Dispatch<React.SetStateAction<Settings>>;
}

const SettingsScreen: React.FC<SettingsScreenProps> = ({ settings, setSettings }) => {
    const [formState, setFormState] = useState<FormState>({
        electricityCostKwh: String(settings.electricityCostKwh),
        machinePowerWatt: String(settings.machinePowerWatt),
        rhinestoneCostPerGross: String(settings.rhinestoneCostPerGross),
        rhinestoneWeightGramsPerGross: String(settings.rhinestoneWeightGramsPerGross),
        companyName: settings.companyName || '',
        companyAddress: settings.companyAddress || '',
        companyPhoneNumbers: settings.companyPhoneNumbers || [''],
        companyEmail: settings.companyEmail || '',
        companyTaxNumber: settings.companyTaxNumber || '',
        companyLogo: settings.companyLogo || '',
        minutesPer100Meters: String(settings.minutesPer100Meters || 20),
        requirePasswordForDelete: settings.requirePasswordForDelete,
        confirmationPassword: settings.confirmationPassword || '',
    });

    const [toastInfo, setToastInfo] = useState<{ message: string, type: 'success' | 'error' } | null>(null);
    const [activeTab, setActiveTab] = useState<ActiveTab>('company');

    const handleNumericChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (/^\d*\.?\d*$/.test(value)) {
            setFormState(prev => ({ ...prev, [name]: value }));
        }
    };

    const handleIntegerChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value } = e.target;
        if (/^\d*$/.test(value)) {
            setFormState(prev => ({ ...prev, [name]: value }));
        }
    };


    const handleTextChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
        const { name, value } = e.target;
        setFormState(prev => ({ ...prev, [name]: value }));
    };

    const handlePhoneChange = (index: number, value: string) => {
        const newPhones = [...formState.companyPhoneNumbers];
        newPhones[index] = value;
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const addPhone = () => {
        setFormState(prev => ({ ...prev, companyPhoneNumbers: [...prev.companyPhoneNumbers, ''] }));
    };

    const removePhone = (index: number) => {
        if (formState.companyPhoneNumbers.length <= 1) return;
        const newPhones = formState.companyPhoneNumbers.filter((_, i) => i !== index);
        setFormState(prev => ({ ...prev, companyPhoneNumbers: newPhones }));
    };

    const handleLogoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0]);
                setFormState(prev => ({...prev, companyLogo: base64}));
            } catch (error) {
                console.error("Error compressing and encoding image:", error);
                setToastInfo({ message: "Logo yüklenirken hata oluştu.", type: 'error' });
            }
        }
    };


    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        const newSettings: Settings = {
            electricityCostKwh: parseFloat(formState.electricityCostKwh) || 0,
            machinePowerWatt: parseFloat(formState.machinePowerWatt) || 0,
            rhinestoneCostPerGross: parseFloat(formState.rhinestoneCostPerGross) || 0,
            rhinestoneWeightGramsPerGross: parseFloat(formState.rhinestoneWeightGramsPerGross) || 0,
            companyName: formState.companyName.trim(),
            companyAddress: formState.companyAddress.trim(),
            companyPhoneNumbers: formState.companyPhoneNumbers.map(p => p.trim()).filter(p => p),
            companyEmail: formState.companyEmail.trim(),
            companyTaxNumber: formState.companyTaxNumber.trim(),
            companyLogo: formState.companyLogo || undefined,
            minutesPer100Meters: parseInt(formState.minutesPer100Meters, 10) || 20,
            requirePasswordForDelete: formState.requirePasswordForDelete,
            confirmationPassword: formState.confirmationPassword.trim(),
        };

        setSettings(newSettings);
        setToastInfo({ message: "Ayarlar başarıyla kaydedildi.", type: 'success' });
    };

    const renderContent = () => {
        switch (activeTab) {
            case 'company':
                return (
                    <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Firma Bilgileri</h3>
                        <div>
                            <label className="block text-sm font-medium text-gray-300">Firma Logosu</label>
                            <div className="mt-2 flex items-center gap-4">
                                {formState.companyLogo ? (
                                    <img src={formState.companyLogo} alt="Firma Logosu" className="h-16 w-16 object-contain bg-white p-1 rounded-md" />
                                ) : (
                                    <div className="h-16 w-16 bg-gray-700 rounded-md flex items-center justify-center text-gray-500 text-xs text-center">Logo Yok</div>
                                )}
                                <div className="flex flex-col gap-2">
                                    <label className="cursor-pointer px-3 py-1 bg-blue-600 text-white text-sm font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                                        Logo Yükle
                                        <input type="file" accept="image/png, image/jpeg" className="hidden" onChange={handleLogoUpload} />
                                    </label>
                                    {formState.companyLogo && (
                                        <button type="button" onClick={() => setFormState(p => ({...p, companyLogo: ''}))} className="px-3 py-1 bg-red-600 text-white text-sm font-semibold rounded-lg hover:bg-red-500 transition-colors">
                                            Logoyu Kaldır
                                        </button>
                                    )}
                                </div>
                            </div>
                        </div>
                        <InputField name="companyName" label="Firma Adı" value={formState.companyName} onChange={handleTextChange} />
                        <TextareaField name="companyAddress" label="Firma Adresi" description="Faturada görünecek açık adresi girin." value={formState.companyAddress} onChange={handleTextChange} />
                        <div>
                            <label className="block text-sm font-medium text-gray-300 mb-2">Telefon Numaraları</label>
                            {formState.companyPhoneNumbers.map((phone, index) => (
                                <div key={index} className="flex items-center gap-2 mb-2">
                                    <input type="tel" value={phone} onChange={(e) => handlePhoneChange(index, e.target.value)} className="flex-grow bg-gray-700 text-gray-200 rounded-md p-2 focus:ring-2 focus:ring-teal-500 focus:outline-none" placeholder="örn: +90 555 123 4567" />
                                    <button type="button" onClick={() => removePhone(index)} disabled={formState.companyPhoneNumbers.length <= 1} className="p-2 bg-red-600 text-white rounded-md hover:bg-red-500 disabled:opacity-50 disabled:cursor-not-allowed">
                                        <TrashIcon className="h-4 w-4" />
                                    </button>
                                </div>
                            ))}
                            <button type="button" onClick={addPhone} className="flex items-center gap-2 text-sm px-3 py-1 bg-blue-600 text-white rounded-md hover:bg-blue-500">
                                <PlusIcon /> Yeni Telefon Ekle
                            </button>
                        </div>
                        <InputField name="companyEmail" label="E-posta Adresi" value={formState.companyEmail} onChange={handleTextChange} type="email" inputMode="email" />
                        <InputField name="companyTaxNumber" label="Vergi Numarası" value={formState.companyTaxNumber} onChange={handleTextChange} />
                    </div>
                );
            case 'costs':
                return (
                     <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Maliyet Ayarları</h3>
                        <InputField name="electricityCostKwh" label="Elektrik Maliyeti (kWh başına)" description="1 kWh birim fiyatını girin." value={formState.electricityCostKwh} onChange={handleNumericChange} type="text" inputMode="decimal" />
                        <InputField name="machinePowerWatt" label="Makine Gücü (Watt)" description="Makinenin saatte harcadığı ortalama gücü girin." value={formState.machinePowerWatt} onChange={handleIntegerChange} type="text" inputMode="decimal" />
                        <InputField name="rhinestoneCostPerGross" label="Taş Maliyeti (Gross başına)" description="1 Gross (144 adet) taşın maliyetini girin." value={formState.rhinestoneCostPerGross} onChange={handleNumericChange} type="text" inputMode="decimal" />
                        <InputField name="rhinestoneWeightGramsPerGross" label="Taş Ağırlığı (Gross başına Gram)" description="1 Gross taşın gram cinsinden ağırlığını girin." value={formState.rhinestoneWeightGramsPerGross} onChange={handleNumericChange} type="text" inputMode="decimal" />
                    </div>
                );
            case 'calculations':
                return (
                    <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Hesaplama Ayarları</h3>
                        <InputField name="minutesPer100Meters" label="100 Metre Başına Süre (Dakika)" description="İşlerin tahmini süresini hesaplamak için kullanılır." value={formState.minutesPer100Meters} onChange={handleIntegerChange} type="text" inputMode="decimal" />
                    </div>
                );
            case 'security':
                return (
                    <div className="space-y-4">
                        <h3 className="text-xl font-bold text-gray-200 border-b border-gray-700 pb-2">Güvenlik Ayarları</h3>
                        <div className="flex items-center justify-between p-3 bg-gray-700/50 rounded-md">
                            <label htmlFor="requirePasswordForDelete" className="text-sm font-medium text-gray-300 flex-1">Silme İşlemleri İçin Şifre İste</label>
                            <div className="relative inline-flex items-center cursor-pointer">
                                <input type="checkbox" id="requirePasswordForDelete" className="sr-only peer" checked={formState.requirePasswordForDelete} onChange={(e) => setFormState(prev => ({ ...prev, requirePasswordForDelete: e.target.checked }))} />
                                <div className="w-11 h-6 bg-gray-600 rounded-full peer peer-focus:ring-2 peer-focus:ring-teal-800 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-0.5 after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-teal-600"></div>
                            </div>
                        </div>
                        {formState.requirePasswordForDelete && (
                            <InputField name="confirmationPassword" label="Onay Şifresi" description="Silme işlemleri için kullanılacak şifre." value={formState.confirmationPassword} onChange={handleTextChange} type="text" />
                        )}
                    </div>
                );
            default: return null;
        }
    }


    return (
        <div>
            {toastInfo && <Toast message={toastInfo.message} type={toastInfo.type} show={!!toastInfo} onClose={() => setToastInfo(null)} />}
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-teal-400">Genel Ayarlar</h2>
                <button form="settings-form" type="submit" className="px-5 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">
                    Kaydet
                </button>
            </div>
             <form id="settings-form" onSubmit={handleSubmit} className="flex flex-col md:flex-row gap-6">
                <aside className="flex flex-row md:flex-col gap-2 md:w-16">
                    <IconNavButton label="Firma Bilgileri" icon={<BuildingIcon />} isActive={activeTab === 'company'} onClick={() => setActiveTab('company')} />
                    <IconNavButton label="Maliyet Ayarları" icon={<CalculatorIcon />} isActive={activeTab === 'costs'} onClick={() => setActiveTab('costs')} />
                    <IconNavButton label="Hesaplama Ayarları" icon={<ClockIcon />} isActive={activeTab === 'calculations'} onClick={() => setActiveTab('calculations')} />
                    <IconNavButton label="Güvenlik Ayarları" icon={<ShieldIcon />} isActive={activeTab === 'security'} onClick={() => setActiveTab('security')} />
                </aside>
                <div className="flex-grow bg-gray-800 rounded-lg shadow-lg p-6">
                    {renderContent()}
                </div>
            </form>
        </div>
    );
};

export default SettingsScreen;

