const compressAndEncodeImage = (file: File, maxDimension: number = 800, quality: number = 0.7): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            if (!event.target?.result) {
                return reject(new Error("FileReader failed to read file."));
            }
            const img = new Image();
            img.src = event.target.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let { width, height } = img;

                if (width > height) {
                    if (width > maxDimension) {
                        height = Math.round((height * maxDimension) / width);
                        width = maxDimension;
                    }
                } else {
                    if (height > maxDimension) {
                        width = Math.round((width * maxDimension) / height);
                        height = maxDimension;
                    }
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    return reject(new Error('Could not get 2D context from canvas.'));
                }
                ctx.drawImage(img, 0, 0, width, height);

                const dataUrl = canvas.toDataURL('image/jpeg', quality);
                resolve(dataUrl);
            };
            img.onerror = (err) => reject(err);
        };
        reader.onerror = (err) => reject(err);
    });
};

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', {
        style: 'decimal',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(amount);
};

interface PatternManagementScreenProps {
    patterns: Pattern[];
    setPatterns: React.Dispatch<React.SetStateAction<Pattern[]>>;
    settings: Settings;
}

const PatternManagementScreen: React.FC<PatternManagementScreenProps> = ({ patterns, setPatterns, settings }) => {
    const [isAdding, setIsAdding] = useState(false);
    const [newPatternName, setNewPatternName] = useState('');
    const [newPatternPrice, setNewPatternPrice] = useState('');
    const [newPatternRhinestones, setNewPatternRhinestones] = useState('');
    const [newPatternImage, setNewPatternImage] = useState<string | null>(null);
    const [newPatternRhinestoneId, setNewPatternRhinestoneId] = useState('');
    const [patternToDelete, setPatternToDelete] = useState<string | null>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0]);
                setNewPatternImage(base64);
            } catch (error) {
                console.error("Error compressing and encoding image:", error);
            }
        }
    };

    const handleAddPattern = (e: React.FormEvent) => {
        e.preventDefault();
        const price = parseFloat(newPatternPrice);
        const rhinestones = parseFloat(newPatternRhinestones);
        if (newPatternName.trim() === '' || isNaN(price) || price < 0 || isNaN(rhinestones) || rhinestones < 0) return;

        const newPattern: Pattern = {
            id: Date.now().toString(),
            name: newPatternName.trim(),
            pricePerMeter: price,
            rhinestonesPerMeter: rhinestones,
            image: newPatternImage || undefined,
            defaultRhinestoneId: newPatternRhinestoneId || undefined,
        };

        setPatterns(prev => [newPattern, ...prev]);
        setNewPatternName('');
        setNewPatternPrice('');
        setNewPatternImage(null);
        setNewPatternRhinestones('');
        setNewPatternRhinestoneId('');
        setIsAdding(false);
    };

    const handleDeleteRequest = (patternId: string) => {
        setPatternToDelete(patternId);
    };

    const handleConfirmDelete = () => {
        if (!patternToDelete) return;
        setPatterns(prev => prev.filter(p => p.id !== patternToDelete));
        setPatternToDelete(null);
    };

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-teal-400">Kalıp Yönetimi</h2>
                <button onClick={() => setIsAdding(!isAdding)} className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                    <PlusIcon /> {isAdding ? 'İptal' : 'Yeni Kalıp'}
                </button>
            </div>

            {isAdding && (
                <form onSubmit={handleAddPattern} className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-4">
                    <input type="text" value={newPatternName} onChange={(e) => setNewPatternName(e.target.value)} placeholder="Kalıp Adı" className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none" required autoFocus />
                    <input type="number" step="0.01" value={newPatternPrice} onChange={(e) => setNewPatternPrice(e.target.value)} placeholder="Metre Başına Baskı Fiyatı (Taş Hariç)" className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                    <input type="number" step="0.01" value={newPatternRhinestones} onChange={(e) => setNewPatternRhinestones(e.target.value)} placeholder="Metre Başına Taş Sarfiyatı (Gross)" className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none" required />
                    <div>
                        <label htmlFor="defaultRhinestone" className="block text-sm font-medium text-gray-400 mb-1">Varsayılan Taş Türü (İsteğe Bağlı)</label>
                        <select id="defaultRhinestone" value={newPatternRhinestoneId} onChange={e => setNewPatternRhinestoneId(e.target.value)} className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none">
                            <option value="">Taş Yok</option>
                            {settings.rhinestones.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-400 mb-2">Kalıp Resmi (İsteğe Bağlı)</label>
                        <input type="file" accept="image/*" onChange={handleImageUpload} className="w-full text-sm text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-teal-600 file:text-white hover:file:bg-teal-500" />
                    </div>
                    {newPatternImage && <img src={newPatternImage} alt="Kalıp Önizleme" className="mt-2 rounded-lg max-h-40 mx-auto" />}
