            ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                    {patterns.map(pattern => {
                        const rhinestone = settings.rhinestones.find(r => r.id === pattern.defaultRhinestoneId);
                        return (
                            <div key={pattern.id} className="bg-gray-800 rounded-lg shadow-md overflow-hidden relative group">
