                                    <button onClick={() => handleDeleteRequest(pattern.id)} className="p-1.5 bg-red-600/80 hover:bg-red-500 rounded-full text-white" aria-label="Kalıbı Sil">
                                        <TrashIcon />
                                    </button>
                                </div>
                                <img src={pattern.image || `https://via.placeholder.com/150/4B5563/FFFFFF?text=${encodeURIComponent(pattern.name)}`} alt={pattern.name} className="w-full h-32 object-cover bg-gray-700" />
