                                    <h3 className="font-semibold text-gray-200 truncate">{pattern.name}</h3>
                                    <p className="text-teal-400">{formatCurrency(pattern.pricePerMeter)} / m <span className="text-xs text-gray-400">(Baskı)</span></p>
                                    <p className="text-xs text-gray-400">{pattern.rhinestonesPerMeter} Gross / m {rhinestone ? `(${rhinestone.name})` : ''}</p>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            <ConfirmationModal isOpen={!!patternToDelete} onClose={() => setPatternToDelete(null)} onConfirm={handleConfirmDelete} title="Kalıbı Silmeyi Onayla" settings={settings}>
                <p>Bu kalıbı kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p>
            </ConfirmationModal>
        </div>
    );
};

