                                <div className="w-11 h-6 bg-gray-600 rounded-full peer peer-focus:ring-2 peer-focus:ring-teal-800 peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-0.5 after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-teal-600"></div>
                            </div>
                        </div>
                        {formState.requirePasswordForDelete && (
                            <InputField name="confirmationPassword" label="Onay Şifresi" description="Silme işlemleri için kullanılacak şifre." value={formState.confirmationPassword} onChange={handleTextChange} type="text" />
                        )}
                    </div>
                );
            default: return null;
        }
    }


    return (
        <div>
            {toastInfo && <Toast message={toastInfo.message} type={toastInfo.type} show={!!toastInfo} onClose={() => setToastInfo(null)} />}
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-teal-400">Genel Ayarlar</h2>
                <button form="settings-form" type="submit" className="px-5 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">
                    Kaydet
                </button>
            </div>
             <form id="settings-form" onSubmit={handleSubmit} className="flex flex-col md:flex-row gap-6">
                <aside className="flex flex-row md:flex-col gap-2 md:w-16 flex-wrap">
                    <IconNavButton label="Firma Bilgileri" icon={<BuildingIcon />} isActive={activeTab === 'company'} onClick={() => setActiveTab('company')} />
                    <IconNavButton label="Maliyet Ayarları" icon={<CalculatorIcon />} isActive={activeTab === 'costs'} onClick={() => setActiveTab('costs')} />
                    <IconNavButton label="Taş Yönetimi" icon={<GemIcon />} isActive={activeTab === 'rhinestones'} onClick={() => setActiveTab('rhinestones')} />
                    <IconNavButton label="Kalıp Yönetimi" icon={<PatternIcon />} isActive={activeTab === 'patterns'} onClick={() => setActiveTab('patterns')} />
                    <IconNavButton label="Hesaplama Ayarları" icon={<ClockIcon />} isActive={activeTab === 'calculations'} onClick={() => setActiveTab('calculations')} />
                    <IconNavButton label="Asistan Ayarları" icon={<BellIcon />} isActive={activeTab === 'assistant'} onClick={() => setActiveTab('assistant')} />
                    <IconNavButton label="Güvenlik Ayarları" icon={<ShieldIcon />} isActive={activeTab === 'security'} onClick={() => setActiveTab('security')} />
                </aside>
                <div className="flex-grow bg-gray-800 rounded-lg shadow-lg p-6">
                    {renderContent()}
                </div>
            </form>
        </div>
    );
};

export default SettingsScreen;

import React, { useState } from 'react';
import type { Pattern, Settings } from '../types';
import { PlusIcon, TrashIcon } from './Icons';
import ConfirmationModal from './ConfirmationModal';

const compressAndEncodeImage = (file: File, maxDimension: number = 800, quality: number = 0.7): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            if (!event.target?.result) {
                return reject(new Error("FileReader failed to read file."));
            }
            const img = new Image();
            img.src = event.target.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let { width, height } = img;

                if (width > height) {
                    if (width > maxDimension) {
                        height = Math.round((height * maxDimension) / width);
                        width = maxDimension;
                    }
                } else {
                    if (height > maxDimension) {
                        width = Math.round((width * maxDimension) / height);
                        height = maxDimension;
                    }
                }

                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    return reject(new Error('Could not get 2D context from canvas.'));
                }
                ctx.drawImage(img, 0, 0, width, height);

                const dataUrl = canvas.toDataURL('image/jpeg', quality);
                resolve(dataUrl);
            };
            img.onerror = (err) => reject(err);
        };
        reader.onerror = (err) => reject(err);
    });
};

const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('tr-TR', {
        style: 'decimal',
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
    }).format(amount);
};

interface PatternManagementScreenProps {
    patterns: Pattern[];
    setPatterns: React.Dispatch<React.SetStateAction<Pattern[]>>;
    settings: Settings;
}

const PatternManagementScreen: React.FC<PatternManagementScreenProps> = ({ patterns, setPatterns, settings }) => {
    const [isAdding, setIsAdding] = useState(false);
    const [newPatternName, setNewPatternName] = useState('');
    const [newPatternPrice, setNewPatternPrice] = useState('');
    const [newPatternRhinestones, setNewPatternRhinestones] = useState('');
    const [newPatternImage, setNewPatternImage] = useState<string | null>(null);
    const [newPatternRhinestoneId, setNewPatternRhinestoneId] = useState('');
    const [patternToDelete, setPatternToDelete] = useState<string | null>(null);

    const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            try {
                const base64 = await compressAndEncodeImage(e.target.files[0]);
                setNewPatternImage(base64);
            } catch (error) {
                console.error("Error compressing and encoding image:", error);
            }
        }
    };

    const handleAddPattern = () => {
        const price = parseFloat(newPatternPrice);
        const rhinestones = parseFloat(newPatternRhinestones);
        if (newPatternName.trim() === '' || isNaN(price) || price < 0 || isNaN(rhinestones) || rhinestones < 0) {
            alert("Lütfen tüm kalıp bilgilerini geçerli şekilde girin.");
            return;
        }

        const newPattern: Pattern = {
            id: Date.now().toString(),
            name: newPatternName.trim(),
            pricePerMeter: price,
            rhinestonesPerMeter: rhinestones,
            image: newPatternImage || undefined,
            defaultRhinestoneId: newPatternRhinestoneId || undefined,
        };

        setPatterns(prev => [newPattern, ...prev]);
        setNewPatternName('');
        setNewPatternPrice('');
        setNewPatternImage(null);
        setNewPatternRhinestones('');
        setNewPatternRhinestoneId('');
        setIsAdding(false);
    };

    const handleDeleteRequest = (patternId: string) => {
        setPatternToDelete(patternId);
    };

    const handleConfirmDelete = () => {
        if (!patternToDelete) return;
        setPatterns(prev => prev.filter(p => p.id !== patternToDelete));
        setPatternToDelete(null);
    };

    return (
        <div>
            <div className="flex justify-between items-center mb-6">
                <h2 className="text-2xl font-bold text-teal-400">Kalıp Yönetimi</h2>
                <button onClick={() => setIsAdding(!isAdding)} className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-500 transition-colors">
                    <PlusIcon /> {isAdding ? 'İptal' : 'Yeni Kalıp'}
                </button>
            </div>

            {isAdding && (
                <div className="p-4 bg-gray-800 rounded-lg shadow-lg mb-6 space-y-4">
                    <input type="text" value={newPatternName} onChange={(e) => setNewPatternName(e.target.value)} placeholder="Kalıp Adı" className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none" autoFocus />
                    <input type="number" step="0.01" value={newPatternPrice} onChange={(e) => setNewPatternPrice(e.target.value)} placeholder="Metre Başına Baskı Fiyatı (Taş Hariç)" className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <input type="number" step="0.01" value={newPatternRhinestones} onChange={(e) => setNewPatternRhinestones(e.target.value)} placeholder="Metre Başına Taş Sarfiyatı (Gross)" className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none" />
                    <div>
                        <label htmlFor="defaultRhinestone" className="block text-sm font-medium text-gray-400 mb-1">Varsayılan Taş Türü (İsteğe Bağlı)</label>
                        <select id="defaultRhinestone" value={newPatternRhinestoneId} onChange={e => setNewPatternRhinestoneId(e.target.value)} className="w-full bg-gray-700 text-gray-200 rounded-md p-3 focus:ring-2 focus:ring-teal-500 focus:outline-none">
                            <option value="">Taş Yok</option>
                            {settings.rhinestones.map(r => <option key={r.id} value={r.id}>{r.name}</option>)}
                        </select>
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-gray-400 mb-2">Kalıp Resmi (İsteğe Bağlı)</label>
                        <input type="file" accept="image/*" onChange={handleImageUpload} className="w-full text-sm text-gray-400 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-teal-600 file:text-white hover:file:bg-teal-500" />
                    </div>
                    {newPatternImage && <img src={newPatternImage} alt="Kalıp Önizleme" className="mt-2 rounded-lg max-h-40 mx-auto" />}
                    <div className="flex justify-end">
                        <button type="button" onClick={handleAddPattern} className="px-4 py-2 bg-teal-600 text-white font-semibold rounded-lg hover:bg-teal-500 transition-colors">Kalıp Ekle</button>
                    </div>
                </div>
            )}

            {patterns.length === 0 && !isAdding ? (
                <p className="text-gray-500 text-center py-4">Henüz kalıp eklenmemiş.</p>
            ) : (
                <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                    {patterns.map(pattern => {
                        const rhinestone = settings.rhinestones.find(r => r.id === pattern.defaultRhinestoneId);
                        return (
                            <div key={pattern.id} className="bg-gray-800 rounded-lg shadow-md overflow-hidden relative group">
                                <div className="absolute top-2 right-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity">
                                    <button onClick={() => handleDeleteRequest(pattern.id)} className="p-1.5 bg-red-600/80 hover:bg-red-500 rounded-full text-white" aria-label="Kalıbı Sil">
                                        <TrashIcon />
                                    </button>
                                </div>
                                <img src={pattern.image || `https://via.placeholder.com/150/4B5563/FFFFFF?text=${encodeURIComponent(pattern.name)}`} alt={pattern.name} className="w-full h-32 object-cover bg-gray-700" />
                                <div className="p-3">
                                    <h3 className="font-semibold text-gray-200 truncate">{pattern.name}</h3>
                                    <p className="text-teal-400">{formatCurrency(pattern.pricePerMeter)} / m <span className="text-xs text-gray-400">(Baskı)</span></p>
                                    <p className="text-xs text-gray-400">{pattern.rhinestonesPerMeter} Gross / m {rhinestone ? `(${rhinestone.name})` : ''}</p>
                                </div>
                            </div>
                        );
                    })}
                </div>
            )}

            <ConfirmationModal isOpen={!!patternToDelete} onClose={() => setPatternToDelete(null)} onConfirm={handleConfirmDelete} title="Kalıbı Silmeyi Onayla" settings={settings}>
                <p>Bu kalıbı kalıcı olarak silmek istediğinizden emin misiniz? Bu işlem geri alınamaz.</p>
            </ConfirmationModal>
        </div>
    );
};

export default PatternManagementScreen;
